local function IsDualGapAirEcoBrain(aiBrain)
    return aiBrain and (aiBrain.AiBotDualGapRole == 'top_air'
            or aiBrain.AiBotDualGapRole == 'bottom_air'
            or aiBrain.AiBotDualGapRole == 'eco')
end

local function GetOwnMassStorageCountAroundMex(aiBrain, oMex)
    if not(AiBotUnitInfo.IsUnitValid(oMex)) or oMex:GetAIBrain() ~= aiBrain then return 0 end
    local tMexPosition = oMex:GetPosition()
    local tiXZOffset = {{-2,0},{0,-2},{0,2},{2,0}}
    local iCount = 0
    --Count only the four real adjacency cells. A broad radius incorrectly
    --counted storages belonging to neighbouring mexes in the tight Gap grid.
    for _, tXZOffset in tiXZOffset do
        local tSlot = {tMexPosition[1] + tXZOffset[1], tMexPosition[2], tMexPosition[3] + tXZOffset[2]}
        local tStorageAtSlot = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMassStorage, tSlot, 0.9, 'Ally') or {}
        for _, oStorage in tStorageAtSlot do
            if AiBotUnitInfo.IsUnitValid(oStorage) and oStorage:GetAIBrain() == aiBrain then
                iCount = iCount + 1
                break
            end
        end
    end
    return iCount
end

function HasUncappedDualGapT3Mex(aiBrain)
    if not(IsDualGapAirEcoBrain(aiBrain)) then return false end
    local tT3Mexes = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3, false) or {}
    for _, oMex in tT3Mexes do
        if AiBotUnitInfo.IsUnitValid(oMex) and oMex:GetFractionComplete() == 1
                and GetOwnMassStorageCountAroundMex(aiBrain, oMex) < 4 then
            return true
        end
    end
    return false
end

local function GetDualGapPriorityUpgradeTarget(aiBrain)
    local tMexes = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryMex * (categories.TECH1 + categories.TECH2), false) or {}
    local oBestMex
    local iBestMexProgress = -1
    for _, oMex in tMexes do
        if AiBotUnitInfo.IsUnitValid(oMex) and oMex:IsUnitState('Upgrading') then
            local iProgress = oMex:GetWorkProgress() or 0
            if iProgress > iBestMexProgress then
                oBestMex = oMex
                iBestMexProgress = iProgress
            end
        end
    end

    --Finish the first four T2 mexes before committing most build power to
    --the air HQ. Once that income exists, the air HQ becomes the phase goal.
    local iCompletedT2PlusMexes = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * (categories.TECH2 + categories.TECH3))
    if iCompletedT2PlusMexes < 4 and oBestMex then return oBestMex end

    local tAirFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory, false) or {}
    local oBestAirFactory
    local iBestAirProgress = -1
    for _, oFactory in tAirFactories do
        if AiBotUnitInfo.IsUnitValid(oFactory) and oFactory:IsUnitState('Upgrading') then
            local iProgress = oFactory:GetWorkProgress() or 0
            if iProgress > iBestAirProgress then
                oBestAirFactory = oFactory
                iBestAirProgress = iProgress
            end
        end
    end
    return oBestAirFactory or oBestMex
end

local function GetDualGapStorageTarget(aiBrain)
    local tMexes = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryMex * (categories.TECH2 + categories.TECH3), false) or {}
    local oAirFactory
    local bT3AirPhase = false
    local tAirFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory, false) or {}
    for _, oFactory in tAirFactories do
        if AiBotUnitInfo.IsUnitValid(oFactory) then
            if not(oAirFactory) or AiBotUnitInfo.GetUnitTechLevel(oFactory) > AiBotUnitInfo.GetUnitTechLevel(oAirFactory) then
                oAirFactory = oFactory
            end
            if AiBotUnitInfo.GetUnitTechLevel(oFactory) >= 3
                    or (AiBotUnitInfo.GetUnitTechLevel(oFactory) == 2 and oFactory:IsUnitState('Upgrading')) then
                bT3AirPhase = true
            end
        end
    end

    local oMissingT3Storage
    local oMissingT2Storage
    local iNearestT2Distance = 100000
    local iCappedT2Plus = 0
    for _, oMex in tMexes do
        if AiBotUnitInfo.IsUnitValid(oMex) and oMex:GetFractionComplete() == 1 then
            local iStorageCount = GetOwnMassStorageCountAroundMex(aiBrain, oMex)
            if iStorageCount >= 4 then
                iCappedT2Plus = iCappedT2Plus + 1
            elseif AiBotUnitInfo.GetUnitTechLevel(oMex) == 3 then
                oMissingT3Storage = oMex
                break
            elseif bT3AirPhase and oAirFactory then
                local iDistance = AiBotUtilities.GetDistanceBetweenPositions(oMex:GetPosition(), oAirFactory:GetPosition())
                if iDistance < iNearestT2Distance then
                    iNearestT2Distance = iDistance
                    oMissingT2Storage = oMex
                end
            end
        end
    end
    if oMissingT3Storage then return oMissingT3Storage end
    if bT3AirPhase and iCappedT2Plus < 4 then return oMissingT2Storage end
    return nil
end

local function DualGapEconomyPriorityManager(aiBrain)
    while IsDualGapAirEcoBrain(aiBrain) and not(aiBrain:IsDefeated()) and not(aiBrain.AiBotIsDefeated) do
        local iNow = GetGameTimeSeconds()
        local oStorageTarget = GetDualGapStorageTarget(aiBrain)
        if oStorageTarget and (oStorageTarget.AiBotDualGapStorageDispatchUntil or 0) <= iNow then
            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oStorageTarget:GetPosition(), true, aiBrain.AiBotTeam)
            if tLZOrWZData and tLZOrWZTeamData then
                BuildMassStorageAroundMexDueToCompletion(oStorageTarget, nil, tLZOrWZData, tLZOrWZTeamData)
            end
        end

        local oTarget = GetDualGapPriorityUpgradeTarget(aiBrain)
        if AiBotUnitInfo.IsUnitValid(oTarget) and oTarget:IsUnitState('Upgrading')
                and (aiBrain.AiBotDualGapPriorityTarget ~= oTarget
                    or iNow - (aiBrain.AiBotDualGapPriorityRefreshTime or -100) >= 10) then
            local tEngineers = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer * (categories.TECH1 + categories.TECH2 + categories.TECH3), false) or {}
            local iWanted = math.max(1, math.floor(table.getn(tEngineers) * 0.7))
            local iAssigned = 0
            for _, oEngineer in tEngineers do
                if iAssigned >= iWanted then break end
                if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer:GetFractionComplete() == 1
                        and not(EntityCategoryContains(categories.COMMAND, oEngineer.UnitId))
                        and not(oEngineer:IsUnitState('Attached'))
                        and (oEngineer.AiBotDualGapStorageWorkerUntil or 0) <= iNow then
                    AiBotOrders.IssueTrackedGuard(oEngineer, oTarget, false, 'DGPriorityUpgrade', true)
                    iAssigned = iAssigned + 1
                end
            end
            aiBrain.AiBotDualGapPriorityTarget = oTarget
            aiBrain.AiBotDualGapPriorityRefreshTime = iNow
            LOG('AiBot Dual Gap priority manager: army='..aiBrain:GetArmyIndex()
                    ..'; target='..oTarget.UnitId..'; progress='..tostring(oTarget:GetWorkProgress() or 0)
                    ..'; engineers='..iAssigned..'; time='..iNow)
        elseif not(AiBotUnitInfo.IsUnitValid(oTarget)) then
            aiBrain.AiBotDualGapPriorityTarget = nil
        end
        WaitSeconds(2)
    end
    aiBrain.AiBotDualGapEconomyManagerActive = false
end

function EnsureDualGapEconomyManager(aiBrain)
    if IsDualGapAirEcoBrain(aiBrain) and not(aiBrain.AiBotDualGapEconomyManagerActive) then
        aiBrain.AiBotDualGapEconomyManagerActive = true
        ForkThread(DualGapEconomyPriorityManager, aiBrain)
    end
end

local function ForceDualGapPriorityUpgradeAssist(oTarget)
    if AiBotUnitInfo.IsUnitValid(oTarget) then
        EnsureDualGapEconomyManager(oTarget:GetAIBrain())
    end
end

function UpgradeUnit(oUnitToUpgrade, bUpdateUpgradeTracker, iOptionalWait)
    --Work out the upgrade ID wanted; if bUpdateUpgradeTracker is true then records upgrade against unit's aiBrain
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpgradeUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oUpgradeBrain = oUnitToUpgrade:GetAIBrain()
    local bDualGapAirEcoUpgradeRole = oUpgradeBrain and (oUpgradeBrain.AiBotDualGapRole == 'top_air'
            or oUpgradeBrain.AiBotDualGapRole == 'bottom_air'
            or oUpgradeBrain.AiBotDualGapRole == 'eco')
    if bDualGapAirEcoUpgradeRole then EnsureDualGapEconomyManager(oUpgradeBrain) end
    if bDualGapAirEcoUpgradeRole
            and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnitToUpgrade.UnitId) then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    end

    -- Hard phase gate for the DualGap air/eco opening.  Every mex-upgrade
    -- route eventually comes through this function, so generic economy and
    -- engineer schedulers cannot spend the strat reserve on T2 -> T3 mexes.
    -- T1 -> T2 remains available while the air HQ upgrades in parallel.
    if AiBotUnitInfo.IsUnitValid(oUnitToUpgrade)
            and EntityCategoryContains(AiBotUnitInfo.refCategoryMex * categories.TECH2, oUnitToUpgrade.UnitId) then
        local aiBrain = oUnitToUpgrade:GetAIBrain()
        local bDualGapAirEcoRole = aiBrain.AiBotDualGapRole == 'top_air'
                or aiBrain.AiBotDualGapRole == 'bottom_air'
                or aiBrain.AiBotDualGapRole == 'eco'
        if bDualGapAirEcoRole
                and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryBomber * categories.TECH3) == 0 then
            if not aiBrain.AiBotDualGapT3MexGateLogTime
                    or GetGameTimeSeconds() - aiBrain.AiBotDualGapT3MexGateLogTime >= 30 then
                LOG('AiBot Dual Gap T3 mex blocked until first strat: army='..aiBrain:GetArmyIndex()
                        ..'; role='..aiBrain.AiBotDualGapRole..'; time='..GetGameTimeSeconds())
                aiBrain.AiBotDualGapT3MexGateLogTime = GetGameTimeSeconds()
            end
            ForkThread(ConsiderFutureMexUpgrade, oUnitToUpgrade, 20)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        end
        if bDualGapAirEcoRole and HasUncappedDualGapT3Mex(aiBrain) then
            ForkThread(ConsiderFutureMexUpgrade, oUnitToUpgrade, 12)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        end
        if bDualGapAirEcoRole then
            local tOwnT2Mexes = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryMex * categories.TECH2, false) or {}
            for _, oOtherMex in tOwnT2Mexes do
                if oOtherMex ~= oUnitToUpgrade and AiBotUnitInfo.IsUnitValid(oOtherMex)
                        and oOtherMex:IsUnitState('Upgrading') then
                    ForkThread(ConsiderFutureMexUpgrade, oUnitToUpgrade, 12)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return false
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnitToUpgrade='..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)..' owned by '..oUnitToUpgrade:GetAIBrain().Nickname..'; GetUnitUpgradeBlueprint='..reprs((AiBotUnitInfo.GetUnitUpgradeBlueprint(oUnitToUpgrade, true) or 'nil'))..'; bUpdateUpgradeTracker='..tostring((bUpdateUpgradeTracker or false))..'; unit brain='..oUnitToUpgrade:GetAIBrain().Nickname..'; Are we in T1 spam mode='..tostring(AiBotTeam.tTeamData[oUnitToUpgrade:GetAIBrain().AiBotTeam][AiBotTeam.refbFocusOnT1Spam])..'; Unit enhancement upgrade count='..(oUnitToUpgrade[AiBotACU.refiUpgradeCount] or 'nil')..'; refbTriedUpgrading='..tostring(oUnitToUpgrade[AiBotUnitInfo.refbTriedUpgrading] or false)..'; refbObjectiveUnit='..tostring(oUnitToUpgrade[AiBotUnitInfo.refbObjectiveUnit] or false)..'; Is oUnitToUpgrade.EventCallbacks.OnKilled nil='..tostring(oUnitToUpgrade.EventCallbacks.OnKilled == nil)..'; iOptionalWait='..(iOptionalWait or 'nil')) end
    local bContinue = true
    if oUnitToUpgrade.CanBuild then
        if iOptionalWait and iOptionalWait > 0 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iOptionalWait)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        --Campaign specific - dont upgrade a campaign objective unit if it doesnt have an active OnKilled callback
        if oUnitToUpgrade[AiBotUnitInfo.refbObjectiveUnit] and AiBotMap.bIsCampaignMap and not(oUnitToUpgrade.EventCallbacks.OnKilled) then
            if bDebugMessages == true then LOG(sFunctionRef..': Wont upgrade afterall as we might break a campaign objective') end
            AiBotUtilities.ErrorHandler('Aborting upgrade of unit '..oUnitToUpgrade.UnitId..' as it might be a campaign objective unit', true, false)
            bContinue = false
        end
    else
        bContinue = false
        AiBotUtilities.ErrorHandler('Wanted to upgrade unit '..oUnitToUpgrade.UnitId..' but .CanBuild isnt true')
    end
    if bContinue then
        --Do we have any HQs of the same factory type of a higher tech level?
        local sUpgradeID = AiBotUnitInfo.GetUnitUpgradeBlueprint(oUnitToUpgrade, true) --If not a factory or dont recognise the faction then just returns the normal unit ID
        --Redundancy if unit is capable of upgrading but the CanBuild check fails
        if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeID after trying GetUnitUpgradeBlueprint='..(sUpgradeID or 'nil')..'; refbTriedIgnoringCanBuildForUpgrade='..tostring(oUnitToUpgrade[refbTriedIgnoringCanBuildForUpgrade] or false)) end
        if not(sUpgradeID) and not(oUnitToUpgrade[refbTriedIgnoringCanBuildForUpgrade]) then
            oUnitToUpgrade[refbTriedIgnoringCanBuildForUpgrade] = true
            sUpgradeID = oUnitToUpgrade:GetBlueprint().General.UpgradesTo
        end

        if sUpgradeID and AiBotUnitInfo.IsUnitValid(oUnitToUpgrade) then
            local bDelayedUpgradeTrackingCheck = false
            if bUpdateUpgradeTracker and AiBotOverseer.bUnitRestrictionsArePresent and not(oUnitToUpgrade:CanBuild(sUpgradeID)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Dont think we c an upgrade this unit due to unit restrictions, so wont update the upgrade tracking') end
                bDelayedUpgradeTrackingCheck = true
                bUpdateUpgradeTracker = false
            end
            local aiBrain = oUnitToUpgrade:GetAIBrain()
            if bDebugMessages == true then LOG(sFunctionRef..': About to issue ugprade to unit '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)..'; Current state='..AiBotUnitInfo.GetUnitState(oUnitToUpgrade)..'; Work progress='..(oUnitToUpgrade:GetWorkProgress() or 'nil')..'; Is unit upgrading='..tostring(oUnitToUpgrade:IsUnitState('Upgrading'))..'; Fraction complete='..oUnitToUpgrade:GetFractionComplete()..'; bDelayedUpgradeTrackingCheck='..tostring(bDelayedUpgradeTrackingCheck)..'; AiBotOverseer.bUnitRestrictionsArePresent='..tostring(AiBotOverseer.bUnitRestrictionsArePresent or false)..'; CanBuild check='..tostring(oUnitToUpgrade:CanBuild(sUpgradeID))) end

            if not(oUnitToUpgrade:IsUnitState('Upgrading')) then
                if not(oUnitToUpgrade:IsUnitState('BeingUpgraded')) then
                    local bAddToExistingQueue = true



                    --Factory specific - if work progress is <=5% then cancel so can do the upgrade
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnitToUpgrade.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Are upgrading a factory '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)..'; work progress='..oUnitToUpgrade:GetWorkProgress()) end
                        if oUnitToUpgrade.GetWorkProgress and oUnitToUpgrade:GetWorkProgress() <= 0.05 then
                            --Are we building an engineer or transport?
                            local oUnitThatAreBuilding = oUnitToUpgrade:GetFocusUnit()
                            if not(AiBotUnitInfo.IsUnitValid(oUnitThatAreBuilding) and EntityCategoryContains(AiBotUnitInfo.refCategoryTransport + AiBotUnitInfo.refCategoryEngineer, oUnitThatAreBuilding.UnitId)) then
                                bAddToExistingQueue = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Have barely started with current construction so will cancel so can get upgrade sooner') end
                            end
                        end
                    end

                    --Air factory upgrades - if we are upgrading from T1 to T2 and havent build a transport, and have plateaus, then want to get a transport first
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory * categories.TECH1, oUnitToUpgrade.UnitId) and aiBrain[refiOurHighestAirFactoryTech] == 1 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory * categories.TECH1) == 1 then
                        --Do we have locations for transports to drop?
                        if bDebugMessages == true then LOG(sFunctionRef..': Is island drop shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportIslandDropShortlist]))..'; Is table of far away same island zone shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist]))..'; Lifetime transport count='..AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryTransport)) end
                        if (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportIslandDropShortlist]) == false or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist]) == false) and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryTransport) == 0 then
                            local refbQueuedTransport = 'AiBotQueuedTransport'
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have already queued up transport for this unit='..tostring(oUnitToUpgrade[refbQueuedTransport] or false)..'; AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportIslandDropShortlist]='..repru(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportIslandDropShortlist])..'; AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist]='..repru(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist])) end

                            if not(oUnitToUpgrade[refbQueuedTransport]) then
                                --Havent built any transports yet so build a T1 transport before we upgrade to T2 air
                                --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,           oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                                local sTransportID = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryTransport, oUnitToUpgrade)
                                if sTransportID then
                                    oUnitToUpgrade[refbQueuedTransport] = true
                                    AiBotOrders.IssueTrackedFactoryBuild(oUnitToUpgrade, sTransportID, false, 'PreUp')
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will queue up a transport for factory '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)) end
                                end
                            end
                        end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory * categories.TECH2 + AiBotUnitInfo.refCategoryAirFactory * categories.TECH2, oUnitToUpgrade.UnitId) and aiBrain[refiOurHighestFactoryTechLevel] <= 2 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer - categories.TECH1) <= 5 then
                        --About to go for T3 factory but have hardl yany engineers so queue up an extra one
                        --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,                oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                        local sEngiID = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryEngineer, oUnitToUpgrade)
                        if sEngiID then
                            AiBotOrders.IssueTrackedFactoryBuild(oUnitToUpgrade, sEngiID, false, 'PreUp')
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': About to go to T3 on factory '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)..' but only have '..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer - categories.TECH1)..' T2 plus engis so will queue up another engi before the upgrade. sEngiID='..(sEngiID or 'nil')) end
                    end

                    --Issue upgrade
                    AiBotOrders.IssueTrackedUpgrade(oUnitToUpgrade, sUpgradeID, bAddToExistingQueue)
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory
                            + AiBotUnitInfo.refCategoryMex * categories.TECH2, oUnitToUpgrade.UnitId) then
                        ForkThread(ForceDualGapPriorityUpgradeAssist, oUnitToUpgrade)
                    end
                    --Issue where if we give the upgrade presumably just as the unit has finihsed its own upgrade, then it shows as beingupgrade while also being complete; so we wait 1 second and try again
                    --Only do below if bUpdateUpgradeTracker is true, to avoid infinite loop
                elseif oUnitToUpgrade:GetFractionComplete() == 1 and oUnitToUpgrade.CanBuild and bUpdateUpgradeTracker then
                    ForkThread(UpgradeUnit, oUnitToUpgrade, false, 1)
                end
            end

            --Clear any pausing of the unit
            AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(oUnitToUpgrade, false)
            --oUnitToUpgrade:SetPaused(false)
            --oUnitToUpgrade[AiBotUnitInfo.refbPaused] = false
            if bDebugMessages == true then LOG(sFunctionRef..': Just set paused to false for unit '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)) end

            if bUpdateUpgradeTracker then
                AiBotTeam.UpdateUpgradeTrackingOfUnit(oUnitToUpgrade, false, sUpgradeID)
            elseif bDelayedUpgradeTrackingCheck then
                --Will only update if in 2 ticks the unit state is that it is upgrading
                ForkThread(AiBotOrders.DelayedUpgradeTracking, oUnitToUpgrade, sUpgradeID)
            end
        else
            --Dont have an upgrade ID; if the unit has an UpgradesTo value in the blueprint and that unit is restricted, then dont show an error
            local sExpectedUpgradeID = oUnitToUpgrade:GetBlueprint().General.UpgradesTo
            if sExpectedUpgradeID and AiBotUnitInfo.IsUnitRestricted(sExpectedUpgradeID, oUnitToUpgrade:GetAIBrain():GetArmyIndex()) then
                --Restricted e.g. due to campaign or other settings
            elseif not(AiBotMap.bIsCampaignMap) then --on campaign had issue where could have t3 HQs but not be allowed to upgrade t2 support factory to t3, so have disabled error message on all campaign maps
                AiBotUtilities.ErrorHandler('Dont have a valid upgrade ID; UnitID=' .. (oUnitToUpgrade.UnitId or 'nil')..'; sExpectedUpgradeID='..(sExpectedUpgradeID or 'nil'))
                if bDebugMessages == true and sExpectedUpgradeID then
                    LOG(sFunctionRef..': oUnitToUpgrade:CanBuild(sExpectedUpgradeID)='..tostring(oUnitToUpgrade:CanBuild(sExpectedUpgradeID))..'; Cur T3 Air HQs='..oUnitToUpgrade:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryAirHQ*categories.TECH3)..'; Cur T3 land HQs='..oUnitToUpgrade:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryLandHQ*categories.TECH3))
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBestUnitToUpgrade(toPotentialUnits, bPrioritiseFactoryHQ)
    --Assumes have already checked units are valid/not upgrading and factored in whether safe or not already, so just need to do distance type check
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBestUnitToUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iClosestUnitToBase = 100000
    local oClosestUnitToBase
    local iCurModDist
    local sUnitToUpgradeTo
    for iUnit, oUnit in toPotentialUnits do
        iCurModDist = AiBotMap.GetModDistanceFromStart(oUnit:GetAIBrain(), oUnit:GetPosition(), false)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurModDist before adjust='..iCurModDist..'; iClosestUnitToBase='..iClosestUnitToBase..'; bPrioritiseFactoryHQ='..tostring(bPrioritiseFactoryHQ or false)..'; Unit upgrades to='..(oUnit:GetBlueprint().General.UpgradesTo or 'nil')..'; length of string='..string.len(sUnitToUpgradeTo or '')..'; Is UpgradesTo a blank string='..tostring(sUnitToUpgradeTo == '')) end
        if bPrioritiseFactoryHQ and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnit.UnitId)) then iCurModDist = iCurModDist + 1000 end
        if iCurModDist < iClosestUnitToBase then
            --Check it can upgrade
            sUnitToUpgradeTo = oUnit:GetBlueprint().General.UpgradesTo
            if sUnitToUpgradeTo and not(sUnitToUpgradeTo == '') and not(AiBotUnitInfo.IsUnitRestricted(sUnitToUpgradeTo, oUnit:GetAIBrain():GetArmyIndex())) then
                if bDebugMessages == true then LOG(sFunctionRef..': Updating oClosestUnitToBase to be this unit') end
                iClosestUnitToBase = iCurModDist
                oClosestUnitToBase = oUnit
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Best unit to upgrade was '..(oClosestUnitToBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToBase) or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oClosestUnitToBase
end

function UpdateZoneAiBotAllMexByTech(aiBrain, iPlateauOrZero, iLandOrWaterZone, oOptionalUnitThatDied, iOptionalWait)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateZoneAiBotAllMexByTech'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tLZOrWZTeamData
    local tLZOrWZData
    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam]
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
    end
    if iOptionalWait then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(iOptionalWait)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end

    local iOrigMexCount = 0
    --Redundancy for rare cases where we realise we have fewer mexes in the zone, but think there are no avaialble build locations
    if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech] then
        for iTech, iMexes in tLZOrWZTeamData[AiBotMap.subrefMexCountByTech] do
            iOrigMexCount = iOrigMexCount + iMexes
        end
    end

    tLZOrWZTeamData[AiBotMap.subrefMexCountByTech] = {[1]=0,[2]=0,[3]=0} --starting point
    if bDebugMessages == true then LOG(sFunctionRef..': Time of game='..GetGameTimeSeconds()..'; Is table of allied units for iPlateauOrZero '..iPlateauOrZero..' iLandOrWaterZone '..iLandOrWaterZone..' empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
    local iMexCount = 0
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tAllMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        --Update list of allied mex units in this LZ in case some of the mexes are dead now
        --UpdateUnitPositionsAndLandZone(aiBrain, tUnits, iTeam,    iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZOrWZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
        if iPlateauOrZero > 0 then
            AiBotLand.UpdateUnitPositionsAndLandZone(aiBrain, tAllMexes, aiBrain.AiBotTeam, iPlateauOrZero, iLandOrWaterZone,            false)
        else
            AiBotNavy.UpdateUnitPositionsAndWaterZone(aiBrain, tAllMexes, aiBrain.AiBotTeam, iLandOrWaterZone, false, false, tLZOrWZTeamData, false, false)
        end

        local tMexesByTech = {}
        tMexesByTech[1] = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex * categories.TECH1, tAllMexes)
        tMexesByTech[2] = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex * categories.TECH2, tAllMexes)
        tMexesByTech[3] = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex * categories.TECH3, tAllMexes)
        if bDebugMessages == true then LOG(sFunctionRef..': oOptionalUnitThatDied='..(oOptionalUnitThatDied.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalUnitThatDied) or 'nil')..'; Is tAllMexes empty='..tostring(AiBotUtilities.IsTableEmpty(tAllMexes))) end
        local tiRecordedMexPositionsXZ = {} --Finding issues with an upgrading mex that completes having both the original mex and the upgraded mex for a period of time; if are upgrading multiple in a zone at the same time, this can lead to too many mexes being recorded for brief moment
        for iTech = 3, 1, -1 do
            if bDebugMessages == true then LOG(sFunctionRef..': Updating for iTech='..iTech..'; Is table of mexes by tech empty='..tostring(AiBotUtilities.IsTableEmpty(tMexesByTech[iTech]))) end
            if AiBotUtilities.IsTableEmpty(tMexesByTech[iTech]) == false then
                for iMex, oCurMex in tMexesByTech[iTech] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Plateau='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; oCurMex='..oCurMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCurMex)..'; Unit state='..AiBotUnitInfo.GetUnitState(oCurMex)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oCurMex))..'; Position='..repru(oCurMex:GetPosition())..'; iTech='..iTech..'; iMexCount pre increase='..iMexCount..'; tLZOrWZTeamData[AiBotMap.subrefMexCountByTech] pre increase='..repru(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech])) end
                    if oCurMex:GetAIBrain().AiBotAI and AiBotUnitInfo.IsUnitValid(oCurMex) and oCurMex:GetFractionComplete() == 1 and not(oOptionalUnitThatDied == oCurMex) then
                        if iTech == 3 or not(tiRecordedMexPositionsXZ[oCurMex:GetPosition()[1]]) or not(tiRecordedMexPositionsXZ[oCurMex:GetPosition()[1]][oCurMex:GetPosition()[3]]) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding iMex '..iMex..'; oCurMex='..oCurMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCurMex)..' to mex count, Unit state='..AiBotUnitInfo.GetUnitState(oCurMex)..'; Position='..repru(oCurMex:GetPosition())) end
                            tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][iTech] = tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][iTech] + 1
                            if not(tiRecordedMexPositionsXZ[oCurMex:GetPosition()[1]]) then tiRecordedMexPositionsXZ[oCurMex:GetPosition()[1]] = {} end
                            tiRecordedMexPositionsXZ[oCurMex:GetPosition()[1]][oCurMex:GetPosition()[3]] = true
                            iMexCount = iMexCount + 1
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished updating mex count, tLZOrWZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech])..'; iMexCount='..iMexCount..'; Table size of mex locations for this LZ='..table.getn( AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZOrWZMexLocations])..'; iMexCount from this function='..iMexCount..'; iOptionalWait='..(iOptionalWait or 'nil')..'; tiRecordedMexPositionsXZ='..repru(tiRecordedMexPositionsXZ)) end
        --If have somehow ended up with more mexes than there are locations, then redo the check in 1 second
        if iMexCount > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false and iMexCount > table.getn( tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) then
            if (iOptionalWait or 0) >= 10 then
                --Mind games - has an extra mex in one of the zones, so dont show this error message on campaign maps
                if not(AiBotMap.bIsCampaignMap) then
                    AiBotUtilities.ErrorHandler('Somehow we have more mexes than we should even after waiting '..iOptionalWait..' first, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; iMexCount='..iMexCount..'; table.getn( tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations])='..table.getn( tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations])..'; tLZOrWZTeamData[AiBotMap.subrefMexCountByTech]: T1='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1]..';T2='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2]..'; T3='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3])
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Have an inconsistent number of mexes so will call this function again with a wait, time='..GetGameTimeSeconds()) end
            ForkThread(UpdateZoneAiBotAllMexByTech, aiBrain, iPlateauOrZero, iLandOrWaterZone, oOptionalUnitThatDied, 15)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking mex count by tech, iMexCount='..iMexCount..'; iOrigMexCount='..iOrigMexCount..'; Is table of unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) end
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) and (iMexCount < iOrigMexCount or (iMexCount == iOrigMexCount and iMexCount < tLZOrWZData[AiBotMap.subrefLZOrWZMexCount])) then
        --We have fewer mexes; unless this is because e.g. enemy has captured a mex, or due to a split second timing issue, this suggests a bug with mex tracking, so will re-check all unavailable locations in 1 sec
        if bDebugMessages == true then LOG(sFunctionRef..': Will manuall recheck unbuilt locations') end
        ForkThread(ManuallyRecheckUnbuiltMexLocationsInZone, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, 1)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManuallyRecheckUnbuiltMexLocationsInZone(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iWaitInSeconds)
    --Calll via forkthread when had unexpected mex result that in some cases might be valid but in others invalid
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManuallyRecheckUnbuiltMexLocationsInZone'

    WaitSeconds(iWaitInSeconds)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tMexLocations = tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] --same ref used for LZ and WZs
    if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; Is tMexLocations empty='..tostring(AiBotUtilities.IsTableEmpty(tMexLocations))..'; Is subrefMexUnbuiltLocations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))) end
    --Do we have unavailable build locations, but have mexes in the zone? (redundancy in case things have changed in iWaitInSeconds time; we shouldve only called this function if the team's mexes decreased but there were no available mex locations to build on)
    if AiBotUtilities.IsTableEmpty(tMexLocations) == false and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) then
        local bNoMexPresent
        for iMex, tMex in tMexLocations do
            local rRect = AiBotUtilities.GetRectAroundLocation(tMex, 0.49)
            local tUnitsInRect = GetUnitsInRect(rRect)
            bNoMexPresent = true
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iMex position='..iMex..'; tMex='..repru(tMex)..'; Are there units in a rectangle around this mex='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInRect))) end
            if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                for iUnit, oUnit in tUnitsInRect do
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have a mex near here, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; .Dead='..tostring(oUnit.Dead or false)) end
                        bNoMexPresent = false
                        break
                    end
                end
            end
            if bNoMexPresent then
                if not(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) then tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] = {} end
                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy, adding unbuilt mex location for P'..iPlateauOrZero..'Z'..iLandOrWaterZone..' at time='..GetGameTimeSeconds()..'; tMex='..repru(tMex)) end
                table.insert(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations], tMex)
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]='..repru(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateZoneAiBotMexByTechCount(oMexJustBuiltOrDied, bJustDied, iOptionalWait)
    --Call via fork thread on mex creation due to potential timing issue with an upgrading mex being destroyed and replaced with the new (upgraded) mex
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateZoneAiBotMexByTechCount'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if oMexJustBuiltOrDied.GetAIBrain then
        local aiBrain = oMexJustBuiltOrDied:GetAIBrain()
        if aiBrain.AiBotAI then
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oMexJustBuiltOrDied:GetPosition())
            --should be called whenever a mex is created or destroyed in a land zone; ideally call via fork thread so reduced risk of it being called inbetween a mex say upgrading from one to another and being claled before both the creation and destroy events have happened
            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; oMexJustBuiltOrDied='..(oMexJustBuiltOrDied.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oMexJustBuiltOrDied) or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Mex position='..repru(oMexJustBuiltOrDied:GetPosition())..'; iMapWaterHeight='..AiBotMap.iMapWaterHeight..'; iOptionalWait='..(iOptionalWait or 'nil')..'; bJustDied='..tostring(bJustDied or false)) end
            if (iLandOrWaterZone or 0) > 0 then
                if not(iOptionalWait) then
                    if bJustDied then
                        UpdateZoneAiBotAllMexByTech(aiBrain, iPlateauOrZero, iLandOrWaterZone, oMexJustBuiltOrDied)
                    else
                        UpdateZoneAiBotAllMexByTech(aiBrain, iPlateauOrZero, iLandOrWaterZone, nil)
                    end
                else
                    if bJustDied then
                        ForkThread(UpdateZoneAiBotAllMexByTech, aiBrain, iPlateauOrZero, iLandOrWaterZone, oMexJustBuiltOrDied, iOptionalWait)
                    else
                        ForkThread(UpdateZoneAiBotAllMexByTech, aiBrain, iPlateauOrZero, iLandOrWaterZone, nil, iOptionalWait)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function FindAndUpgradeUnitOfCategory(aiBrain, iCategoryWanted, iOptionalMinUnitsToHaveBuilt)
    --e.g. intended for upgrading factory HQs, subject to CheckIfNeedMoreEngineersOrSnipeUnitsBeforeUpgrading
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'FindAndUpgradeUnitOfCategory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tUnitsOfCategory = aiBrain:GetListOfUnits(iCategoryWanted, false, true)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for brain '..aiBrain.Nickname..'; is tUnitsOfCategory empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsOfCategory))..'; iOptionalMinUnitsToHaveBuilt='..(iOptionalMinUnitsToHaveBuilt or 'nil')) end
    if AiBotUtilities.IsTableEmpty(tUnitsOfCategory) == false then
        local tUnitsToSearch = {}
        local tUnsafeUnitsOfCategory = {}
        local iCurPlateau, iCurLZ
        for iUnit, oUnit in tUnitsOfCategory do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname..'; Do we want more engis before upgrading='..tostring(AiBotConditions.CheckIfNeedMoreEngineersOrSnipeUnitsBeforeUpgrading(oUnit))..'; Unit build count='.. oUnit[AiBotFactory.refiTotalBuildCount]) end
            if not(AiBotConditions.CheckIfNeedMoreEngineersOrSnipeUnitsBeforeUpgrading(oUnit)) then
                if oUnit:GetFractionComplete() == 1 and not(oUnit:IsUnitState('Upgrading')) and not(oUnit.Dead) and not(oUnit:IsUnitState('BeingUpgraded')) then
                    if not(iOptionalMinUnitsToHaveBuilt) or oUnit[AiBotFactory.refiTotalBuildCount] >= iOptionalMinUnitsToHaveBuilt then
                        --Are we in a safe land zone?
                        iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                        local tLZTeamData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLZ][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                        if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] then
                            table.insert(tUnsafeUnitsOfCategory, oUnit)
                        else
                            table.insert(tUnitsToSearch, oUnit)
                        end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnitsToSearch) then tUnitsToSearch = tUnsafeUnitsOfCategory end
        if AiBotUtilities.IsTableEmpty(tUnitsToSearch) == false then
            local iCurDist
            local iClosestDist = 100000
            local oClosestUnit
            if bDebugMessages == true then LOG(sFunctionRef..': About to consider '..table.getn(tUnitsToSearch)..' potential units to upgrade, will pick the closest one') end
            for iUnit, oUnit in tUnitsToSearch do
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()])
                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..(oUnit.UnitId or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; iCurDist='..iCurDist) end
                if iCurDist < iClosestDist then
                    iClosestDist = iCurDist
                    oClosestUnit = oUnit
                end
            end
            if oClosestUnit then
                if bDebugMessages == true then LOG(sFunctionRef..': WIll try and upgrade oClosestUnit '..oClosestUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit)..'; Fraction complete='..oClosestUnit:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oClosestUnit)) end
                UpgradeUnit(oClosestUnit, true) --Will queue up transport or engineer for factories as well as figuring out whether to upgrade a support factory or an HQ
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateFactoryCountForFactoryKilledOrBuilt(oFactory, bIsDead)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateFactoryCountForFactoryKilledOrBuilt'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iAdjust = 0
    local sTrackerRef = 'AiBotRecordedCount'
    if bIsDead then
        if oFactory[sTrackerRef] then
            iAdjust = -1
            oFactory[sTrackerRef] = false
        end
    else
        if not(oFactory[sTrackerRef]) then
            iAdjust = 1
            oFactory[sTrackerRef] = true
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start, Time='..GetGameTimeSeconds()..'; iAdjust='..iAdjust..'; bIsDead='..tostring(bIsDead or false)..'; oFactory='..(oFactory.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactory) or 'nil')) end
    if not(iAdjust == 0) then
        local iFactoryType, iFactoryCategory = AiBotUnitInfo.GetFactoryType(oFactory)
        if bDebugMessages == true then LOG(sFunctionRef..': iFactoryType='..iFactoryType..'; iTeam='..oFactory:GetAIBrain().AiBotTeam..'; Brain='..oFactory:GetAIBrain().Nickname..'; Team factory count by type before update='..(AiBotTeam.tTeamData[oFactory:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTotalFactoryCountByType][iFactoryType] or 'nil')) end
        AiBotTeam.tTeamData[oFactory:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTotalFactoryCountByType][iFactoryType] = math.max(0, AiBotTeam.tTeamData[oFactory:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTotalFactoryCountByType][iFactoryType] + iAdjust)
        if bDebugMessages == true then LOG(sFunctionRef..': Factory count after update='..AiBotTeam.tTeamData[oFactory:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTotalFactoryCountByType][iFactoryType]) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateHighestFactoryTechLevelForBuiltUnit(oUnitJustBuilt)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateHighestFactoryTechLevelForBuiltUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Checking if just built a factory HQ, Have just built unit '..oUnitJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitJustBuilt)..'; Fraction complete='..oUnitJustBuilt:GetFractionComplete()..'; Is it a factory HQ='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnitJustBuilt.UnitId))) end

    --Update total factory count


    if oUnitJustBuilt:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway, oUnitJustBuilt.UnitId) then
        --Update factory count
        if bDebugMessages == true then LOG(sFunctionRef..': Just built factory or gateway, if we have built an HQ then will run more code') end
        UpdateFactoryCountForFactoryKilledOrBuilt(oUnitJustBuilt, false)
        --Plateau factory - set flag to not pause if it's the first factory
        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnitJustBuilt.UnitId) then
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnitJustBuilt:GetPosition())
            if iPlateau and iLandZone then
                local aiBrain = oUnitJustBuilt:GetAIBrain()
                local iTeam = aiBrain.AiBotTeam
                local tFactoryLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                local tFactoryLZTeamData = tFactoryLZData[AiBotMap.subrefLZTeamData][iTeam]
                --Are we in the same island as a friendly start position?
                local bHaveStartInSameIslandOrLOUD = false
                if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau]) == false then
                    for iStartLandZone, _ in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau] do
                        local tStartLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iStartLandZone]
                        if tStartLZData[AiBotMap.subrefLZIslandRef] == tFactoryLZData[AiBotMap.subrefLZIslandRef] then
                            bHaveStartInSameIslandOrLOUD = true
                            break
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Just built land fac '..oUnitJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitJustBuilt)..' in P'..iPlateau..'Z'..iLandZone..'; bHaveStartInSameIslandOrLOUD='..tostring(bHaveStartInSameIslandOrLOUD)) end
                if not(bHaveStartInSameIslandOrLOUD) then
                    local bHaveOtherFactoriesOfSameTech = false
                    if AiBotUtilities.IsTableEmpty(tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local iFactoryTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnitJustBuilt)
                        local iSearchCategory
                        if iFactoryTechLevel == 1 then iSearchCategory = AiBotUnitInfo.refCategoryLandFactory
                        elseif iFactoryTechLevel == 2 then iSearchCategory = AiBotUnitInfo.refCategoryLandFactory - categories.TECH1
                        else iSearchCategory = AiBotUnitInfo.refCategoryLandFactory * categories.TECH3
                        end

                        local tFactoriesOfSameTech = EntityCategoryFilterDown(iSearchCategory, tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tFactoriesOfSameTech) == false then
                            for iExistingFactory, oExistingFactory in tFactoriesOfSameTech do
                                if AiBotUnitInfo.IsUnitValid(oExistingFactory) and not(oExistingFactory == oUnitJustBuilt) and oExistingFactory:GetFractionComplete() == 1 then
                                    bHaveOtherFactoriesOfSameTech = true
                                    break
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bHaveOtherFactoriesOfSameTech='..tostring(bHaveOtherFactoriesOfSameTech)..'; Mex count for factory island='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tFactoryLZData[AiBotMap.subrefLZIslandRef]] or 0)..'; Mod dist%='..tFactoryLZTeamData[AiBotMap.refiModDistancePercent]) end
                    if not(bHaveOtherFactoriesOfSameTech) then
                        --Do we have enough mexes to warrant always building from this factory?
                        local bHaveEnoughMexes = false
                        if (tFactoryLZData[AiBotMap.subrefLZOrWZMexCount] or 0) >= 3 or (tFactoryLZData[AiBotMap.subrefLZIslandRef] and ((AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tFactoryLZData[AiBotMap.subrefLZIslandRef]] or 0) >= 7 or ((AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tFactoryLZData[AiBotMap.subrefLZIslandRef]] or 0) >= 5 and tFactoryLZTeamData[AiBotMap.refiModDistancePercent] >= 0.2))) or (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (tFactoryLZData[AiBotMap.subrefLZOrWZMexCount] or 0) >= 2 then
                            bHaveEnoughMexes = true
                        elseif AiBotUtilities.IsTableEmpty(tFactoryLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            local iNearbyMexCount = (tFactoryLZData[AiBotMap.subrefLZOrWZMexCount] or 0)
                            for _, iAdjLZ in tFactoryLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                iNearbyMexCount = iNearbyMexCount + (tAdjLZData[AiBotMap.subrefLZOrWZMexCount] or 0)
                            end
                            if iNearbyMexCount >= 4 then
                                bHaveEnoughMexes = true
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iNearbyMexCount='..iNearbyMexCount..'; bHaveEnoughMexes='..tostring(bHaveEnoughMexes)) end
                        end
                        if bHaveEnoughMexes then
                            --Set flag of any other factories in this zone to false
                            if AiBotUtilities.IsTableEmpty(tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                local tAllLandFacsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory, tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tAllLandFacsInZone) == false then
                                    for iFactory, oFactory in tAllLandFacsInZone do
                                        if not(oFactory == oUnitJustBuilt) then
                                            if (oFactory[AiBotACU.refiUpgradeCount] or 0) == 0 then
                                                oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = false
                                            end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Just set land factory '..oUnitJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitJustBuilt)..' to be the primary factory for P'..iPlateau..'Z'..iLandZone..'at time='..GetGameTimeSeconds()) end
                            oUnitJustBuilt[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true
                        end
                    end
                end
            end
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalHQ, oUnitJustBuilt.UnitId) then
            --Is this our highest naval fac HQ, and we lack any others of this tech level in this pond?
            local iTeam = oUnitJustBuilt:GetAIBrain().AiBotTeam
            if AiBotUnitInfo.GetUnitTechLevel(oUnitJustBuilt) >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] then
                local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnitJustBuilt:GetPosition())
                local iPond = AiBotMap.tPondBySegment[iSegmentX][iSegmentZ]
                if iPond then
                    if not(AiBotUnitInfo.IsUnitValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond])) then
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond]) then
                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory]) then
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory] = {}
                            end
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond] = {}
                        end
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refoPrimaryPondNavalFactory][iPond] = oUnitJustBuilt
                        oUnitJustBuilt[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true
                    end
                end
                --If owned by AiBotNavy and LC is <=2 then also make primary factory
                if oUnitJustBuilt:GetAIBrain()[AiBotOverseer.refbPrioritiseNavy] then oUnitJustBuilt[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true end
            end
            --Safe base - make air fac the primary fac
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirHQ, oUnitJustBuilt.UnitId) then
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnitJustBuilt:GetPosition())
            if iPlateau and iLandZone then
                local aiBrain = oUnitJustBuilt:GetAIBrain()
                local iTeam = aiBrain.AiBotTeam
                local tFactoryLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                local tFactoryLZTeamData = tFactoryLZData[AiBotMap.subrefLZTeamData][iTeam]
                if (tFactoryLZTeamData[AiBotMap.refbBaseInSafePosition] and not(aiBrain[AiBotOverseer.refbPrioritiseLand]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy])) or (aiBrain[AiBotOverseer.refbPrioritiseAir] and tFactoryLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                    local bHaveOtherFactoriesOfSameTech = false
                    if AiBotUtilities.IsTableEmpty(tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local iFactoryTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnitJustBuilt)
                        local iSearchCategory
                        if iFactoryTechLevel == 1 then iSearchCategory = AiBotUnitInfo.refCategoryAirHQ
                        elseif iFactoryTechLevel == 2 then iSearchCategory = AiBotUnitInfo.refCategoryAirHQ - categories.TECH1
                        else iSearchCategory = AiBotUnitInfo.refCategoryAirHQ * categories.TECH3
                        end

                        local tFactoriesOfSameTech = EntityCategoryFilterDown(iSearchCategory, tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tFactoriesOfSameTech) == false then
                            for iExistingFactory, oExistingFactory in tFactoriesOfSameTech do
                                if AiBotUnitInfo.IsUnitValid(oExistingFactory) and not(oExistingFactory == oUnitJustBuilt) and oExistingFactory:GetFractionComplete() == 1 then
                                    bHaveOtherFactoriesOfSameTech = true
                                    break
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': air hq bHaveOtherFactoriesOfSameTech='..tostring(bHaveOtherFactoriesOfSameTech)..'; Mex count for factory island='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tFactoryLZData[AiBotMap.subrefLZIslandRef]] or 0)..'; Mod dist%='..tFactoryLZTeamData[AiBotMap.refiModDistancePercent]) end
                    if not(bHaveOtherFactoriesOfSameTech) then
                        --Set flag of any other factories in this zone to false
                        if AiBotUtilities.IsTableEmpty(tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                            local tAllLandFacsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tFactoryLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            if AiBotUtilities.IsTableEmpty(tAllLandFacsInZone) == false then
                                for iFactory, oFactory in tAllLandFacsInZone do
                                    if not(oFactory == oUnitJustBuilt) and oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] then
                                        if (oFactory[AiBotACU.refiUpgradeCount] or 0) == 0 then
                                            oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = false
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Just set air factory '..oUnitJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitJustBuilt)..' to be the primary factory for P'..iPlateau..'Z'..iLandZone..'at time='..GetGameTimeSeconds()) end
                        oUnitJustBuilt[AiBotFactory.refbPrimaryFactoryForIslandOrPond] = true
                    end
                end
            end
        end

        if EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnitJustBuilt.UnitId) then
            local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnitJustBuilt)
            local sFactoryRef
            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnitJustBuilt.UnitId) then sFactoryRef = refiOurHighestLandFactoryTech
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnitJustBuilt.UnitId) then sFactoryRef = refiOurHighestAirFactoryTech
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnitJustBuilt.UnitId) then sFactoryRef = refiOurHighestNavalFactoryTech
            else AiBotUtilities.ErrorHandler('Unrecognised factory type')
            end
            local aiBrain = oUnitJustBuilt:GetAIBrain()
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if factory HQ is a higher tech than we already have, sFactoryRef='..sFactoryRef..'; iUnitTechLevel='..iUnitTechLevel..'; aiBrain[sFactoryRef]='..aiBrain[sFactoryRef]) end
            if iUnitTechLevel > aiBrain[sFactoryRef] then
                aiBrain[sFactoryRef] = math.max(aiBrain[sFactoryRef], iUnitTechLevel)
                aiBrain[refiOurHighestFactoryTechLevel] = math.max(iUnitTechLevel, aiBrain[refiOurHighestFactoryTechLevel])
                --Update team details
                AiBotTeam.UpdateTeamHighestAndLowestFactories(aiBrain.AiBotTeam)
                AiBotTeam.CheckForSubteamFactoryChange(oUnitJustBuilt, true)
            else
                --Still consider updating subteam, as e.g. we may have T3 UEF HQ and have just built T3 Seraphim HQ
                AiBotTeam.CheckForSubteamFactoryChange(oUnitJustBuilt, true)
            end

            --Special bomber snipe logic
            if aiBrain[AiBotOverseer.refbBomberSnipe] and iUnitTechLevel >= 2 and EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnitJustBuilt.UnitId) then
                local AiBotAir = import('/lua/AiBot/AI/AiBotAir.lua')
                ForkThread(AiBotAir.AssessPotentialBomberSnipeTargetsNowReachedT2Air, aiBrain.AiBotTeam)
            end
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryQuantumGateway, oUnitJustBuilt.UnitId) then
            if bDebugMessages == true then LOG(sFunctionRef..': Have built a gateway, will update subteam factory change') end
            AiBotTeam.CheckForSubteamFactoryChange(oUnitJustBuilt, true)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateHighestFactoryTechLevelForDestroyedUnit(oUnitJustDestroyed)
    --Dont call via forkthread as causes issues with the unit being removed
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateHighestFactoryTechLevelForDestroyedUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnitJustDestroyed.UnitId) then
        UpdateFactoryCountForFactoryKilledOrBuilt(oUnitJustDestroyed, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Factory was destroyed, oUnitJustDestroyed='..oUnitJustDestroyed.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitJustDestroyed)..'; is this an HQ factory='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnitJustDestroyed.UnitId))..'; Time='..GetGameTimeSeconds()) end
        local aiBrain = oUnitJustDestroyed:GetAIBrain()
        if EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnitJustDestroyed.UnitId) then
            local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnitJustDestroyed)
            if bDebugMessages == true then LOG(sFunctionRef..': iUnitTechLevel='..iUnitTechLevel..'; owned by brain '..aiBrain.Nickname) end
            function UnitsStillValid(iCategory)
                local tUnitsOfType = aiBrain:GetListOfUnits(iCategory, false, true)
                if AiBotUtilities.IsTableEmpty(tUnitsOfType) == false then
                    for iUnit, oUnit in tUnitsOfType do
                        if not(oUnit == oUnitJustDestroyed) and AiBotUnitInfo.IsUnitValid(oUnit) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Still have a valid unit for the category, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                            return true
                        end
                    end
                end
                return false
            end
            local iCategoryBeingConsidered
            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnitJustDestroyed.UnitId) then
                if bDebugMessages == true then LOG(sFunctionRef..': Land fac destroyed, iUnitTechLevel='..iUnitTechLevel..';  aiBrain[refiOurHighestLandFactoryTech] ='.. aiBrain[refiOurHighestLandFactoryTech]) end
                if iUnitTechLevel >= (aiBrain[refiOurHighestLandFactoryTech] or 0) then
                    aiBrain[refiOurHighestLandFactoryTech] = 0
                    for iTechLevel = 3, 1, -1 do
                        iCategoryBeingConsidered = AiBotUnitInfo.refCategoryLandFactory * AiBotUnitInfo.ConvertTechLevelToCategory(iTechLevel) - categories.SUPPORTFACTORY
                        if aiBrain:GetCurrentUnits(iCategoryBeingConsidered) > 0 and UnitsStillValid(iCategoryBeingConsidered) then
                            --Check these units are all still valid
                            aiBrain[refiOurHighestLandFactoryTech] = iTechLevel
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting highets land fac tech to iTechLevel='..iTechLevel) end
                            break
                        end
                    end
                end
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnitJustDestroyed.UnitId) then
                if bDebugMessages == true then LOG(sFunctionRef..': Air fac was destroyed, aiBrain[refiOurHighestAirFactoryTech]='..(aiBrain[refiOurHighestAirFactoryTech] or 'nil')..'; iUnitTechLevel='..iUnitTechLevel) end
                if iUnitTechLevel >= aiBrain[refiOurHighestAirFactoryTech] then
                    aiBrain[refiOurHighestAirFactoryTech] = 0
                    for iTechLevel = 3, 1, -1 do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iTechLevel='..iTechLevel..'; Cur units owned by this brain of that tech level excl support factory='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory * AiBotUnitInfo.ConvertTechLevelToCategory(iTechLevel) - categories.SUPPORTFACTORY)) end
                        iCategoryBeingConsidered = AiBotUnitInfo.refCategoryAirFactory * AiBotUnitInfo.ConvertTechLevelToCategory(iTechLevel) - categories.SUPPORTFACTORY
                        if aiBrain:GetCurrentUnits(iCategoryBeingConsidered) > 0 and UnitsStillValid(iCategoryBeingConsidered) then
                            aiBrain[refiOurHighestAirFactoryTech] = iTechLevel
                            break
                        end
                    end
                    if aiBrain[refiOurHighestAirFactoryTech] == 0 then
                        --We have lost our air HQ, consider a flag so that significant minor zones will try and build air factories
                        --Losing signficant unit in core base - consider moving core base
                        local iTeam = aiBrain.AiBotTeam
                        local tLZOrWZData = AiBotMap.tAllPlateaus[oUnitJustDestroyed[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oUnitJustDestroyed[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]]
                        local tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                            --Consider relocating core base if have another location that is either further from the enemy base or on a different plateau
                            ForkThread(ConsiderChangingCoreBase, aiBrain, oUnitJustDestroyed[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1], oUnitJustDestroyed[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2])
                        end
                    end
                end
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnitJustDestroyed.UnitId) then
                if iUnitTechLevel >= aiBrain[refiOurHighestNavalFactoryTech] then
                    aiBrain[refiOurHighestNavalFactoryTech] = 0
                    for iTechLevel = 3, 1, -1 do
                        iCategoryBeingConsidered = AiBotUnitInfo.refCategoryNavalFactory * AiBotUnitInfo.ConvertTechLevelToCategory(iTechLevel) - categories.SUPPORTFACTORY
                        if aiBrain:GetCurrentUnits(iCategoryBeingConsidered) > 0 and UnitsStillValid(iCategoryBeingConsidered) then
                            aiBrain[refiOurHighestNavalFactoryTech] = iTechLevel
                            break
                        end
                    end
                end
            else AiBotUtilities.ErrorHandler('Unrecognised factory type')
            end

            --Updated highest factory type across all types
            aiBrain[refiOurHighestFactoryTechLevel] = math.max(aiBrain[refiOurHighestLandFactoryTech], aiBrain[refiOurHighestAirFactoryTech], aiBrain[refiOurHighestNavalFactoryTech])

            --Update team details
            AiBotTeam.UpdateTeamHighestAndLowestFactories(aiBrain.AiBotTeam)
            AiBotTeam.CheckForSubteamFactoryChange(oUnitJustDestroyed, false)
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryQuantumGateway, oUnitJustDestroyed.UnitId) then
            AiBotTeam.CheckForSubteamFactoryChange(oUnitJustDestroyed, false)
        end
        --Check for if we have lost a teammate base (i.e. in full share type scenario) so no longer want to treat it as a closest friendly base
        if aiBrain.AiBotAI then
            local iTeam = aiBrain.AiBotTeam
            if bDebugMessages == true then LOG(sFunctionRef..': Have lost factory for brain '..aiBrain.Nickname..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount] > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then --we have lost a friendly AiBotAI, so want to check if the base of the killed AI is no more
                local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitJustDestroyed:GetPosition(), true, aiBrain.AiBotTeam)
                if bDebugMessages == true then LOG(sFunctionRef..': Dist from the zone this unit is in to the closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                if AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 10 then
                    --Is this the start position of a dead AI?
                    for iBrain, oBrain in ArmyBrains do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; IsDefeated='..tostring(oBrain:IsDefeated())..'; Dist from brain start position to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oBrain), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                        if oBrain.AiBotTeam == iTeam and oBrain:IsDefeated() and AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oBrain), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 10 then
                            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider if friendly base is destroyed now') end
                            ForkThread(AiBotMap.DelayedConsiderationOfWhetherToIgnoreFriendlyBase, tLZOrWZData, tLZOrWZTeamData, aiBrain.AiBotTeam, iPlateauOrZero, iLandOrWaterZone, AiBotLand.iTicksPerLandCycle * 0.1 + 0.1)
                            break
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Near end of code, aiBrain[refiOurHighestAirFactoryTech]='..oUnitJustDestroyed:GetAIBrain()[refiOurHighestAirFactoryTech]..'; aiBrain[refiOurHighestLandFactoryTech]='..oUnitJustDestroyed:GetAIBrain()[refiOurHighestLandFactoryTech]..'; aiBrain[refiOurHighestNavalFactoryTech]='..oUnitJustDestroyed:GetAIBrain()[refiOurHighestNavalFactoryTech]..'; aiBrain[refiOurHighestFactoryTechLevel]='..oUnitJustDestroyed:GetAIBrain()[refiOurHighestFactoryTechLevel]) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateMassStorageAdjacencyValues(oStorage, bDestroyed)
    --Updates gross income for the mass storage
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateMassStorageAdjacencyValues'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iMassChange = -(oStorage[refiStorageMassAdjacencyBonus] or 0)
    local aiBrain = oStorage:GetAIBrain()

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, Time='..GetGameTimeSeconds()..'; About to update for oStorage='..oStorage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStorage)..' owned by brain '..aiBrain.Nickname..'; bDestroyed='..tostring(bDestroyed or false)..'; oStorage[refiStorageMassAdjacencyBonus]='..(oStorage[refiStorageMassAdjacencyBonus] or 'nil')..'; aiBrain[refiGrossMassBaseIncome]='..(aiBrain[refiGrossMassBaseIncome] or 'nil')) end
    if not(bDestroyed) then
        oStorage[refiStorageMassAdjacencyBonus] = 0
        if oStorage:GetFractionComplete() >= 1 then
            local iBaseMassGen
            local iAIxMod = 1
            local iAdjacencyMassGen
            local oGenBP
            local iBPMassGen
            local iGenUnitSize
            local iStorageSize = AiBotUnitInfo.GetBuildingSize(oStorage.UnitId)
            --Adjust for AIx
            if aiBrain.CheatEnabled then
                iAIxMod = (aiBrain[refiBrainResourceMultiplier] or tonumber(ScenarioInfo.Options.CheatMult or 1.5))
            end
            oStorage[refiStorageMassAdjacencyBonus] = 0
            --Get all adjacent mexes
            if bDebugMessages == true then LOG(sFunctionRef..': iAIxMod='..iAIxMod..'; Is table of adjacent units empty='..tostring(AiBotUtilities.IsTableEmpty(oStorage.AdjacentUnits))) end
            if AiBotUtilities.IsTableEmpty(oStorage.AdjacentUnits) == false then
                --Cant use filterdown a doesnt work with .adjacentunits
                for iMassGenUnit, oMassGenUnit in oStorage.AdjacentUnits do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oMassGenUnit='..oMassGenUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMassGenUnit)..' owned by '..oMassGenUnit:GetAIBrain().Nickname) end
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryMassFab, oMassGenUnit.UnitId) and oMassGenUnit:GetAIBrain() == aiBrain and AiBotUnitInfo.IsUnitValid(oMassGenUnit) then --Wont get adjacency unless are on the same team
                        oGenBP = oMassGenUnit:GetBlueprint()
                        iBaseMassGen = (oGenBP.Economy.ProductionPerSecondMass or 0)
                        if iBaseMassGen > 0 then
                            iGenUnitSize = AiBotUnitInfo.GetBuildingSize(oMassGenUnit.UnitId)
                            --Mass storage adjacency - if covers all of the resource generation on all 4 sides, gives a 50% boost, so is giving 12.5% boost for each side fully covered
                            --Also want to measure in mass per tick not per second, so *0.0125
                            iAdjacencyMassGen = iBaseMassGen * iAIxMod * 0.0125 * math.min(1, iStorageSize / iGenUnitSize)
                            oStorage[refiStorageMassAdjacencyBonus] = oStorage[refiStorageMassAdjacencyBonus] + iAdjacencyMassGen
                            iMassChange = iMassChange + iAdjacencyMassGen
                            if bDebugMessages == true then LOG(sFunctionRef..': Are adjacent to oMassGenUnit='..(oMassGenUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMassGenUnit)..'; iAdjacencyMassGen for this unit='..(iAdjacencyMassGen or 'nil'))) end
                        end
                    end
                end
            end
        end
    end

    aiBrain[refiGrossMassBaseIncome] = (aiBrain[refiGrossMassBaseIncome] or 0) + iMassChange
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iMassChange='..iMassChange..'; aiBrain[refiGrossMassBaseIncome]='..aiBrain[refiGrossMassBaseIncome]) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderHydroUpgradeLoop(oUnit)
    --Every 10s consider upgrading unit
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderHydroUpgradeLoop'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Special upgrade monitor already active='..tostring(oUnit[refbSpecialUpgradeMonitor] or false)..'; Unit owner='..oUnit:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
    if not(oUnit[refbSpecialUpgradeMonitor]) then
        --Does the blueprint have an upgrade option?
        local oBP = oUnit:GetBlueprint()
        if bDebugMessages == true then LOG(sFunctionRef..': Unit upgrades to='..(oBP.General.UpgradesTo or 'nil')..'; Does this equal empty string='..tostring(oBP.General.UpgradesTo == '')) end
        if oBP.General.UpgradesTo and not(oBP.General.UpgradesTo == '') then
            oUnit[refbSpecialUpgradeMonitor] = true
            local aiBrain = oUnit:GetAIBrain()
            local iTeam = aiBrain.AiBotTeam
            local oUpgradedBP = __blueprints[oBP.General.UpgradesTo]
            if oUpgradedBP then
                local iBuildPower = oBP.Economy.BuildRate * aiBrain[refiBrainBuildRateMultiplier]
                local iBrainCount = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
                if bDebugMessages == true then LOG(sFunctionRef..': oUpgradedBP='..reprs(oUpgradedBP)) end
                local iMassPerTickWanted = 0.1 * (oUpgradedBP.Economy.BuildCostMass * iBuildPower / oUpgradedBP.Economy.BuildTime) * iBrainCount * 2
                local iEnergyPerTickWanted = 0.1 * (oUpgradedBP.Economy.BuildCostEnergy * iBuildPower / oUpgradedBP.Economy.BuildTime ) * iBrainCount * 2
                local iStoredMassAlternative = oUpgradedBP.Economy.BuildCostMass * 4
                local iDelay = 10
                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 then
                    local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                    local iResourceFactorAdjust = 1.5
                    if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.45 then --dont really want to get if near middle of map
                        if iUnitTechLevel >= 2 then
                            iDelay = 120
                            if aiBrain[refiGrossEnergyBaseIncome] >= 400 then
                                iResourceFactorAdjust = 10
                            else
                                iResourceFactorAdjust = 8
                            end
                        else
                            iDelay = 60
                            iResourceFactorAdjust = 5
                        end

                    else
                        if iUnitTechLevel >= 2 then
                            iDelay = 60
                            iResourceFactorAdjust = 3
                        else
                            iDelay = 30
                            iResourceFactorAdjust = 2
                        end
                    end
                    iMassPerTickWanted = iMassPerTickWanted * iResourceFactorAdjust
                    iEnergyPerTickWanted = iEnergyPerTickWanted * iResourceFactorAdjust
                    iStoredMassAlternative = iStoredMassAlternative * iResourceFactorAdjust
                    if bDebugMessages == true then LOG(sFunctionRef..': iResourceFactorAdjust='..iResourceFactorAdjust) end
                end
                local iGrossMassPerTickAlternative = iMassPerTickWanted * 20
                local iGrossEnergyPerTickAlternative = iEnergyPerTickWanted * 20

                if bDebugMessages == true then LOG(sFunctionRef..': iBuildPower='..iBuildPower..'; iMasPerTickWanted='..iMassPerTickWanted..'; iEnergyPerTickWanted='..iEnergyPerTickWanted) end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(iDelay)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

                while AiBotUnitInfo.IsUnitValid(oUnit) do
                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to upgrade at time='..GetGameTimeSeconds()..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Brain='..aiBrain.Nickname..'; Want more power='..tostring(AiBotConditions.WantMorePower(iTeam))..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; iEnergyPerTickWanted='..iEnergyPerTickWanted..'; Net mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; iMassPerTickWanted='..iMassPerTickWanted..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
                    if AiBotConditions.WantMorePower(iTeam) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= iEnergyPerTickWanted or (iEnergyPerTickWanted > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= iGrossEnergyPerTickAlternative) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= iMassPerTickWanted or ((aiBrain:GetEconomyStored('MASS') >= iStoredMassAlternative and (aiBrain:GetEconomyStored('MASS') >= iStoredMassAlternative * 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= -1)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= iGrossMassPerTickAlternative)))) then
                        UpgradeUnit(oUnit, false)
                        break
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(iDelay)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Couldnt locate an actual blueprint')
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateGrossIncomeForUnit(oUnit, bDestroyed, bIgnoreEnhancements, iOptionalResourceModAdjustmentOverride, oOptionalBrainFromDestroyedUnit)
    --iOptionalResourceModAdjustmentOverride - intended for use with AIX overwhelm where we have already recorded a unit but at the 'wrong' resource rate

    --Logs are enabled below
    if oUnit.GetAIBrain and EntityCategoryContains(AiBotUnitInfo.refCategoryResourceUnit + AiBotUnitInfo.refCategoryMassStorage, oUnit.UnitId) then
        --Does the unit have an AiBot aiBrain?
        local aiBrain = (oOptionalBrainFromDestroyedUnit or oUnit:GetAIBrain())
        if aiBrain.AiBotAI then
            local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
            local sFunctionRef = 'UpdateGrossIncomeForUnit'
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..' oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bDestroyed='..tostring(bDestroyed or false)..': Unit aiBrain='..oUnit:GetAIBrain().Nickname..'; Brain recorded for economy='..((oUnit[refoBrainRecordedForEconomy] or {'nil'}).Nickname or 'nil')..'; Fraction complete='..oUnit:GetFractionComplete()) end
            if (not(bDestroyed) or not(oOptionalBrainFromDestroyedUnit)) and oUnit:GetFractionComplete() < 1 then AiBotUtilities.ErrorHandler('Trying to update income for unit whose fraction isnt complete') end

            if (bDestroyed and oUnit[refoBrainRecordedForEconomy] == aiBrain) or (not(bDestroyed) and not(oUnit[refoBrainRecordedForEconomy] == aiBrain)) then
                local iMassGen
                local iEnergyGen
                if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and EntityCategoryContains(AiBotUnitInfo.refCategoryParagon, oUnit.UnitId) then
                    iMassGen = 10000 * 0.1
                    iEnergyGen = 1000000 * 0.1
                    if iOptionalResourceModAdjustmentOverride then
                        iMassGen = iMassGen * iOptionalResourceModAdjustmentOverride
                        iEnergyGen = iEnergyGen * iOptionalResourceModAdjustmentOverride
                    end
                    local iTeam = aiBrain.AiBotTeam
                    if bDestroyed then
                        local bRemainingParagon = false
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            local tParagon = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryParagon, false, true)
                            if AiBotUtilities.IsTableEmpty(tParagon) == false then
                                for iParagon, oParagon in tParagon do
                                    if oParagon:GetFractionComplete() == 1 then
                                        bRemainingParagon = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': we still have a contructed paragon for oBrain='..oBrain.Nickname..'; oParagon='..oParagon.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oParagon)) end
                                        break
                                    end
                                end
                            end
                            if bRemainingParagon then break end
                        end
                        oUnit:GetAIBrain()[refbBuiltParagon] = bRemainingParagon
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] = bRemainingParagon
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': We have just built a paragon for brain '..oUnit:GetAIBrain().Nickname..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                        oUnit:GetAIBrain()[refbBuiltParagon] = true
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': We have a paragon that has been built or killed, setting mass gen and energy gen accordingly, iMassGen='..iMassGen) end
                else
                    local oBP = oUnit:GetBlueprint()
                    iMassGen = math.max(oBP.Economy.ProductionPerSecondMass or 0) * 0.1
                    iEnergyGen = math.max(oBP.Economy.ProductionPerSecondEnergy or 0) * 0.1
                    --Adjust for RAS upgrade
                    if bDebugMessages == true then LOG(sFunctionRef..': Is this an ACU or SACU='..tostring(EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oUnit.UnitId))) end
                    if not(bIgnoreEnhancements) and EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oUnit.UnitId) then
                        local iUpgradeMassPerSec = 0
                        local iUpgradeEnergyPerSec = 0

                        local tPossibleUpgrades = oBP.Enhancements
                        if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; is tPossibleUpgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tPossibleUpgrades))) end
                        if AiBotUtilities.IsTableEmpty(tPossibleUpgrades) == false and oUnit.HasEnhancement then
                            local tbIncludedUpgrade = {}
                            for sCurUpgrade, tUpgrade in tPossibleUpgrades do
                                if oUnit:HasEnhancement(sCurUpgrade) then
                                    tbIncludedUpgrade[sCurUpgrade] = true
                                    iUpgradeMassPerSec = iUpgradeMassPerSec + (tUpgrade.ProductionPerSecondMass or 0)
                                    iUpgradeEnergyPerSec = iUpgradeEnergyPerSec + (tUpgrade.ProductionPerSecondEnergy or 0)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit has enhancement '..sCurUpgrade..'; tUpgrade.ProductionPerSecondMass='..(tUpgrade.ProductionPerSecondMass or 'nil')) end
                                end
                            end


                            --Include built in enhancements (i.e. RAS presets) as there is a delay with onbuilt units showing as having active enhancements
                            if oBP.EnhancementPresetAssigned.Enhancements then
                                for iCurUpgrade, sCurUpgrade in oBP.EnhancementPresetAssigned.Enhancements do
                                    if not(tbIncludedUpgrade[sCurUpgrade]) then
                                        iUpgradeMassPerSec = iUpgradeMassPerSec + (tPossibleUpgrades[sCurUpgrade].ProductionPerSecondMass or 0)
                                        iUpgradeEnergyPerSec = iUpgradeEnergyPerSec + (tPossibleUpgrades[sCurUpgrade].ProductionPerSecondEnergy or 0)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit has preset enhancement '..sCurUpgrade..'; tUpgrade.ProductionPerSecondMass='..(tPossibleUpgrades[sCurUpgrade].ProductionPerSecondMass or 'nil')..'; reprs='..reprs(tPossibleUpgrades[sCurUpgrade])) end
                                    end
                                end
                            end
                            --[[local activeEnhancements = SimUnitEnhancements[oUnit.EntityId]
                            if bDebugMessages == true then LOG(sFunctionRef..': Is activeEnhancements nil='..tostring(activeEnhancements == nil)) end
                            if activeEnhancements then
                                local presetEnhancements = oBP.EnhancementPresetAssigned.Enhancements
                                for _, enhName in activeEnhancements do
                                    if not(tbIncludedUpgrade[enhName]) then
                                        tbIncludedUpgrade[enhName] = true
                                        local enh = tPossibleUpgrades[enhName]
                                        iUpgradeMassPerSec = iUpgradeMassPerSec + (enh.ProductionPerSecondMass or 0)
                                        iUpgradeEnergyPerSec = iUpgradeEnergyPerSec + (enh.ProductionPerSecondEnergy or 0)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit has preset enhancement '..enhName..'; enh.ProductionPerSecondMass='..(enh.ProductionPerSecondMass or 'nil')) end
                                    end
                                end
                            end--]]
                        end
                        iMassGen = iMassGen + iUpgradeMassPerSec * 0.1
                        iEnergyGen = iEnergyGen + iUpgradeEnergyPerSec * 0.1
                        if bDebugMessages == true then LOG(sFunctionRef..': iUpgradeMassPerSec='..iUpgradeMassPerSec..'; iMassGen per tick='..iMassGen) end
                    end

                    --Mass storage - assume we are adjacent to a T2 mex as a basic approximation
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to check for mass storage, iMassGen='..iMassGen..'; iEnergyGen='..iEnergyGen..'; Does unit contain mass storage='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, oUnit.UnitId))) end
                    if iMassGen == 0 and iEnergyGen == 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, oUnit.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Dealing with mass storage so will update for adjacency value gained or lost') end
                        UpdateMassStorageAdjacencyValues(oUnit, bDestroyed) --Will update mass income values as part of this function
                    elseif iMassGen > 0 then
                        --Update adjacency values for any nearby mass storage
                        local tMexLocation = oUnit:GetPosition()
                        local rSearchRectangle = AiBotUtilities.GetRectAroundLocation(tMexLocation, 2.749) --If changing this also change AiBotEvents and AiBotEngineer similar value
                        local tNearbyUnits = GetUnitsInRect(rSearchRectangle) --at 1.5 end up with storage thats not adjacent being gifted in some cases but not in others; at 1 none of it gets gifted; the mass storage should be exactly 2 from the mex; however even at 2.1, 2.25 and 2.499 had cases where the mex wasnt identified so will try 2.75 since distances can vary/be snapped to the nearest 0.5 I think
                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if have any nearby units in a rectangle to this mex/mass fab, is tNearbyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnits))) end
                        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                            local tNearbyStorage = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMassStorage, tNearbyUnits)
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby storage empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyStorage))) end
                            if AiBotUtilities.IsTableEmpty(tNearbyStorage) == false then
                                for iStorage, oStorage in tNearbyStorage do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have oStorage='..oStorage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStorage)..'; will update if it is close to here, distance='..AiBotUtilities.GetDistanceBetweenPositions(oStorage:GetPosition(), tMexLocation)) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(oStorage:GetPosition(), tMexLocation) <= 2.25 then
                                        --Cant fork thread or else lose the aiBrain info if were just destroyed
                                        UpdateMassStorageAdjacencyValues(oStorage, false)
                                    end
                                end
                            end
                        end
                    end

                    --Adjust for AIx
                    if aiBrain.CheatEnabled then
                        local iAIxMod = iOptionalResourceModAdjustmentOverride or aiBrain[refiBrainResourceMultiplier] or tonumber(ScenarioInfo.Options.CheatMult or tostring(1.5))
                        iMassGen = iMassGen * iAIxMod
                        iEnergyGen = iEnergyGen * iAIxMod
                    end
                end
                if bDestroyed then
                    iMassGen = iMassGen * -1
                    iEnergyGen = iEnergyGen * -1
                    oUnit[refoBrainRecordedForEconomy] = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit destroyed so will reduce mass gen') end
                else
                    oUnit[refoBrainRecordedForEconomy] = aiBrain
                    if not(aiBrain[toRecordedEconomyUnits]) then aiBrain[toRecordedEconomyUnits] = {} end
                    table.insert(aiBrain[toRecordedEconomyUnits], oUnit)
                    --Set temporary flag that we have just built a lot of power (if we have)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if should temporarily say we have enough power; iEnergyGen='..iEnergyGen..'; Gross energy='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] or 'nil')..'; Net energy='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetEnergy] or 'nil')..'; Flag for lots of power='..tostring(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbJustBuiltLotsOfPower] or false)) end
                    if iEnergyGen >= math.max(20, (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] or 0) * 0.15, -(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetEnergy] or 0)) and not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbJustBuiltLotsOfPower]) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Setting flag we have built lots of power, subrefiTeamNetEnergy='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetEnergy] or 0)) end
                        local iTeam = aiBrain.AiBotTeam

                        local iTimeToWait = 6
                        if AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= 2 then
                            local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                            if iUnitTechLevel > 1 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] or 0) >= iEnergyGen * 0.2 then
                                iTimeToWait = math.max(6, math.min(30, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] or 1) / math.max(0.1, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] or 1))))
                            end
                            if iTimeToWait < 10 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] or 0) >= iEnergyGen * 0.1 and (AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 1 or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] or 0) < -1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4)) then
                                iTimeToWait = 10
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Just built a lot of power so will temporarily say we dont need more power, iTimeToWait='..iTimeToWait..'; refiTimeEndingActiveCheckOfLotsOfPower='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeEndingActiveCheckOfLotsOfPower] or 'nil')) end
                        if iTimeToWait <= 6 then
                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower]) then
                                AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower] = true
                                AiBotUtilities.DelayChangeVariable(AiBotTeam.tTeamData[aiBrain.AiBotTeam], AiBotTeam.refbJustBuiltLotsOfPower, false, iTimeToWait)
                            end
                        else
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower] = true
                            ForkThread(JustBuiltSignificantPowerMonitor, aiBrain.AiBotTeam, iTimeToWait, iEnergyGen) --This includes a check if we are already acitvely monitoring
                        end
                    end
                    --Update team eco values to factor in impact of this on any decisions made before the next team eco refresh
                    AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] = math.max(0, (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] or 0) + iMassGen)
                    AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetMass] = (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetMass] or 0) + iMassGen
                    AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] = math.max(0, (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] or 0) + iEnergyGen)
                    AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetEnergy] = (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetEnergy] or 0) + iEnergyGen
                end
                aiBrain[refiGrossEnergyBaseIncome] = math.max(0, (aiBrain[refiGrossEnergyBaseIncome] or 0) + iEnergyGen)
                aiBrain[refiNetEnergyBaseIncome] = (aiBrain[refiNetEnergyBaseIncome] or 0) + iEnergyGen
                aiBrain[refiGrossMassBaseIncome] = math.max(0, (aiBrain[refiGrossMassBaseIncome] or 0) + iMassGen)
                aiBrain[refiNetMassBaseIncome] = (aiBrain[refiNetMassBaseIncome] or 0) + iMassGen

                if iEnergyGen >= 25 then
                    ForkThread(ConsiderReclaimingPower, aiBrain.AiBotTeam, oUnit)
                end

                --Upgrading hydro
                if not(bDestroyed) and EntityCategoryContains(AiBotUnitInfo.refCategoryHydro, oUnit.UnitId) then
                    ForkThread(ConsiderHydroUpgradeLoop,oUnit)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Updated gross and net resources for iMassGen='..iMassGen..'; iEnergyGen='..iEnergyGen..'; aiBrain[refiNetMassBaseIncome]='..aiBrain[refiNetMassBaseIncome]..'; aiBrain[refiGrossMassBaseIncome]='..aiBrain[refiGrossMassBaseIncome]..'; refiNetEnergyBaseIncome='..aiBrain[refiNetEnergyBaseIncome]..'; refiGrossEnergyBaseIncome='..aiBrain[refiGrossEnergyBaseIncome]) end
            end


            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        end
    end
end

function AdjustAIxOverwhelmRate()
    --Waits the indicated number of seconds and then adjusts the AIx overwhelm rate
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AdjustAIxOverwhelmRate'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iSecondsToWait = tonumber(ScenarioInfo.Options.AiBotOvwT) * 60
    local iRateAdjustment = tonumber(ScenarioInfo.Options.AiBotOvwR)
    local iLowerCap = 0.1
    local iUpperCap = 10.0
    if iRateAdjustment > 0 then iUpperCap = tonumber(ScenarioInfo.Options.AiBotOvwC)
    else iLowerCap = tonumber(ScenarioInfo.Options.AiBotOvwC)
    end

    if bDebugMessages == true then LOG(sFunctionRef..': near start of code, iSecondsToWait='..iSecondsToWait..'; ScenarioInfo.Options.AiBotOvwT='..ScenarioInfo.Options.AiBotOvwT..'; iRateAdjustment='..iRateAdjustment..'; ScenarioInfo.Options.AiBotOvwR='..ScenarioInfo.Options.AiBotOvwR..'; iLowerCap='..iLowerCap..'; iUpperCap='..iUpperCap) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(iSecondsToWait)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(AiBotOverseer.tAllActiveAiBotBrains) == false then
        local bChangedModifier
        local iCurBuildModifier
        local iCurResourceModifier

        local bHaveIndividualAIBrainMods = false
        for iBrian, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
            if oBrain.CheatValue then bHaveIndividualAIBrainMods = true break end
        end

        while AiBotUtilities.bAiBotAIInGame do
            --Set the new modifier
            bChangedModifier = false
            iCurResourceModifier = tonumber(ScenarioInfo.Options.CheatMult or tostring(1.5))
            iCurBuildModifier = tonumber(ScenarioInfo.Options.BuildMult or tostring(1.5))

            if iRateAdjustment > 0 then
                if iCurResourceModifier < iUpperCap or iCurBuildModifier < iUpperCap then
                    iCurResourceModifier = math.min(iCurResourceModifier + iRateAdjustment, iUpperCap)
                    iCurBuildModifier = math.min(iCurBuildModifier + iRateAdjustment, iUpperCap)
                    ScenarioInfo.Options.CheatMult = tostring(iCurResourceModifier)
                    ScenarioInfo.Options.BuildMult = tostring(iCurBuildModifier)
                    if bDebugMessages == true then LOG(sFunctionRef..': Increased modifiers to reflect iRateAdjustment='..iRateAdjustment..'; CheatMult now='..ScenarioInfo.Options.CheatMult..'; BuildMult now='..ScenarioInfo.Options.BuildMult) end
                    bChangedModifier = true
                end
            else
                if iCurResourceModifier > iLowerCap or iCurBuildModifier > iLowerCap then
                    iCurResourceModifier = math.max(iCurResourceModifier + iRateAdjustment, iLowerCap)
                    iCurBuildModifier = math.max(iCurBuildModifier + iRateAdjustment, iLowerCap)
                    ScenarioInfo.Options.CheatMult = tostring(iCurResourceModifier)
                    ScenarioInfo.Options.BuildMult = tostring(iCurBuildModifier)
                    if bDebugMessages == true then LOG(sFunctionRef..': Rate adjustment is negative, adjusted modifiers to reflect iRateAdjustment='..iRateAdjustment..'; CheatMult now='..ScenarioInfo.Options.CheatMult..'; BuildMult now='..ScenarioInfo.Options.BuildMult) end
                    bChangedModifier = true
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bChangedModifier='..tostring(bChangedModifier)..'; bHaveIndividualAIBrainMods='..tostring(bHaveIndividualAIBrainMods)..'; Time='..GetGameTimeSeconds()) end
            if not(bChangedModifier) and not(bHaveIndividualAIBrainMods) then
                break
            else
                --Adjust each brain (which should also adjust all units owned by them and updates the team modifier)
                local bChangedAnyAI = not(bHaveIndividualAIBrainMods)
                function GetIndividualModifier(oBrain)
                    bChangedModifier = false
                    if iRateAdjustment > 0 then
                        if oBrain.CheatValue < iUpperCap then
                            bChangedModifier = true
                        end
                    else
                        if oBrain.CheatValue > iLowerCap then
                            bChangedModifier = true
                        end
                    end
                    if bChangedModifier then return oBrain.CheatValue + iRateAdjustment end
                end
                local iIndividualModifier
                for iBrain, oBrain in ArmyBrains do
                    if oBrain.CheatEnabled and not(oBrain.AiBotIsDefeated) and (oBrain.AiBotAI or oBrain.BrainType == 'AI') then
                        if bHaveIndividualAIBrainMods and oBrain.CheatValue then
                            iIndividualModifier = GetIndividualModifier(oBrain)
                            if bChangedModifier and iIndividualModifier then
                                bChangedAnyAI = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Changing AIx modifier for brain '..oBrain.Nickname..' to '..iIndividualModifier) end
                                --Also change the AI .CheatValue
                                --aiBrain, iBuildModifier, iResourceModifier, bDontChangeScenarioInfo, iOptionalRecordedUnitResourceAdjust, bDontApplyToUnits, bUpdateCheatValue)
                                AiBotOverseer.SetBuildAndResourceCheatModifiers(oBrain, iIndividualModifier, iIndividualModifier, true,                   nil,                                false,           true)
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Will update AIx modifiers for brain to iCurBuildModifier='..iCurBuildModifier..'; iCurResourceModifier='..iCurResourceModifier) end
                            AiBotOverseer.SetBuildAndResourceCheatModifiers(oBrain, iCurBuildModifier, iCurResourceModifier, true)
                        end
                    end
                end
                if bHaveIndividualAIBrainMods and not(bChangedAnyAI) then break end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iSecondsToWait)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshEconomyGrossValues(aiBrain)
    --Updates recorded gross mass and energy for each unit
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshEconomyGrossValues'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tEconomyUnits = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryResourceUnit, false, true)
    if bDebugMessages == true then LOG(sFunctionRef..': refreshing gross income for every unit we own time='..GetGameTimeSeconds()..'; size of tEconomyUnits='..table.getn(tEconomyUnits)..'; Gross E before update='..aiBrain[refiGrossEnergyBaseIncome]) end
    if tEconomyUnits then
        local iConstructedEconomyUnits = 0
        for iUnit, oUnit in tEconomyUnits do
            if oUnit:GetFractionComplete() == 1 then
                if not(oUnit[refoBrainRecordedForEconomy] == aiBrain) then
                    UpdateGrossIncomeForUnit(oUnit) --if we havent recorded the unit then will record it (this has its own check re brain, per above; added above for minor optimisation)
                end
                iConstructedEconomyUnits = iConstructedEconomyUnits + 1
            end
        end
        --Check for destroyed units we haven't picked up yet
        if aiBrain[toRecordedEconomyUnits] and iConstructedEconomyUnits < table.getn(aiBrain[toRecordedEconomyUnits]) then
            for iRecorded, oRecorded in aiBrain[toRecordedEconomyUnits] do
                if (oRecorded.Dead or (oRecorded.BeenDestroyed and oRecorded:BeenDestroyed())) and oRecorded[refoBrainRecordedForEconomy] == aiBrain then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a dead resource generator that we havent recognised is dead, oRecorded='..(oRecorded.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oRecorded) or 'nil')) end
                    UpdateGrossIncomeForUnit(oRecorded, true, nil, nil, aiBrain) --(this also has a brain check, added brain check above as well for minor optimisation)
                end
            end

        end
    end

    --Update storage capacity
    GetMassStorageMaximum(aiBrain, true)

    GetEnergyStorageMaximum(aiBrain, true)

end

function RefreshEconomyData(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshEconomyData'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    aiBrain[refiNetEnergyBaseIncome] = math.min((aiBrain[refiGrossEnergyBaseIncome] or 0) - aiBrain:GetEconomyRequested('ENERGY'), aiBrain:GetEconomyTrend('ENERGY'))
    aiBrain[refiNetMassBaseIncome] = math.min((aiBrain[refiGrossMassBaseIncome] or 0) - aiBrain:GetEconomyRequested('MASS'), aiBrain:GetEconomyTrend('MASS'))

    if bDebugMessages == true then LOG(sFunctionRef..': Finished refreshing economy data, time='..GetGameTimeSeconds()..'; Energy gross='..aiBrain[refiGrossEnergyBaseIncome]..'; Energy net='..aiBrain[refiNetEnergyBaseIncome]..'; Mass gross='..aiBrain[refiGrossMassBaseIncome]..'; Mass net='..aiBrain[refiNetMassBaseIncome]..'; aiBrain:GetEconomyRequested(\'MASS\')='..aiBrain:GetEconomyRequested('MASS')..'; aiBrain:GetEconomyTrend(\'MASS\')='..aiBrain:GetEconomyTrend('MASS')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function EconomyMainLoop(aiBrain)
    local iSlowRefreshCount = 0

    while not(aiBrain.AiBotIsDefeated) do
        --Slow refresh logic - every 30s update economy values for every unit as redundancy
        if iSlowRefreshCount == 0 then
            ForkThread(RefreshEconomyGrossValues, aiBrain)
        end
        iSlowRefreshCount = iSlowRefreshCount + 1
        if iSlowRefreshCount >= 30 then iSlowRefreshCount = 0 end

        --Frequent refresh logic:
        ForkThread(RefreshEconomyData, aiBrain)
        WaitSeconds(1)
    end
end

function EconomyInitialisation(aiBrain)
    while not(aiBrain[AiBotOverseer.refbInitialised]) do
        WaitTicks(1)
        if GetGameTimeSeconds() >= 5 then
            AiBotUtilities.ErrorHandler('Waited 5 seconds and brain '..aiBrain.Nickname..' doesnt seem to have initialised AiBot code')
            break
        end
    end
    if not(aiBrain[refiGrossEnergyBaseIncome]) then aiBrain[refiGrossEnergyBaseIncome] = 0 end
    if not(aiBrain[refiNetEnergyBaseIncome]) then aiBrain[refiNetEnergyBaseIncome] = 0 end
    if not(aiBrain[refiGrossMassBaseIncome]) then aiBrain[refiGrossMassBaseIncome] = 0 end
    if not(aiBrain[refiNetMassBaseIncome]) then aiBrain[refiNetMassBaseIncome] = 0 end

    --Some values are set when creating a team to avoid errors

    ForkThread(EconomyMainLoop, aiBrain)
end

function RecordUnitsOfCategoryToBeReclaimed(iTeam, iCategory)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordUnitsOfCategoryToBeReclaimed'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAddCurUnit
    local bCheckForExistingUnits
    for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
        if AiBotUtilities.IsTableEmpty(tPlateauData[AiBotMap.subrefPlateauLandZones]) == false then
            for iLandZone, tLZData in tPlateauData[AiBotMap.subrefPlateauLandZones] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if iPlateau-LZ '..iPlateau..'-'..iLandZone..' has units of the category wanted') end
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    if not(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoUnitsToReclaim]) then
                        bCheckForExistingUnits = false
                        tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoUnitsToReclaim] = {}
                    else
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoUnitsToReclaim]) == false then
                            bCheckForExistingUnits = true
                        end
                    end
                    local tUnitsToReclaim = EntityCategoryFilterDown(iCategory, tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoLZOrWZAlliedUnits])
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of untis of category wanted empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToReclaim))) end
                    if AiBotUtilities.IsTableEmpty(tUnitsToReclaim) == false then
                        for iUnit, oUnit in tUnitsToReclaim do
                            if bDebugMessages == true then LOG(sFunctionRef..': Will add unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of units to be reclaimed unless it is already in the table') end
                            bAddCurUnit = true
                            if bCheckForExistingUnits then
                                for iExistingUnit, oExistingUnit in tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoUnitsToReclaim] do
                                    if oUnit == oExistingUnit then
                                        bAddCurUnit = false
                                        break
                                    end
                                end
                            end
                            if bAddCurUnit then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to table of units to reclaim for iTeam='..iTeam..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                table.insert(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoUnitsToReclaim], oUnit)
                                oUnit[AiBotEngineer.refbDontIncludeAsPartCompleteBuildingForConstruction] = true
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshUnitsToReclaim(iTeam, iPlateau, iLandZone)
    --Removes any dead units
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshUnitsToReclaim'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tUnitsToReclaim = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subreftoUnitsToReclaim]
    if bDebugMessages == true then
        LOG(sFunctionRef..': About to remove any dead units from tUnitsToReclaim for iPlateau-iLandZone='..iPlateau..'-'..iLandZone..', is table empty at start='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToReclaim)))
        if AiBotUtilities.IsTableEmpty(tUnitsToReclaim) == false then
            LOG(sFunctionRef..': Size of tUnitsToReclaim='..table.getn(tUnitsToReclaim))
        end
    end

    function KeepCurEntry(tArray, iEntry)
        return AiBotUnitInfo.IsUnitValid(tArray[iEntry])
    end
    if AiBotUtilities.IsTableEmpty(tUnitsToReclaim) == false then
        AiBotUtilities.RemoveEntriesFromArrayBasedOnCondition(tUnitsToReclaim, KeepCurEntry)
        if bDebugMessages == true then LOG(sFunctionRef..': Is table empty after removing dead units='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToReclaim))) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForUnitsToReclaimOfCategory(iTeam, iCategory, sTeamSubrefFlag)
    --Checks if we have any units of iCategory, and if so then checks if we have low enough mass to reclaim them; if we have enough mass then starts a while loop and only aborts once we no longer have any units of the category
    --CheckForUnitsToReclaimOfCategory - e.g. subrefbActiveT2PowerReclaimer
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckForUnitsToReclaimOfCategory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotTeam.tTeamData[iTeam][sTeamSubrefFlag] = true
    local bDontCheckForPower = true
    if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryPower, iCategory, false) then bDontCheckForPower = false end
    if bDebugMessages == true then LOG(sFunctionRef..': Checking to see if we have any units to reclaim for the specified category.  bDontCheckForPower='..tostring(bDontCheckForPower)) end
    while AiBotTeam.GetCurrentUnitsOfCategory(iTeam, iCategory) > 0 do
        --Are we low on mass and not low on power?
        if bDebugMessages == true then LOG(sFunctionRef..': Will only add units to be reclaimed if we have low mass, and have power (if checking for power). Has low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; Have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))) end
        if AiBotConditions.TeamHasLowMass(iTeam) and (bDontCheckForPower or not(AiBotConditions.HaveLowPower(iTeam))) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            RecordUnitsOfCategoryToBeReclaimed(iTeam, iCategory) --this can sometimes have waitticks in it
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if bDebugMessages == true then LOG(sFunctionRef..': Have added any units to be reclaimed, will stop looping now') end
            break
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end

    AiBotTeam.tTeamData[iTeam][sTeamSubrefFlag] = false
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderReclaimingPower(iTeam, oPowerJustBuilt)
    --Intended to be called whenever we build a PGen
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderReclaimingPower'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPowerTechLevel = AiBotUnitInfo.GetUnitTechLevel(oPowerJustBuilt)
    if bDebugMessages == true then LOG(sFunctionRef..': Just built power='..oPowerJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPowerJustBuilt)..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Do we have active reclaimer logic for T1='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbActiveT1PowerReclaimer] or false)..'; Do we ahve active t2 reclaimer='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbActiveT2PowerReclaimer])) end
    if iPowerTechLevel == 2 then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 20 + 80 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbActiveT1PowerReclaimer]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbActiveT2PowerReclaimer]) then
            --Check we have 1 T2 power per AiBot player
            local iT2PowerEquivalent = 0
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                iT2PowerEquivalent = iT2PowerEquivalent + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH2) + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH3) * 4
            end
            if iT2PowerEquivalent >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.65 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] then
                if iT2PowerEquivalent >= 2 then AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] = false end --If game is late enough that we have built multiple t2 pgens then should start ecoing
                if bDebugMessages == true then LOG(sFunctionRef..': Will check for t1 power that we can reclaim') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                CheckForUnitsToReclaimOfCategory(iTeam, AiBotUnitInfo.refCategoryT1Power, AiBotTeam.subrefbActiveT1PowerReclaimer)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end
    elseif iPowerTechLevel == 3 then
        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] = false --redundancy (wouldnt expect to get to this point anyway with t1 spam active)
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbActiveT2PowerReclaimer]) then
            local iT3PowerEquivalent = 0
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                iT3PowerEquivalent = iT3PowerEquivalent + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH3)
            end
            if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 600 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.65 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] and (iT3PowerEquivalent >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 2000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]) then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                CheckForUnitsToReclaimOfCategory(iTeam, AiBotUnitInfo.refCategoryT1Power + AiBotUnitInfo.refCategoryT2Power, AiBotTeam.subrefbActiveT2PowerReclaimer)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            elseif not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbActiveT1PowerReclaimer]) then
                if bDebugMessages == true then LOG(sFunctionRef..': Built T3 PGen, but sitll low gross energy, Will check for t1 power that we can reclaim') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                CheckForUnitsToReclaimOfCategory(iTeam, AiBotUnitInfo.refCategoryT1Power, AiBotTeam.subrefbActiveT1PowerReclaimer)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function GetCategoryAndActionsToPauseWhenStalling(iTeam, bStallingMass, bPauseNotUnpause)
    --First check if we already have the category tables determiend from when the stall started
    --local tCategoriesByPriority, tEngineerActionsByPriority
    if bStallingMass then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables][1] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables][2] then
            --LOG('About to return category and engineer tables,  category size='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables][1])..'; Engineer size='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables][2]))
            return AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables][1], AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables][2]
        end
    else
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables][1] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables][2] then
            return AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables][1], AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables][2]
        end
    end



    --if AiBotTeam.tTeamData[iTeam][refiLastMassStallCategoryAndEngineerTables] = {}
    --tTeamData[iTotalTeamCount][refiLastEnergyStallCategoryAndEngineerTables] = {}
    --Are there enemies adjacent to a core base? If so then dont want to pause T2+ air factories except as a near last resort
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        local tCategoryAndEngineerTables
        if bStallingMass then
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables] = {[1]=0,[2]=0}
            tCategoryAndEngineerTables = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables]
        else
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables] = {[1]=0,[2]=0}
            tCategoryAndEngineerTables = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables]
        end
        local bImminentThreat = false
        local iPlateauOrZero, iLandOrWaterZone
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
            local tLZOrWZData
            local tLZOrWZTeamData
            if iPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end
            if tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] then
                bImminentThreat = true
                break
