                                                  { AiBotEngineer.refActionBuildExperimental, AiBotEngineer.refActionAssistAirFactory, AiBotEngineer.refActionAssistNavalFactory, AiBotEngineer.refActionAssistUpgrade, AiBotEngineer.refActionBuildEnergyStorage,  AiBotEngineer.refActionBuildT3MassFab, AiBotEngineer.refActionBuildSecondMassStorage, AiBotEngineer.refActionAssistMexUpgrade, AiBotEngineer.refActionSpare },
