                    tCategoryAndEngineerTables[2] = { { AiBotEngineer.refActionBuildQuantumOptics, AiBotEngineer.refActionBuildT3MassFab, AiBotEngineer.refActionBuildHive, AiBotEngineer.refActionBuildT3Radar, AiBotEngineer.refActionBuildGameEnder, AiBotEngineer.refActionBuildLandExperimental, AiBotEngineer.refActionBuildSecondExperimental, AiBotEngineer.refActionNavalSpareAction, AiBotEngineer.refActionBuildT2Sonar, AiBotEngineer.refActionBuildT1Sonar, AiBotEngineer.refActionBuildT2Radar, AiBotEngineer.refActionBuildT1Radar, AiBotEngineer.refActionBuildQuantumGateway, AiBotEngineer.refActionBuildEnergyStorage, AiBotEngineer.refActionBuildAirStaging, AiBotEngineer.refActionManageGameEnderTemplate, AiBotEngineer.refActionBuildShield, AiBotEngineer.refActionBuildSecondShield, AiBotEngineer.refActionBuildThirdPower, AiBotEngineer.refActionBuildSecondAirFactory, AiBotEngineer.refActionBuildAirFactory, AiBotEngineer.refActionBuildSecondLandFactory, AiBotEngineer.refActionSAMCreep, AiBotEngineer.refActionBuildNavalFactory, AiBotEngineer.refActionAssistMexUpgrade, AiBotEngineer.refActionUpgradeBuilding, AiBotEngineer.refActionAssistUpgrade },
                                                      { AiBotEngineer.refActionBuildSecondMassStorage, AiBotEngineer.refActionAssistAirFactory, AiBotEngineer.refActionBuildExperimental, AiBotEngineer.refActionBuildMassStorage, AiBotEngineer.refActionSpare, AiBotEngineer.refActionAssistNavalFactory,  AiBotEngineer.refActionBuildTML, AiBotEngineer.refActionBuildSecondPower, AiBotEngineer.refActionFortifyFirebase },
                                                      { AiBotEngineer.refActionBuildLandFactory, AiBotEngineer.refActionBuildSMD, AiBotEngineer.refActionBuildEmergencyArti, iSpecialNonPowerEngiAction } }
                end
