                tCategoryAndEngineerTables[1] = { AiBotUnitInfo.refCategoryQuantumOptics, AiBotUnitInfo.refCategorySMD, AiBotUnitInfo.refCategoryMassFab, AiBotUnitInfo.refCategoryEngineerStation, AiBotUnitInfo.refCategoryQuantumOptics, iSpecialSurplusUpgradeCategory, AiBotUnitInfo.refCategoryTML, AiBotUnitInfo.refCategoryEngineer, AiBotUnitInfo.refCategoryQuantumGateway, categories.SUBCOMMANDER, AiBotUnitInfo.refCategorySpecialFactory, AiBotUnitInfo.refCategoryAirFactory, AiBotUnitInfo.refCategoryNavalFactory, AiBotUnitInfo.refCategoryT3Radar, categories.COMMAND, AiBotUnitInfo.refCategoryEngineer, AiBotUnitInfo.refCategorySML - categories.EXPERIMENTAL, iSpecialHQCategory, AiBotUnitInfo.refCategoryStealthGenerator, AiBotUnitInfo.refCategoryStealthAndCloakPersonal, AiBotUnitInfo.refCategorySonar, AiBotUnitInfo.refCategoryRadar, AiBotUnitInfo.refCategoryPersonalShield, AiBotUnitInfo.refCategoryFixedShield, AiBotUnitInfo.refCategoryMobileLandShield, AiBotUnitInfo.refCategoryEngineer }
                tCategoryAndEngineerTables[2] = { { AiBotEngineer.refActionBuildQuantumOptics, AiBotEngineer.refActionBuildT3MassFab, AiBotEngineer.refActionBuildHive, AiBotEngineer.refActionBuildT3Radar, AiBotEngineer.refActionBuildGameEnder, AiBotEngineer.refActionBuildLandExperimental, AiBotEngineer.refActionBuildSecondExperimental, AiBotEngineer.refActionNavalSpareAction, AiBotEngineer.refActionBuildT2Sonar, AiBotEngineer.refActionBuildT1Sonar, AiBotEngineer.refActionBuildT2Radar, AiBotEngineer.refActionBuildT1Radar, AiBotEngineer.refActionBuildExperimental, AiBotEngineer.refActionBuildQuantumGateway, AiBotEngineer.refActionBuildEnergyStorage, AiBotEngineer.refActionBuildAirStaging, AiBotEngineer.refActionManageGameEnderTemplate, AiBotEngineer.refActionBuildShield, AiBotEngineer.refActionBuildSecondShield, AiBotEngineer.refActionBuildThirdPower, AiBotEngineer.refActionBuildSecondAirFactory, AiBotEngineer.refActionBuildAirFactory, AiBotEngineer.refActionBuildSecondLandFactory, AiBotEngineer.refActionSAMCreep, AiBotEngineer.refActionBuildNavalFactory, AiBotEngineer.refActionAssistMexUpgrade, AiBotEngineer.refActionUpgradeBuilding, AiBotEngineer.refActionAssistUpgrade},
