                                                  { AiBotEngineer.refActionBuildLandFactory, AiBotEngineer.refActionBuildSMD, AiBotEngineer.refActionBuildEmergencyArti, iSpecialNonPowerEngiAction } }

            end
            --Early game - consider pausing t1 mex and mex construction if we are really stalling
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 100 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 50 + 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                table.insert(tCategoryAndEngineerTables[1], AiBotUnitInfo.refCategoryT1Mex)
                table.insert(tCategoryAndEngineerTables[2][3], AiBotEngineer.refActionBuildMex)
            end
        end
        --LOG('TEMPCODE bImminentThreat='..tostring(bImminentThreat)..'; size of tCategoryAndEngineerTables[1]='..table.getn(tCategoryAndEngineerTables[1])..'; Time='..GetGameTimeSeconds())
        if not(bPauseNotUnpause) then
            table.insert(tCategoryAndEngineerTables[1], AiBotUnitInfo.refCategoryT2Mex)
            table.insert(tCategoryAndEngineerTables[1], AiBotUnitInfo.refCategoryT1Mex)
        end
        --LOG('About to return category and engineer tables,  category size='..table.getn(tCategoryAndEngineerTables[1])..'; Engineer size='..table.getn(tCategoryAndEngineerTables[2]))
        return tCategoryAndEngineerTables[1], tCategoryAndEngineerTables[2]
    else
        AiBotUtilities.ErrorHandler('No active AiBot brains')
    end
end

function ManageMassStalls(iTeam)
    --For now focus is on if we are trying to build a missile for an SML, or we are massively mass stalling
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageMassStalls'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start at time'..GetGameTimeSeconds()..'; Is table of active AiBot brains empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))..'; Net mass / gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        local bOnlyParagons = false
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] then
            bOnlyParagons = true
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                if not(oBrain[refbBuiltParagon]) then
                    bOnlyParagons = false
                    break
                end
            end
        end
        local bPauseNotUnpause = true
        local bChangeRequired = false
        local iUnitsAdjusted = 0
        local iMassStallPercentAdjust = 0
        local iOverspendPercentage = 0.2 --i.e. if sending 20% more than our gross income will consider a mass stall
        local bOnlyEasyBrains = true
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if not(oBrain.AiBotEasy) then
                bOnlyEasyBrains = false
                break
            end
        end
        if bOnlyEasyBrains then
            iOverspendPercentage = 0.35
        end
        local bFirstBrain
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] then iMassStallPercentAdjust = 0.015 end
        --Dont consider pausing or unpausing if are stalling energy or early game, as our energy stall manager is likely to be operating
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, GetGameTimeSeconds='..GetGameTimeSeconds()..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Team stalling mass already='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; Team stalling energy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or ((GetGameTimeSeconds() >= 120 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 3 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -100) >= 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.99)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 0.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and GetGameTimeSeconds() >= 80 and GetGameTimeSeconds() <= 180 and not(AiBotMap.bIsLowMexMap) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 1 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryEngineer) >= 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
            if bOnlyParagons then bPauseNotUnpause = false end
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': About to consider if we have a mass stall or not. Team lowest mass percent stored=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))
            end
            --First consider unpausing
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': If we have flagged that we are stalling mass then will check if we have enough to start unpausing things. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; iMassStallPercentAdjust='..iMassStallPercentAdjust)
            end

            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > (0.005 + iMassStallPercentAdjust) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 2000 then
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': Have enough mass stored or income to start unpausing things')
                end
                bPauseNotUnpause = false
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then bChangeRequired = true end
            end
            if bDebugMessages == true then LOG(sFunctionRef .. ': Checking if we shoudl flag that we are mass stalling. bChangeRequired='..tostring(bChangeRequired)..'; Mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Need resources for missile='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] or false))..'; Gross mass income='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]) end
            --Check if should manage mass stall
            if bChangeRequired == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= (0.001 + iMassStallPercentAdjust) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < -1 and (-AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= iOverspendPercentage))) and not(bOnlyParagons) then
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': We are stalling mass, will look for units to pause and record this as the time of last mass stall')
                end
                bChangeRequired = true
                bPauseNotUnpause = true
                AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] = true
            end
            if bPauseNotUnpause and not(bChangeRequired) and not(bOnlyParagons) then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbStallingMassFlaggedFromTeamEconomy] then
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbStallingMassFlaggedFromTeamEconomy] = false
                    bChangeRequired = true
                else
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] > 0 then
                        bChangeRequired = true
                    end
                end
            end

            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] = GetGameTimeSeconds() end

            if bDebugMessages == true then LOG(sFunctionRef..': bChangeRequired='..tostring(bChangeRequired)..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; Time of last stall='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 'nil')) end
            if bChangeRequired then
                local bDontPauseUpgradingT1LandOrT2Land = false
                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether we want to avoid pausing a t1 factory upgrading to t2, lowest friendly land factory tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] or 'nil')..'; Highest='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; Is table of upgrading HQs empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]))) end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] < 3 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false then
                    for iFactory, oFactory in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs] do
                        if AiBotUnitInfo.IsUnitValid(oFactory) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) then
                            local tFactoryLZData, tFactoryLZTeamData = AiBotMap.GetLandOrWaterZoneData(oFactory:GetPosition(), true, iTeam)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering upgrading factory '..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; Do we want to save mass for MML for firebase for zone this factory is in='..tostring(AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tFactoryLZData, tFactoryLZTeamData, oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1], iTeam, true))) end
                            if tFactoryLZTeamData and AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tFactoryLZData, tFactoryLZTeamData, oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1], iTeam, true) then
                                bDontPauseUpgradingT1LandOrT2Land = true
                                break
                            end
                        end
                    end

                end

                local iMinBuildCountBeforePausingHQ = 5
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 0.8 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or bDontPauseUpgradingT1LandOrT2Land then
                    iMinBuildCountBeforePausingHQ = 2
                end

                --Decide on order to pause/unpause

                local tCategoriesByPriority, tEngineerActionsByPriority = GetCategoryAndActionsToPauseWhenStalling(iTeam, true, bPauseNotUnpause)

                local iMassPerTickSavingNeeded
                if bPauseNotUnpause then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] then iMassPerTickSavingNeeded = math.max(1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass])
                    else
                        if -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.8 then --almost 80% stall rate
                            iMassPerTickSavingNeeded = math.max(1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass])
                        else
                            iMassPerTickSavingNeeded = math.max(1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] * 0.8)
                        end
                    end
                else
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNeedResourcesForMissile] then iMassPerTickSavingNeeded = math.min(-1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass], -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] / 30)
                    else
                        iMassPerTickSavingNeeded = math.min(-1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] * 1.2, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] / 20)
                    end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.15 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 4000 then
                        iMassPerTickSavingNeeded = iMassPerTickSavingNeeded * 1.2 - 0.5
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 4000 then iMassPerTickSavingNeeded = iMassPerTickSavingNeeded - 1 end
                    end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 2000 then iMassPerTickSavingNeeded = iMassPerTickSavingNeeded - 1 end
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to unpause units, iMassPerTickSavingNeeded (negative means unpausing units)='..iMassPerTickSavingNeeded) end
                end

                local iMassSavingManaged = 0
                local iEngineerSubtableCount = 0
                local tEngineerActionSubtable
                local oUnit
                local oBrainWithParagon
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and bPauseNotUnpause then
                    for iBrain, oBrain in  AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        if oBrain[refbBuiltParagon] and not(oBrain[AiBotOverseer.refbCloseToUnitCap]) then oBrainWithParagon = oBrain break end
                    end
                end

                local bAbort = false
                local iTotalUnits = 0
                local iCategoryStartPoint, iIntervalChange, iCategoryEndPoint, iCategoryRef
                local bWasUnitAlreadyPaused
                local bConsiderReclaimingEngineer = false
                local iKillCount = 0
                local iCurPlateau, iCurLandZone
                local iBuildRateMod

                if bPauseNotUnpause then
                    iCategoryStartPoint = 1
                    iIntervalChange = 1
                    iCategoryEndPoint = table.getn(tCategoriesByPriority)
                    if GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEngiSelfDestruct] > 0.99 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                        local iEngiCategoryWanted
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer * categories.TECH3
                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 then iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer - categories.TECH1
                        else iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer
                        end
                        local iCurEngis = 0
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            iCurEngis = iCurEngis + oBrain:GetCurrentUnits(iEngiCategoryWanted)
                        end
                        iCurEngis = iCurEngis / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]

                        if iCurEngis >= 10 then
                            --If are defending against arti then want a lot more engineers before start considering ctrl-king any
                            if (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and (iCurEngis >= 40 or (GetGameTimeSeconds() >= 300 and iCurEngis >= 25 - GetGameTimeSeconds() / 60))) or iCurEngis >= 70 then
                                bConsiderReclaimingEngineer = true
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Time of last engi self destruct='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEngiSelfDestruct]..'; bConsiderReclaimingEngineer='..tostring(bConsiderReclaimingEngineer)) end
                else
                    iCategoryStartPoint = table.getn(tCategoriesByPriority)
                    iIntervalChange = -1
                    iCategoryEndPoint = 1
                end

                local bConsideringHQ
                local bConsideringTeamWideUnits = false
                local bNoRelevantUnits = true

                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': About to cycle through every category, bPauseNotUnpause=' .. tostring(bPauseNotUnpause) .. '; iCategoryStartPoint=' .. iCategoryStartPoint .. '; iCategoryEndPoint=' .. iCategoryEndPoint)
                end
                for iCategoryCount = iCategoryStartPoint, iCategoryEndPoint, iIntervalChange do
                    local tRelevantUnits
                    iCategoryRef = tCategoriesByPriority[iCategoryCount]

                    --Are we considering upgrading factory HQs?
                    if iCategoryRef == iSpecialHQCategory then
                        iCategoryRef = AiBotUnitInfo.refCategoryAllHQFactories
                        bConsideringHQ = true
                        bConsideringTeamWideUnits = false
                    else
                        if iCategoryRef == iSpecialSurplusUpgradeCategory then
                            bConsideringTeamWideUnits = true
                        else
                            bConsideringTeamWideUnits = false
                        end
                        bConsideringHQ = false
                    end

                    local iCurUnitMassUsage
                    local bApplyActionToUnit
                    local oBP
                    local oFocusUnitBP
                    local bFirstEngiCategoryRefBrain = true
                    bFirstBrain = true
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        if oBrain.CheatEnabled then iBuildRateMod = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier]
                        else iBuildRateMod = 1
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; oBrain='..oBrain.Nickname..'; refbBuiltParagon='..tostring(oBrain[refbBuiltParagon] or false)) end

                        if bPauseNotUnpause then
                            if oBrain[refbBuiltParagon] then
                                if bDebugMessages == true then LOG(sFunctionRef..': This brain has built a paragon so wont search for units to pause') end
                                tRelevantUnits = nil
                            elseif iCategoryRef == iSpecialSurplusUpgradeCategory then
                                --Pause all but 1 upgrade per brain, pausing the lowest progress first, if we have multiple upgrades.  Dont pause the last mex upgrade. also dont pause anything that is >=85% complete
                                tRelevantUnits = {}
                                if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) then
                                    local iMexesToPause
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 2.5 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                        iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (0.5 + 0.5 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))
                                    else
                                        --Get highest tech level of mex that is upgrading, and how many of that mex we already have; if we already have several, then pause fewer mexes
                                        local bUpgradingT2OrT3Mex = false
                                        for iMex, oMex in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                                            if EntityCategoryContains(categories.TECH2 + categories.TECH3, oMex.UnitId) then
                                                bUpgradingT2OrT3Mex = true
                                                break
                                            end
                                        end
                                        local iExistingMexesOfTech = 0
                                        for iMexBrain, oMexBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                            if bUpgradingT2OrT3Mex then  iExistingMexesOfTech = iExistingMexesOfTech + oMexBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex - categories.TECH1 - categories.TECH2)
                                            else iExistingMexesOfTech = iExistingMexesOfTech + oMexBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex - categories.TECH1)
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iExistingMexesOfTech='..iExistingMexesOfTech) end
                                        if iExistingMexesOfTech >= 1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                            if iExistingMexesOfTech >= 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                                if iExistingMexesOfTech >= 3 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                                    iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (0.25 + 1.2 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))
                                                else
                                                    iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))
                                                end
                                            else
                                                iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (0.25 + 0.75 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))
                                            end
                                        else
                                            iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (0.5 + 0.5 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))
                                        end
                                    end
                                    --Want to allow multiple upgrading mexes for a brain if we have lots of mexes
                                    if iMexesToPause > 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 14 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] > 10 and AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3])) then
                                        local iMexPerPlayer
                                        if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or AiBotMap.iMapSize > 1024 then iMexPerPlayer = 1 + (oBrain[refiGrossMassBaseIncome] / 6)*0.45
                                        elseif AiBotMap.iMapSize >= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 then iMexPerPlayer = 0.5 + (oBrain[refiGrossMassBaseIncome] / 6)*0.4
                                        else iMexPerPlayer = 0.5 + (oBrain[refiGrossMassBaseIncome] / 6)*0.3
                                        end
                                        if AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] then iMexPerPlayer = iMexPerPlayer * 2.5 end
                                        iMexesToPause = math.min(iMexesToPause, math.max(0, table.getn(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (0.5 + iMexPerPlayer * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount])))
                                    end

                                    --LOUD - pause fewer mexes due to greater need to focus on ecoing
                                    if iMexesToPause > 0 and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbPrioritiseProduction]) and oBrain[refiGrossMassBaseIncome] >= 3 then
                                        iMexesToPause = math.max(0, iMexesToPause - 1)
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iMexesToPause for brain '..oBrain.Nickname..'='..iMexesToPause..'; Numbero f upgrading mexes='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])..'; Team gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end

                                    while iMexesToPause > 0 do
                                        local iLowestProgress = 0.8
                                        local oLowestProgress
                                        local bAlreadyIncluded
                                        for iUnit, oUnit in AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Start of loop for the lowest mex to pause, iMexesToPause='..iMexesToPause..'; Considering mex '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Work progress='..oUnit:GetWorkProgress()..'; iLowestProgress='..iLowestProgress..'; Mex owner='..oUnit:GetAIBrain().Nickname) end
                                            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetWorkProgress() < iLowestProgress and not(oUnit:GetAIBrain()[refbBuiltParagon]) then
                                                bAlreadyIncluded = false
                                                --Is the unit already in the table of relevant units?
                                                if AiBotUtilities.IsTableEmpty(tRelevantUnits) == false then
                                                    for iRecordedUnit, oRecordedUnit in tRelevantUnits do
                                                        if oRecordedUnit == oUnit then bAlreadyIncluded = true break end
                                                    end
                                                end
                                                if not(bAlreadyIncluded) then
                                                    oLowestProgress = oUnit
                                                    iLowestProgress = oUnit:GetWorkProgress()
                                                end
                                            end
                                        end
                                        if oLowestProgress then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding oLowestProgress='..oLowestProgress.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLowestProgress)..' owned by '..oLowestProgress:GetAIBrain().Nickname..' to table of units to pause') end
                                            table.insert(tRelevantUnits, oLowestProgress)
                                        else
                                            break
                                        end
                                        iMexesToPause = iMexesToPause - 1
                                    end
                                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotUtilities.IsTableEmpty(tRelevantUnits) == false then
                                        --Further check for loud - dont pause any T3 mex upgrades since they arem ore efficient
                                        for iCurRelevantUnitEntry = table.getn(tRelevantUnits), 1, -1 do
                                            local oCurRelevantUnit = tRelevantUnits[iCurRelevantUnitEntry]
                                            if EntityCategoryContains(categories.TECH3, oCurRelevantUnit.UnitId) then
                                                table.remove(tRelevantUnits, iCurRelevantUnitEntry)
                                            end
                                        end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingOther]) == false then
                                    for iUnit, oUnit in AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingOther] do
                                        if not(oUnit.Dead) and not(oUnit:GetAIBrain()[refbBuiltParagon]) then
                                            table.insert(tRelevantUnits, oUnit)
                                        end
                                    end
                                end
                            else
                                tRelevantUnits = oBrain:GetListOfUnits(iCategoryRef, false, true)
                            end
                        else
                            if bFirstBrain then
                                tRelevantUnits = AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority][iCategoryCount]
                                bFirstBrain = false
                            else
                                break
                            end
                        end


                        if AiBotUtilities.IsTableEmpty(tRelevantUnits) == false then
                            bNoRelevantUnits = false
                            iTotalUnits = table.getn(tRelevantUnits)
                            if bDebugMessages == true then
                                LOG(sFunctionRef .. ': iCategoryCount=' .. iCategoryCount .. '; iTotalUnits=' .. iTotalUnits .. '; bPauseNotUnpause=' .. tostring(bPauseNotUnpause))
                            end
                            if iCategoryRef == AiBotUnitInfo.refCategoryEngineer then
                                if bFirstEngiCategoryRefBrain then
                                    iEngineerSubtableCount = iEngineerSubtableCount + 1
                                    bFirstEngiCategoryRefBrain = false
                                end
                                tEngineerActionSubtable = tEngineerActionsByPriority[iEngineerSubtableCount]
                            end
                            for iUnit = iTotalUnits, 1, -1 do
                                oUnit = tRelevantUnits[iUnit]

                                --for iUnit, oUnit in tRelevantUnits do
                                bApplyActionToUnit = false
                                iCurUnitMassUsage = 0
                                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then --Only consider unit if it has been constructed
                                    if not(bPauseNotUnpause) then
                                        bApplyActionToUnit = true
                                        if (oUnit.GetTacticalSiloAmmoCount or oUnit.GetTacticalSiloAmmoCount) and AiBotUnitInfo.GetMissileCount(oUnit) >= 2 then
                                            --Dont unpause TML, SML and SMD that have 2+ missiles loaded already
                                            bApplyActionToUnit = false
                                        end
                                    else
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef .. ': About to consider pausing unit ' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit) .. '; will first check category specific logic for if we want to go ahead with pausing4')
                                            if oUnit.GetWorkProgress then
                                                local oUnitTarget = oUnit:GetFocusUnit()
                                                if oUnitTarget then
                                                    LOG(sFunctionRef..': Work progress='..oUnit:GetWorkProgress()..'; oUnitTarget='..(oUnitTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitTarget) or 'nil'))
                                                else
                                                    LOG(sFunctionRef..': Work progress (no valid target)='..oUnit:GetWorkProgress())
                                                end
                                            end
                                        end


                                        --Do we actually want to pause the unit? check any category specific logic
                                        bApplyActionToUnit = true
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef .. ': UnitState=' .. AiBotUnitInfo.GetUnitState(oUnit) .. '; Is ActiveHQUpgrades Empty=' .. tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]))..'; bDontPauseUpgradingT1LandOrT2Land='..tostring(bDontPauseUpgradingT1LandOrT2Land)..'; Is unit upgrading='..tostring(oUnit:IsUnitState('Upgrading'))..'; refbPrimaryFactoryForIslandOrPond='..tostring(oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] or false)..'; oBrain[refiOurHighestLandFactoryTech]='..oBrain[refiOurHighestLandFactoryTech]..'; ')
                                        end
                                        --TML being used for a snipe - dont pause
                                        if oUnit[AiBotBuilding.refbSpecialLauncherTargeting] then
                                            bApplyActionToUnit = false
                                            --Factories, ACU and engineers - dont pause if >=85% done, or if is land factory that hasn't built many units (so e.g. if have just placed a land factory on a core expansion we dont immediately pause it)
                                        elseif oUnit.GetWorkProgress and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + categories.COMMAND + AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) and ((oUnit:GetWorkProgress() or 0) >= 0.85 or ((oUnit:GetWorkProgress() or 0) >= 0.8 and oUnit:GetFocusUnit().UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit:GetFocusUnit().UnitId)) or (EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) and (oUnit[AiBotFactory.refiTotalBuildCount] or 0) <= iMinBuildCountBeforePausingHQ and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or oBrain[refiOurHighestLandFactoryTech] <= AiBotUnitInfo.GetUnitTechLevel(oUnit)))) then
                                            bApplyActionToUnit = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Either 85% completion or pausing a land factory that hasnt built much') end
                                        elseif oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] then bApplyActionToUnit = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to pause primary factory for island/pond') end
                                            --Air HQ - dont pause first ever unit or transport
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirHQ, oUnit.UnitId) and (oUnit[AiBotFactory.refiTotalBuildCount] == 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, (oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'ueb1105'))) then
                                            bApplyActionToUnit = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to pause an air factory that hasnt built much') end
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) and ((bDontPauseUpgradingT1LandOrT2Land and (EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId or oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('BeingUpgraded'))) or oUnit[AiBotFactory.refiTotalBuildCount] <= 10)) then

                                            --Is this on a dif island to closest enemy base?
                                            local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                            if tUnitLZTeamData and not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tUnitLZTeamData[AiBotMap.reftClosestEnemyBase])) and (oUnit[AiBotFactory.refiTotalBuildCount] or 0) <= iMinBuildCountBeforePausingHQ * 3 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Different island to closest enemy base, and we havent built a certain level of units') end
                                                bApplyActionToUnit = false
                                            elseif bDontPauseUpgradingT1LandOrT2Land and (((oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('BeingUpgraded')) and EntityCategoryContains(categories.TECH1, oUnit.UnitId) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false) or EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory * categories.TECH2, oUnit.UnitId)) then
                                                for iFactory, oFactory in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs] do
                                                    if oUnit == oFactory then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Dont want to pause an upgrading HQ') end
                                                        bApplyActionToUnit = false
                                                        break
                                                    end
                                                end
                                            end
                                            --SMD LOGIC - Check if already have 1 missile loaded before pausing (we know we are in a pause unit scenario from above condition)
                                        elseif iCategoryRef == AiBotUnitInfo.refCategorySMD and oUnit.GetTacticalSiloAmmoCount and oUnit:GetTacticalSiloAmmoCount() == 0 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false then
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': Have SMD with at least 1 missile so will pause it')
                                            end
                                            bApplyActionToUnit = false
                                        elseif iCategoryRef == AiBotUnitInfo.refCategoryEngineer then
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': Have an engineer with action=' .. (oUnit[AiBotEngineer.refiAssignedAction] or 'nil') .. '; tEngineerActionSubtable=' .. repru(tEngineerActionSubtable))
                                            end
                                            bApplyActionToUnit = false
                                            if not(oUnit:IsUnitState('Attached')) then
                                                for iActionCount, iActionRef in tEngineerActionSubtable do
                                                    if iActionRef == oUnit[AiBotEngineer.refiAssignedAction] then
                                                        bApplyActionToUnit = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have an action match, iActionRef='..iActionRef..'; will apply action to unitunless have an override such as priamry power builder, oUnit[AiBotEngineer.refbPrimaryBuilder]='..tostring(oUnit[AiBotEngineer.refbPrimaryBuilder])) end
                                                        --Dont pause the last engi building power or GE Template, and also dont pause if are building PD/T2 Arti/Shield/Experimental and have a fraction complete of at least 70%
                                                        if oUnit[AiBotEngineer.refbPrimaryBuilder] and (iActionRef == AiBotEngineer.refActionBuildPower or iActionRef == AiBotEngineer.refActionBuildSecondPower or iActionRef == AiBotEngineer.refActionManageGameEnderTemplate) then
                                                            bApplyActionToUnit = false
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with primary builder that is building power or GE template so wont pause') end
                                                        elseif oUnit.GetFocusUnit then
                                                            local oFocusUnit = oUnit:GetFocusUnit()
                                                            if bDebugMessages == true then
                                                                if AiBotUnitInfo.IsUnitValid(oFocusUnit) then
                                                                    LOG(sFunctionRef..': Considering engineer '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; UC='..AiBotEngineer.GetEngineerUniqueCount(oUnit)..'; Focus unit='..oFocusUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit)..'; Fraction complete='..oFocusUnit:GetFractionComplete())
                                                                else LOG(sFunctionRef..': Focus unit for engineer '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; UC='..AiBotEngineer.GetEngineerUniqueCount(oUnit)..' isnt valid') end
                                                            end
                                                            if AiBotUnitInfo.IsUnitValid(oFocusUnit) then
                                                                if oFocusUnit:GetFractionComplete() >= 0.7 and oFocusUnit:GetFractionComplete() < 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryExperimentalLevel, oFocusUnit.UnitId) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Wont apply action to unit as it is PD/Arti/Experimental') end
                                                                    bApplyActionToUnit = false
                                                                    if oUnit[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseMassUsage(oUnit, false, iTeam, iCategoryCount) end
                                                                elseif iActionRef == AiBotEngineer.refActionBuildLandFactory and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.TECH3, oFocusUnit.UnitId) and oBrain[refiGrossMassBaseIncome] >= 1.4 then
                                                                    local tEngiZone, tEngiTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Are building al and fac, wont pause if not in core zone, tEngiTeamData[AiBotMap.subrefLZbCoreBase]='..tostring(tEngiTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
                                                                    if not(tEngiTeamData[AiBotMap.subrefLZbCoreBase]) then
                                                                        --Keep building expansion land fac
                                                                        bApplyActionToUnit = false
                                                                    end
                                                                end
                                                                --exception - primary engi trying to build land fac, and not in core zone
                                                            elseif iActionRef == AiBotEngineer.refActionBuildLandFactory then
                                                                local sBlueprint = oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]
                                                                if not(sBlueprint) and oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGuard then sBlueprint = oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget][AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] end
                                                                if sBlueprint and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.TECH3, sBlueprint) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': We have queued up a land fac, want to build it if we are not in a core zone (since presumably are at an expansion point') end
                                                                    local tEngiZone, tEngiTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                                                    if not(tEngiTeamData[AiBotMap.subrefLZbCoreBase]) then
                                                                        bApplyActionToUnit = false
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        if oBrainWithParagon and bApplyActionToUnit and not(oUnit[AiBotEngineer.refbPrimaryBuilder]) then
                                                            bApplyActionToUnit = false
                                                            AiBotTeam.TransferUnitsToPlayer({ oUnit }, oBrainWithParagon:GetArmyIndex(), false)
                                                        end
                                                        if bApplyActionToUnit and bConsiderReclaimingEngineer and not(oUnit[AiBotEngineer.refbPrimaryBuilder]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()]) <= 90 then
                                                            --Is there reclaim near the engineer? If so clear its orders and have it reclaim, otherwise kill it
                                                            local oBP = oUnit:GetBlueprint()
                                                            if oBP.Economy.BuildCostMass < 500 and oBP.Economy.MaxBuildDistance then --redundancy so we dont ctrl-K SACUs or a unit with no build radius
                                                                bApplyActionToUnit = false


                                                                function KillEngineer(oUnit)
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': About to kill engineer '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; unless it is T3 and there is a T1 or T2 engi we can kill instead in the same zone') end
                                                                    local oEngiToKill = GetBestEngiToKill(oUnit)
                                                                    if AiBotUnitInfo.GetUnitTechLevel(oEngiToKill) == 1 and oBrain[refiOurHighestFactoryTechLevel] > 1 then iKillCount = iKillCount + 0.5
                                                                    else iKillCount = iKillCount + 1
                                                                    end
                                                                    AiBotOrders.IssueTrackedKillUnit(oEngiToKill)
                                                                    if iKillCount >= 2 then
                                                                        bConsiderReclaimingEngineer = false
                                                                    end
                                                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEngiSelfDestruct] = GetGameTimeSeconds()
                                                                end
                                                                iCurPlateau, iCurLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                                                                if (iCurPlateau or 0) > 0 and (iCurLandZone or 0) > 0 then
                                                                    if AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone][AiBotMap.subrefTotalMassReclaim] > 30 then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': About to tell unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to clear its current orders and try to reclaim nearby area due to mass stall') end
                                                                        AiBotOrders.IssueTrackedClearCommands(oUnit)
                                                                        AiBotEngineer.GetEngineerToReclaimNearbyArea(oUnit, 1, AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone][AiBotMap.subrefLZTeamData][iTeam], iCurPlateau, iCurLandZone, false, true)
                                                                        --Kill engineers if htey are in a core LZ
                                                                    elseif AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) then
                                                                        KillEngineer(oUnit)
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        break
                                                    end
                                                end
                                            end
                                        elseif iCategoryRef == AiBotUnitInfo.refCategoryPersonalShield or iCategoryRef == AiBotUnitInfo.refCategoryFixedShield or iCategoryRef == AiBotUnitInfo.refCategoryMobileLandShield then
                                            --Mass stalling so pausing shield not expected to do anything
                                            bApplyActionToUnit = false
                                        elseif iCategoryRef == AiBotUnitInfo.refCategoryTML and AiBotUnitInfo.GetMissileCount(oUnit) == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.2 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with TML that has no missile so dont want to pause it') end
                                            bApplyActionToUnit = false
                                        --Dont pause t1-t2 mexes that arent upgrading due to bug where pausing the unit causes it to get mass without the energy cost
                                        elseif (iCategoryRef == AiBotUnitInfo.refCategoryT2Mex or iCategoryRef == AiBotUnitInfo.refCategoryT1Mex) then
                                            --dont pause if the unit isnt upgrading
                                            if not(oUnit.UnitBeingBuilt) and (not(oUnit.GetWorkprogress) or (oUnit:GetWorkProgress() or 0) == 0) and not(oUnit:IsUnitState('Upgrading')) then
                                                bApplyActionToUnit = false
                                            end
                                        end



                                        if iCategoryRef == categories.COMMAND then
                                            --want in addition to above as ACU might have personal shield

                                            if oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('BeingUpgraded') then
                                                bApplyActionToUnit = false
                                            elseif oUnit.GetWorkProgress then
                                                --if oUnit:GetWorkProgress() >= 0.85 then
                                                bApplyActionToUnit = false
                                                --dont pause t1 mex construction
                                                if oUnit.GetFocusUnit and oUnit:GetFocusUnit() and oUnit:GetFocusUnit().UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oUnit:GetFocusUnit().UnitId) then
                                                    bApplyActionToUnit = false
                                                end
                                            end
                                        end
                                    end
                                end


                                --Pause/unpause the unit

                                if bApplyActionToUnit then
                                    bWasUnitAlreadyPaused = oUnit[AiBotUnitInfo.refbPaused] --Means we will ignore the mass usage when calculating how much we have saved
                                    oBP = oUnit:GetBlueprint()
                                    iCurUnitMassUsage = oBP.Economy.MaintenanceConsumptionPerSecondMass

                                    if (iCurUnitMassUsage or 0) == 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryMex + categories.COMMAND, oUnit.UnitId) then
                                        --Approximate mass usage based on build rate as a very rough guide
                                        --examples: Upgrading mex to T3 costs 11E per BP; T3 power is 8.4; T1 power is 6; Guncom is 30; Laser is 178; Strat bomber is 15
                                        local iMassPerBP = 0.25 --e.g. building t1 land factory uses 4; building a titan uses 1.1; divide by 10 as dealing with values per tick
                                        if EntityCategoryContains(categories.SILO, oUnit.UnitId) and oBP.Economy.BuildRate then
                                            --Dealing with a silo so need to calculate mass usage differently
                                            iCurUnitMassUsage = 0
                                            if oBP.Weapon and type(oBP.Weapon) == "table" then
                                                for iWeapon, tWeapon in oBP.Weapon do
                                                    if tWeapon.MaxProjectileStorage and tWeapon.ProjectileId then
                                                        local oProjectileBP = __blueprints[tWeapon.ProjectileId]
                                                        if oProjectileBP.Economy and oProjectileBP.Economy.BuildCostMass and oProjectileBP.Economy.BuildTime > 0 and oBP.Economy.BuildRate > 0 then
                                                            iCurUnitMassUsage = oProjectileBP.Economy.BuildCostMass * oBP.Economy.BuildRate * iBuildRateMod / oProjectileBP.Economy.BuildTime
                                                            --If are power stalling then assume we only save 80% of this, as might have adjacency
                                                            if bPauseNotUnpause then iCurUnitMassUsage = iCurUnitMassUsage * 0.8 end
                                                            break
                                                        end
                                                    end
                                                end
                                            else
                                                AiBotUtilities.ErrorHandler('Have silo without weapon')
                                            end

                                        else
                                            if iCategoryRef == categories.COMMAND and oUnit[AiBotOrders.refiOrderCount] > 0 and oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderEnhancement then
                                                --Determine mass cost per BP
                                                local sUpgradeRef = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint]
                                                if bDebugMessages == true then LOG(sFunctionRef..': aiBrain='..oUnit:GetAIBrain():GetArmyIndex()..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; sUpgradeRef='..(sUpgradeRef or 'nil')..'; Upgrade mass cost='..(AiBotUnitInfo.GetUpgradeMassCost(oUnit, sUpgradeRef) or 'nil')..'; Upgrade build time='..(AiBotUnitInfo.GetUpgradeBuildTime(oUnit, sUpgradeRef) or 'nil')) end
                                                iMassPerBP = AiBotUnitInfo.GetUpgradeMassCost(oUnit, sUpgradeRef) / (AiBotUnitInfo.GetUpgradeBuildTime(oUnit, sUpgradeRef) or 1)
                                            end

                                            if oBP.Economy.BuildRate then
                                                --Reduce this massively if unit isn't actually building anything
                                                if bPauseNotUnpause then
                                                    if (not(oUnit:IsUnitState('Building')) and not(oUnit:IsUnitState('Repairing')) and not(oUnit.GetWorkProgress and oUnit:GetWorkProgress() > 0) and not(oUnit:IsUnitState('Upgrading')) and not(oUnit:IsUnitState('BeingUpgraded'))) then
                                                        iCurUnitMassUsage = oBP.Economy.BuildRate * iBuildRateMod * 0.01
                                                    else
                                                        if AiBotUnitInfo.IsUnitValid(oUnit:GetFocusUnit()) then
                                                            oFocusUnitBP = oUnit:GetFocusUnit():GetBlueprint()
                                                            iCurUnitMassUsage = oBP.Economy.BuildRate * iBuildRateMod / oFocusUnitBP.Economy.BuildTime * oFocusUnitBP.Economy.BuildCostMass
                                                            oUnit[refiLastMassUsage] = iCurUnitMassUsage
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Setting unit last mass usage to '..oUnit[refiLastMassUsage]..'; Build rate='..oBP.Economy.BuildRate..'; Focus unit build time='..oFocusUnitBP.Economy.BuildTime..'; Focus unit build cost mass='..oFocusUnitBP.Economy.BuildCostMass..'; Build rate mod='..iBuildRateMod) end
                                                        else
                                                            iCurUnitMassUsage = oBP.Economy.BuildRate * iBuildRateMod *  iMassPerBP
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking for what the unit is building or upgrading to get more accurate calculation, unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; mass usage after check='..iCurUnitMassUsage..'; Is focus unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit:GetFocusUnit()))) end
                                                else
                                                    iCurUnitMassUsage = (oUnit[refiLastMassUsage] or oBP.Economy.BuildRate * iBuildRateMod * iMassPerBP)
                                                end
                                            end
                                        end
                                    end
                                    --We're working in ticks so adjust mass usage accordingly
                                    iCurUnitMassUsage = iCurUnitMassUsage * 0.1
                                    if bDebugMessages == true then
                                        LOG(sFunctionRef .. ': Estimated mass usage=' .. iCurUnitMassUsage..'; About to call the function PauseOrUnpauseMassUsage on unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; iUnitsAdjusted before counting this unit='..iUnitsAdjusted..'; Unit brain owner='..oUnit:GetAIBrain().Nickname)
                                    end

                                    if not((iCurUnitMassUsage or 0) == 0) then iUnitsAdjusted = iUnitsAdjusted + 1 end
                                    AiBotUnitInfo.PauseOrUnpauseMassUsage(oUnit, bPauseNotUnpause, iTeam, iCategoryCount)
                                    --Cant move the below into unitinfo as get a crash if unitinfo tries to refernce the table of paused units
                                    --Have made localised variable which looks to fix the issue
                                end
                                if bApplyActionToUnit then
                                    if bPauseNotUnpause and not(bWasUnitAlreadyPaused) then
                                        iMassSavingManaged = iMassSavingManaged + iCurUnitMassUsage
                                    elseif bWasUnitAlreadyPaused and not (bPauseNotUnpause) then
                                        iMassSavingManaged = iMassSavingManaged - iCurUnitMassUsage
                                    end
                                end
                                if bDebugMessages == true then
                                    LOG(sFunctionRef .. ': iMassSavingManaged=' .. iMassSavingManaged .. '; iMassPerTickSavingNeeded=' .. iMassPerTickSavingNeeded .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; bWasUnitAlreadyPaused='..tostring(bWasUnitAlreadyPaused)..'; bApplyActionToUnit='..tostring(bApplyActionToUnit)..'; iCurUnitMassUsage='..iCurUnitMassUsage)
                                end

                                if bPauseNotUnpause then
                                    if iMassSavingManaged > iMassPerTickSavingNeeded then
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef .. ': Estimate we have saved ' .. iMassSavingManaged .. ' which is more tahn we wanted so will pause')
                                        end
                                        bAbort = true
                                        break
                                    end
                                else
                                    if iMassSavingManaged < iMassPerTickSavingNeeded then
                                        bAbort = true
                                        break
                                    end
                                end
                            end
                        elseif bDebugMessages == true then
                            LOG(sFunctionRef .. ': We have no units for iCategoryCount=' .. iCategoryCount)
                        end

                        if bAbort then
                            break
                        end
                        if bConsideringTeamWideUnits then break end --dont want to consider for more than one brain
                    end
                    if bAbort then
                        break
                    end
                end
                if bDebugMessages == true then
                    LOG(sFunctionRef .. 'If we have no paused units then will set us as not having a mass stall')
                end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] <= 0 then
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] = false
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': We are no longer stalling mass, setting paused unit count to 0 (it was already <=0)')
                    end
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] = 0
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables] = nil
                else
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': About to check if we wanted to unpause units but havent unpaused anything; iUnitsAdjusted=' .. iUnitsAdjusted .. '; bNoRelevantUnits=' .. tostring(bNoRelevantUnits) .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))
                    end
                    --Backup - sometimes we still have units in the table listed as being paused (e.g. if an engineer changes action to one that isnt listed as needing pausing) - unpause them if we couldnt find via category search
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] and not (bPauseNotUnpause) and (iMassSavingManaged > iMassPerTickSavingNeeded or iUnitsAdjusted == 0 or bNoRelevantUnits) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.03 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.9 then
                        --Have a decent amount of mass, are flagged as stalling mass, but couldnt find any categories to unpause
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': werent able to find any units to unpause with normal approach so will unpause all remaining units')
                        end
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority]) == false then
                            for iCategory, tUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                                if tUnits then
                                    local iUnitCount = table.getn(tUnits)
                                    if iUnitCount > 0 then
                                        for iCurUnit = iUnitCount, 1, -1 do
                                            if AiBotUnitInfo.IsUnitValid(tUnits[iCurUnit]) then
                                                AiBotUnitInfo.PauseOrUnpauseMassUsage(tUnits[iCurUnit], false, iTeam)
                                            end
                                        end
                                    end
                                end
                                tUnits = nil
                            end
                        end
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] = false
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] = 0
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables] = nil

                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': FInished unpausing any remaining units and resetting the staling mass flag')
                        end
                    end
                end
            end
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': End of code, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) .. '; Stalling energy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; bPauseNotUnpause=' .. tostring(bPauseNotUnpause) .. '; iUnitsAdjusted=' .. iUnitsAdjusted .. '; Game time=' .. GetGameTimeSeconds() .. '; Mass stored %=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] .. '; Net mass income=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] .. '; gross mass income=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; refiPausedUnitCount='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount])
            end
        end
    else
        AiBotUtilities.ErrorHandler('No active AiBot brains')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageEnergyStalls(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageEnergyStalls'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        local bOnlyEasyAI = true
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if not(oBrain.AiBotEasy) then bOnlyEasyAI = false break end
        end
        if not(bOnlyEasyAI) or GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastConsideredEnergyStall] or -10) >= 2.99 then
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastConsideredEnergyStall] = GetGameTimeSeconds()
            local bPauseNotUnpause = true
            local bChangeRequired = false
            local iUnitsAdjusted = 0
            local bHaveWeCappedUnpauseAmount = false
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (GetGameTimeSeconds() >= 120 or (GetGameTimeSeconds() >= 40 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 15)) then
                --Only consider power stall management after 2m, otherwise risk pausing things such as early microbots when we would probably be ok after a couple of seconds; lower time limit put in as a theroetical possibility due to AIX
                if bDebugMessages == true then LOG(sFunctionRef .. ': About to consider if we have an energy stall or not. Lowest energy % stored=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
                --First consider unpausing
                if bDebugMessages == true then LOG(sFunctionRef .. ': If we have flagged that we are stalling energy then will check if we have enough to start unpausing things') end

                local iPercentMod = 0
                local iNetMod = 0

                --Also increase net energy if are at tech 3 and lack 3k power
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 300 then iNetMod = iNetMod + 25 end

                    iPercentMod = math.max(0.05, iPercentMod)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': If are in stall mode will check if want to come out. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Gross income='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Stored ratio='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; Net income='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; iNetMod='..iNetMod..'; iPercentMod='..iPercentMod..'; GameTime='..GetGameTimeSeconds()..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled]..'; Changei n power since then='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled]) end

                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 800 then iPercentMod = math.max(iPercentMod,  math.min(iPercentMod + 0.2, 0.275)) end

                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] >= 45 then
                    iPercentMod = iPercentMod -0.3
                end

                --Overcharge - pause even if we dont have terrible E income
                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNeededEnergyForOvercharge] or -10) <= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < 0.9 then
                    bPauseNotUnpause = true
                    iPercentMod = math.max(0.5, iPercentMod)
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU needs energy so will set percentmod to 50% at time '..GetGameTimeSeconds()) end
                end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] >= 200000 and iPercentMod > -0.6 then iPercentMod = iPercentMod - 0.1 end


                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 100000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > math.min(0.95, (0.8 + iPercentMod)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > (0.7 + iPercentMod) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > (1 + iNetMod)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > (0.5 + iPercentMod) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > (4 + iNetMod)) or (GetGameTimeSeconds() <= 180 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] * 1.2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > 250 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 0) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > 0.1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > 25000)))))) then
                    --AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] = false
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': Have enough energy stored or income to start unpausing things if any are paused, refiPausedUnitCount='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount])
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] > 0 then
                            local iShieldsAndRadarPaused = 0
                            for iPriority, tUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                                local tShieldsAndRadarPaused = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAllShieldUnits + AiBotUnitInfo.refCategoryRadar, tUnits)
                                if AiBotUtilities.IsTableEmpty(tShieldsAndRadarPaused) == false then
                                    LOG(sFunctionRef..': iPriority '..iPriority..' has '..table.getn(tShieldsAndRadarPaused)..' units with shield or radar that are paused')
                                end
                                iShieldsAndRadarPaused = iShieldsAndRadarPaused + table.getn(tShieldsAndRadarPaused)
                            end
                            LOG(sFunctionRef..': tShieldsAndRadarPaused in total='..iShieldsAndRadarPaused)
                        end
                    end
                    bPauseNotUnpause = false
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then bChangeRequired = true end
                end
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': Checking if we shoudl flag that we are energy stalling; bChangeRequired='..tostring(bChangeRequired)..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))
                end

                if not(bChangeRequired) and not(bPauseNotUnpause) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                    --We arent stalling so shouldnt have any units that are paused; Cycle thorugh each brain and check that the only units that are paused are missile launchers with loaded missiles
                    local bHaveUnexpectedlyPausedUnits = false
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] > 0 then --This section is a redundancy as came across scenario where had paused factories and launchers when not stalling, and logs indicated we didnt think we were stalling
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority]) == false then
                            for iCategory, tUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                                if tUnits then
                                    for iUnit, oUnit in tUnits do
                                        if not(EntityCategoryContains(categories.SILO * categories.NUKE + AiBotUnitInfo.refCategorySMD + AiBotUnitInfo.refCategoryTML, oUnit.UnitId)) then
                                            bHaveUnexpectedlyPausedUnits = true
                                            break
                                        else
                                            if AiBotUnitInfo.GetMissileCount(oUnit) == 0 then
                                                bHaveUnexpectedlyPausedUnits = true
                                                break
                                            end
                                        end
                                    end
                                    if bHaveUnexpectedlyPausedUnits then break end
                                end
                            end

                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]..'; bHaveUnexpectedlyPausedUnits='..tostring(bHaveUnexpectedlyPausedUnits)) end
                    end
                    if bHaveUnexpectedlyPausedUnits then
                        bChangeRequired = true
                    end
                end
                --Check if should manage energy stall
                if bChangeRequired == false and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= (0.08 + iPercentMod) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= (0.6 + iPercentMod) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < (2 + iNetMod)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= (0.4 + iPercentMod) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < (0.5 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] - 1) * 5 + iNetMod))) then
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': We are stalling energy, will look for units to pause, subject to early game check')
                    end
                    --If this is early game then add extra check
                    if GetGameTimeSeconds() >= 180 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.04 then
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] = true
                        bChangeRequired = true
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] end
                        if bDebugMessages == true then LOG(sFunctionRef..': early game check cleared, so are stalling energy') end
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': Will move on to main pause or unpause logic now if change is required, bChangeRequired='..tostring(bChangeRequired)..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)) end

                if bChangeRequired then
                    --Consider if we want to hold off pausing a T1 land fac upgrading to T2 if enemy has T2 arti threat (since we need MMLs)
                    local bDontPauseUpgradingT1LandOrT2Land = false
                    local bStopPausingIfGotToFactoriesAndHaveSomeEnergy = false
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] < 3 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false then
                        for iFactory, oFactory in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs] do
                            if AiBotUnitInfo.IsUnitValid(oFactory) then
                                local tFactoryLZData, tFactoryLZTeamData = AiBotMap.GetLandOrWaterZoneData(oFactory:GetPosition(), true, iTeam)
                                if tFactoryLZTeamData and AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tFactoryLZData, tFactoryLZTeamData, oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1], iTeam, true) then
                                    bDontPauseUpgradingT1LandOrT2Land = true
                                    break
                                end
                            end
                        end

                    end

                    if bPauseNotUnpause then
                        if bDebugMessages == true then LOG(sFunctionRef..': Change is required and we want to pause units, time='..GetGameTimeSeconds()) end
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] = true
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] end
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.25 then bStopPausingIfGotToFactoriesAndHaveSomeEnergy = true end
                    end --redundancy
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] = GetGameTimeSeconds() --Have even if unpausing, since we may only unpause some of the units
                    --Decide on order to pause/unpause

                    local tCategoriesByPriority, tEngineerActionsByPriority = GetCategoryAndActionsToPauseWhenStalling(iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': tCategoriesByPriority='..reprs(tCategoriesByPriority)) end

                    local iEnergyPerTickSavingNeeded
                    if bPauseNotUnpause then
                        iEnergyPerTickSavingNeeded = math.max(1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] + iNetMod * 0.5 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.02)
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.15 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have less than 15% energy stored so increasing the energy saving wanted. iEnergyPerTickSavingNeeded pre increase='..iEnergyPerTickSavingNeeded..'; Gross base income='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Team lowest energy storage units='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]) end
                            local iStorageFactor = 50
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1000 then iStorageFactor = 100 end
                            iEnergyPerTickSavingNeeded = math.max(iEnergyPerTickSavingNeeded * 1.3, iEnergyPerTickSavingNeeded + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.03)
                            iEnergyPerTickSavingNeeded = math.max(iEnergyPerTickSavingNeeded, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.06, math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] * iStorageFactor, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]*0.15))
                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.225 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Less than 22.5% energy stored so increasing energy saving slightly') end
                            iEnergyPerTickSavingNeeded = math.max(iEnergyPerTickSavingNeeded * 1.15, iEnergyPerTickSavingNeeded + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.015)
                        end
                    else
                        iEnergyPerTickSavingNeeded = math.min(-1, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy], -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] / 30)
                        iEnergyPerTickSavingNeeded = math.max(iEnergyPerTickSavingNeeded, math.min(-300, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] * 0.5), math.min(-600, -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] * 0.25))
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.75 then iEnergyPerTickSavingNeeded = iEnergyPerTickSavingNeeded * 0.75 end
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to start unpausing things, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; iEnergyPerTickSavingNeeded='..iEnergyPerTickSavingNeeded) end
                    end

                    local iEnergySavingManaged = 0
                    local iEngineerSubtableCount = 0
                    local tEngineerActionSubtable
                    local oUnit
                    local iBuildRateMod

                    local bAbort = false
                    local iTotalUnits = 0
                    local iCategoryStartPoint, iIntervalChange, iCategoryEndPoint, iCategoryRef
                    local bWasUnitAlreadyPaused
                    if bPauseNotUnpause then
                        iCategoryStartPoint = 1
                        iIntervalChange = 1
                        iCategoryEndPoint = table.getn(tCategoriesByPriority)
                    else
                        iCategoryStartPoint = table.getn(tCategoriesByPriority)
                        iIntervalChange = -1
                        iCategoryEndPoint = 1
                    end

                    local bConsideringHQ
                    local bConsideringTeamWideUnits = false
                    local bNoRelevantUnits = true

                    if bDebugMessages == true then LOG(sFunctionRef .. ': About to cycle through every category, bPauseNotUnpause=' .. tostring(bPauseNotUnpause) .. '; iCategoryStartPoint=' .. iCategoryStartPoint .. '; iCategoryEndPoint=' .. iCategoryEndPoint..'; iEnergyPerTickSavingNeeded='..iEnergyPerTickSavingNeeded) end

                    local bConsideringFactory
                    local bFirstBrain, bUnpauseThisUnit
                    for iCategoryCount = iCategoryStartPoint, iCategoryEndPoint, iIntervalChange do
                        local tRelevantUnits
                        iCategoryRef = tCategoriesByPriority[iCategoryCount]
                        bConsideringFactory = false

                        --Are we considering upgrading factory HQs?
                        if iCategoryRef == iSpecialHQCategory then
                            iCategoryRef = AiBotUnitInfo.refCategoryAllHQFactories
                            bConsideringHQ = true
                            bConsideringTeamWideUnits = false
                        else
                            if iCategoryRef == iSpecialSurplusUpgradeCategory then
                                bConsideringTeamWideUnits = true
                            else
                                bConsideringTeamWideUnits = false
                            end
                            bConsideringHQ = false
                        end

                        local iCurUnitEnergyUsage
                        local bApplyActionToUnit
                        local oBP
                        local oFocusUnitBP
                        local bFirstEngiCategoryRefBrain = true


                        bFirstBrain = true
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            if oBrain.CheatEnabled then iBuildRateMod = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier]
                            else iBuildRateMod = 1
                            end
                            if bPauseNotUnpause then
                                if oBrain[refbBuiltParagon] and (oBrain:GetEconomyStoredRatio('ENERGY') >= 0.1 or (oBrain:GetEconomyStoredRatio('ENERGY') >= 0.01 and oBrain:GetEconomyTrend('ENERGY') > 0)) then
                                    tRelevantUnits = nil
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have built paragon for brain '..oBrain.Nickname..' so wont pause units unless really low on energy for this brain') end
                                elseif iCategoryRef == iSpecialSurplusUpgradeCategory then
                                    --Pause all but 1 upgrade per brain, pausing the lowest progress first, if we have multiple upgrades
                                    tRelevantUnits = {}
                                    if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) then
                                        local iMexesToPause
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 150 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                            iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) - AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount])
                                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 35 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                            iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]))
                                        else
                                            iMexesToPause = math.max(0, table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) - (0.5 + 0.5 * AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))
                                        end

                                        while iMexesToPause > 0 do
                                            local iLowestProgress = 0.85
                                            local oLowestProgress
                                            local bAlreadyIncluded
                                            for iUnit, oUnit in AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                                                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetWorkProgress() < iLowestProgress and not(oUnit:GetAIBrain()[refbBuiltParagon]) then
                                                    bAlreadyIncluded = false
                                                    --Is the unit already in the table of relevant units?
                                                    if AiBotUtilities.IsTableEmpty(tRelevantUnits) == false then
                                                        for iRecordedUnit, oRecordedUnit in tRelevantUnits do
                                                            if oRecordedUnit == oUnit then bAlreadyIncluded = true break end
                                                        end
                                                    end
                                                    if not(bAlreadyIncluded) then
                                                        oLowestProgress = oUnit
                                                        iLowestProgress = oUnit:GetWorkProgress()
                                                    end
                                                end
                                            end
                                            if oLowestProgress then
                                                table.insert(tRelevantUnits, oLowestProgress)
                                            else
                                                break
                                            end
                                            iMexesToPause = iMexesToPause - 1
                                        end
                                    end
                                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingOther]) == false then
                                        for iUnit, oUnit in AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subreftTeamUpgradingOther] do
                                            if not(oUnit.Dead) and not(oUnit:GetAIBrain()[refbBuiltParagon]) then
                                                table.insert(tRelevantUnits, oUnit)
                                            end
                                        end
                                    end
                                else
                                    tRelevantUnits = oBrain:GetListOfUnits(iCategoryRef, false, true)
                                end
                            else
                                if bFirstBrain then
                                    tRelevantUnits = AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority][iCategoryCount]
                                    bFirstBrain = false
                                else
                                    break
                                end
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iCategoryCount='..iCategoryCount..' for brain '..oBrain.Nickname..'; Is table of relevant units empty='..tostring(AiBotUtilities.IsTableEmpty(tRelevantUnits))) end
                            if AiBotUtilities.IsTableEmpty(tRelevantUnits) == false then
                                if bFirstBrain then
                                    --Will be pausing if are in this scenario as bFirstBrain is set to false earlier on for unpausing
                                    bConsideringFactory = EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory + AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryNavalFactory - AiBotUnitInfo.refCategorySpecialFactory, tRelevantUnits[1].UnitId)
                                    bFirstBrain = false
                                end
                                bNoRelevantUnits = false
                                iTotalUnits = table.getn(tRelevantUnits)
                                if bDebugMessages == true then LOG(sFunctionRef .. ': iCategoryCount=' .. iCategoryCount .. '; iTotalUnits=' .. iTotalUnits .. '; bPauseNotUnpause=' .. tostring(bPauseNotUnpause)..'; iEngineerSubtableCount before increasing='..iEngineerSubtableCount..'; tEngineerActionsByPriority='..repru(tEngineerActionsByPriority)) end

                                if iCategoryRef == AiBotUnitInfo.refCategoryEngineer then
                                    if bFirstEngiCategoryRefBrain then
                                        iEngineerSubtableCount = iEngineerSubtableCount + 1
                                        bFirstEngiCategoryRefBrain = false
                                    end
                                    tEngineerActionSubtable = tEngineerActionsByPriority[iEngineerSubtableCount]
                                end

                                for iUnit = iTotalUnits, 1, -1 do
                                    oUnit = tRelevantUnits[iUnit]

                                    --for iUnit, oUnit in tRelevantUnits do
                                    bApplyActionToUnit = false
                                    iCurUnitEnergyUsage = 0
                                    if bUnpauseThisUnit then bUnpauseThisUnit = false end
                                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then  --Only consider unit if it has been constructed
                                        if not(bPauseNotUnpause) then
                                            bApplyActionToUnit = true
                                            if (oUnit.GetTacticalSiloAmmoCount or oUnit.GetTacticalSiloAmmoCount) then
                                                if AiBotUnitInfo.GetMissileCount(oUnit) >= 2 then
                                                    --Dont unpause TML, SML and SMD that have 2+ missiles loaded already
                                                    bApplyActionToUnit = false
                                                end
                                            elseif bConsideringHQ or (bDontPauseUpgradingT1LandOrT2Land and EntityCategoryContains(categories.TECH1 * AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId)) then
                                                --Only unpause HQs
                                                bApplyActionToUnit = false
                                                if (oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('BeingUpgraded')) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false then
                                                    for iFactory, oFactory in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs] do
                                                        if oUnit == oFactory then
                                                            bApplyActionToUnit = true
                                                            break
                                                        end
                                                    end
                                                end
                                            end
                                        else
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': About to consider pausing/unpausingunit ' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit) .. '; will first check category specific logic for if we want to go ahead with pausing4; bConsideringFactory='..tostring(bConsideringFactory)..'; brain gross energy='..oBrain[refiGrossEnergyBaseIncome]..'; Primary fac='..tostring(oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] or false)..'; MaintenanceConsumptionPerSecondEnergy='..(oUnit:GetBlueprint().Economy.MaintenanceConsumptionPerSecondEnergy or 'nil'))
                                                if oUnit.GetWorkProgress then
                                                    local oUnitTarget = oUnit:GetFocusUnit()
                                                    if oUnitTarget then
                                                        LOG(sFunctionRef..': EWork progress='..oUnit:GetWorkProgress()..'; oUnitTarget='..(oUnitTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitTarget) or 'nil')..'; Av E%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; defending vs t3 arti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]))
                                                    else
                                                        LOG(sFunctionRef..': EWork progress (no valid target)='..oUnit:GetWorkProgress())
                                                    end
                                                end
                                            end


                                            --Do we actually want to pause the unit? check any category specific logic
                                            bApplyActionToUnit = true
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': UnitState=' .. AiBotUnitInfo.GetUnitState(oUnit) .. '; Is ActiveHQUpgrades Empty=' .. tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs])))
                                            end
                                            --SMD LOGIC - Check if already have 1 missile loaded before pausing (unless enemy has no nukes)
                                            if iCategoryRef == AiBotUnitInfo.refCategorySMD and oUnit.GetTacticalSiloAmmoCount and oUnit:GetTacticalSiloAmmoCount() == 0 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false then
                                                if bDebugMessages == true then
                                                    LOG(sFunctionRef .. ': Have SMD with at least 1 missile so will pause it')
                                                end
                                                bApplyActionToUnit = false
                                            elseif iCategoryRef == AiBotUnitInfo.refCategoryEngineer then
                                                if bDebugMessages == true then
                                                    LOG(sFunctionRef .. ': Have an engineer with action=' .. (oUnit[AiBotEngineer.refiAssignedAction] or 'nil') .. '; tEngineerActionSubtable=' .. repru(tEngineerActionSubtable)..'; Brain gross energy income='..oBrain[refiGrossEnergyBaseIncome])
                                                end
                                                bApplyActionToUnit = false

                                                for iActionCount, iActionRef in tEngineerActionSubtable do
                                                    if iActionRef == oUnit[AiBotEngineer.refiAssignedAction] or iActionRef == iSpecialNonPowerEngiAction then
                                                        bApplyActionToUnit = true
                                                        --Dont pause the last engi building power
                                                        if bDebugMessages == true then LOG(sFunctionRef..': action match, checking for exceptions, unit work progress='..oUnit:GetWorkProgress()..'; focus unit='..(oUnit:GetFocusUnit().UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit:GetFocusUnit()) or 'nil')..'; order blueprint='..(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Assigned action='..(oUnit[AiBotEngineer.refiAssignedAction] or 'nil')..'; iActionRef='..iActionRef..'; Team gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
                                                        if oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildPower and
                                                                (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 or iActionRef == iSpecialNonPowerEngiAction --cond 1b
                                                                        or (oUnit[AiBotEngineer.refbPrimaryBuilder] --cond 1c
                                                                        or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 20 and oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] and EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH1, oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint])))) --cond 1d
                                                        then
                                                            bApplyActionToUnit = false
                                                            if oUnit.GetFocusUnit and oUnit:GetFocusUnit().UnitId and (oUnit:GetWorkProgress() > 0.4 or oUnit:GetFocusUnit():GetFractionComplete() > 0.4) and EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH1, oUnit:GetFocusUnit().UnitId) and (oUnit[AiBotUnitInfo.refbPaused] or (oUnit.IsPaused and oUnit:IsPaused())) then bUnpauseThisUnit = true end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': cancelling applying as building power withsome E stored, bUnpauseThisUnit='..tostring(bUnpauseThisUnit)) end
                                                            --Dont pause T1 factory construction if we have a certain amount of gross energy income
                                                        elseif iActionRef == AiBotEngineer.refActionBuildLandFactory and EntityCategoryContains(categories.TECH1, oUnit.UnitId) and oBrain[refiGrossEnergyBaseIncome] >= 26 then
                                                            if oUnit[AiBotEngineer.refbPrimaryBuilder] then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': wont pause primary engineer building t1 land fac') end
                                                                bApplyActionToUnit = false
                                                            else
                                                                local tEngiZone, tEngiTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                                                if not(tEngiTeamData[AiBotMap.subrefLZbCoreBase]) then
                                                                    --Keep building expansion land fac
                                                                    bApplyActionToUnit = false
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': expansion land fac exception') end
                                                                end
                                                            end
                                                        elseif iActionRef == iSpecialNonPowerEngiAction and (oUnit:GetWorkProgress() >= 0.99 or ((oUnit:GetFocusUnit().UnitId and (EntityCategoryContains(AiBotUnitInfo.refCategoryPower, oUnit:GetFocusUnit().UnitId)) and (oUnit:GetWorkProgress() > 0.4 or EntityCategoryContains(categories.TECH1, oUnit.UnitId))))) then
                                                            bApplyActionToUnit = false
                                                            if oUnit:GetFocusUnit().UnitId and (oUnit:GetWorkProgress() > 0.4 or oUnit:GetFocusUnit():GetFractionComplete() > 0.4) and EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH1, oUnit:GetFocusUnit().UnitId) and (oUnit[AiBotUnitInfo.refbPaused] or (oUnit.IsPaused and oUnit:IsPaused())) then bUnpauseThisUnit = true end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Building or repairing power during a pause non power stall exception, work progress='..oUnit:GetWorkProgress()..'; Focus unit ID='..(oUnit:GetFocusUnit().UnitId or 'nil')..'; refbPaused='..tostring(oUnit[AiBotUnitInfo.refbPaused] or false)..'; IsPaused='..tostring(oUnit:IsPaused())..'; bUnpauseThisUnit='..tostring(bUnpauseThisUnit)) end
                                                        elseif iActionRef == AiBotEngineer.refActionManageGameEnderTemplate and oUnit[AiBotEngineer.refbPrimaryBuilder] then
                                                            bApplyActionToUnit = false
                                                            if bDebugMessages == true then LOG(sFunctionRef..': primary GE Template exception') end
                                                        elseif oUnit:GetWorkProgress() >= 0.9 and oUnit:GetFocusUnit().UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryPower, oUnit:GetFocusUnit().UnitId) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.1 or oUnit:GetWorkProgress() >= 0.98) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.5 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])) then
                                                            bApplyActionToUnit = false
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Almost completed an experimental unit so dont want to stop now unless really stalling E') end
                                                        elseif oUnit.GetFocusUnit and oUnit:GetFocusUnit().UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH1, oUnit:GetFocusUnit().UnitId) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 15 then
                                                            bApplyActionToUnit = false
                                                            if bDebugMessages == true then LOG(sFunctionRef..': T1 builder exception') end
                                                        end
                                                        break
                                                    end
                                                end
                                            elseif iCategoryRef == AiBotUnitInfo.refCategoryPersonalShield or iCategoryRef == AiBotUnitInfo.refCategoryFixedShield or iCategoryRef == AiBotUnitInfo.refCategoryMobileLandShield then
                                                --Dont disable shield if unit has enemies nearby
                                                if (oUnit[AiBotBuilding.reftArtiTemplateRefs] or (AiBotUnitInfo.IsUnitShieldEnabled(oUnit) and AiBotUtilities.IsTableEmpty(oBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryDangerousToLand, oUnit:GetPosition(), 40, 'Enemy')) == false)) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Shield has enemies nearby so wont pause it') end
                                                    bApplyActionToUnit = false
                                                end
                                            elseif bConsideringFactory then
                                                --Primary factions - if dealing with T1 (or T2 with lots of E) and is a primary factory, then dont pause, as too big a risk we pause an expansion and lose the whole expansion
                                                if (oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] or (EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) and (oBrain[refiGrossEnergyBaseIncome] >= 300 or (oBrain[refiGrossEnergyBaseIncome] >= 150 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.TECH3, oUnit.UnitId)) or (oBrain[refiGrossEnergyBaseIncome] >= 100 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory * categories.TECH1, oUnit.UnitId))))) and (oBrain[refiGrossEnergyBaseIncome] >= 30 or oBrain[refiGrossEnergyBaseIncome] * oBrain[refiBrainBuildRateMultiplier] >= 30) and (oBrain[refiGrossEnergyBaseIncome] >= 150 or (oBrain[refiGrossEnergyBaseIncome] >= 80 * oBrain[refiBrainBuildRateMultiplier] and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.TECH3 + AiBotUnitInfo.refCategoryNavalFactory * categories.TECH1, oUnit.UnitId)) or EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory * categories.TECH1, oUnit.UnitId)) and (oBrain[refiGrossEnergyBaseIncome] >= 300 or not(oUnit:IsUnitState('Upgrading')) or bDontPauseUpgradingT1LandOrT2Land or (oUnit[AiBotFactory.refbPrimaryFactoryForIslandOrPond] and oBrain[refiGrossEnergyBaseIncome] >= 85 * oBrain[refiBrainBuildRateMultiplier] and EntityCategoryContains(categories.TECH1, oUnit.UnitId)))
                                                 then
                                                    bApplyActionToUnit = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Primary fac for island/pond or just a land fac when we have enough gross energy to support land so wont pause') end
                                                    --Dont want to pause an HQ upgrade since it will give us better power, unless we already have access to that tech for the factory brain owner
                                                elseif (bDontPauseUpgradingT1LandOrT2Land and EntityCategoryContains(categories.TECH1 * AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId)) or (not (bConsideringHQ) and (oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('BeingUpgraded')) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs]) == false and EntityCategoryContains(categories.FACTORY, oUnit.UnitId) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnit.UnitId)) or oUnit:GetAIBrain()[refiOurHighestFactoryTechLevel] <= AiBotUnitInfo.GetUnitTechLevel(oUnit))) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dont want to pause primary factory for island/pond') end
                                                    for iFactory, oFactory in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingHQs] do
                                                        if oUnit == oFactory then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with an upgrading factory, bConsideringHQ='..tostring(bConsideringHQ)..'; wont pause this factorys upgrade as it would give us a higher tech that could give us more power') end
                                                            bApplyActionToUnit = false
                                                            break
                                                        end
                                                    end
                                                end
                                                if bApplyActionToUnit then
                                                    if oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]) and (oUnit[AiBotOrders.refiOrderCount] or 0) <= 1 then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit last order was to build an engineer so dont want to pause it as more engieneers might help us recover from a power stall by building more power') end
                                                        bApplyActionToUnit = false
                                                    elseif bStopPausingIfGotToFactoriesAndHaveSomeEnergy and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) and not(oUnit:IsUnitState('Upgrading')) and not(oUnit:IsUnitState('BeingUpgraded')) then
                                                        bApplyActionToUnit = false
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to pause unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Cur blueprint building='..(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; bConsideringHQ='..tostring(bConsideringHQ)..'; bApplyActionToUnit='..tostring(bApplyActionToUnit)..'; Time='..GetGameTimeSeconds()) end

                                                if bApplyActionToUnit then
                                                    --Dont pause factory that is building an engineer or is an air factory that isnt building an air unit, if its our highest tech level and we dont have at least 5 engis of that tech level
                                                    if AiBotUnitInfo.GetUnitTechLevel(oUnit) >= math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) and oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer * AiBotUnitInfo.ConvertTechLevelToCategory(AiBotUnitInfo.GetUnitTechLevel(oUnit))) < 2
                                                            and (oUnit:GetWorkProgress() >= 0.9 or (oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]))) then
                                                        --Dont pause factory as have too few engis and want to build power with those engis
                                                        if bDebugMessages == true then LOG(sFunctionRef .. ': Have too few engineers and are building more so wont pause factory') end
                                                        bApplyActionToUnit = false
                                                    end
                                                end
                                            elseif iCategoryRef == AiBotUnitInfo.refCategoryTML and AiBotUnitInfo.GetMissileCount(oUnit) == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 30 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Dealing with TML that has no missile so dont want to pause it') end
                                                bApplyActionToUnit = false
                                                --Dont pause mexes that arent upgrading (due to issue where sending a pause order causes energy cost to be set to 0)
                                            elseif (iCategoryRef == AiBotUnitInfo.refCategoryT2Mex or iCategoryRef == AiBotUnitInfo.refCategoryT1Mex) then
                                                --dont pause if the unit isnt upgrading
                                                if not(oUnit.UnitBeingBuilt) and (not(oUnit.GetWorkprogress) or (oUnit:GetWorkProgress() or 0) == 0) and not(oUnit:IsUnitState('Upgrading')) then
                                                    bApplyActionToUnit = false
                                                end
                                                --Selens - dont pause as only costs 1 E per sec
                                            elseif oUnit.UnitId == 'xsl0101' and (oUnit:GetBlueprint().Economy.MaintenanceConsumptionPerSecondEnergy or 1) <= 2 and oBrain[refiGrossEnergyBaseIncome] >= 20 then
                                                bApplyActionToUnit = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have a selen so E drain is negligible') end
                                            end

                                            if iCategoryRef == categories.COMMAND then
                                                --want in addition to above as ACU might have personal shield

                                                if not (oUnit:IsUnitState('Upgrading')) and not(oUnit:IsUnitState('BeingUpgraded')) then
                                                    bApplyActionToUnit = false
                                                elseif oUnit.GetWorkProgress then
                                                    if oUnit:GetWorkProgress() >= 0.85 then
                                                        bApplyActionToUnit = false
                                                        --dont pause t1 mex construction
                                                    elseif oUnit.GetFocusUnit and oUnit:GetFocusUnit() and oUnit:GetFocusUnit().UnitId and EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oUnit:GetFocusUnit().UnitId) then
                                                        bApplyActionToUnit = false
                                                    end
                                                end
                                            end
                                        end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': Unit entry='..iUnit..'; Unit isnt valid or constructed')
                                    end



                                    --Pause the unit
                                    if bDebugMessages == true then LOG(sFunctionRef..': bApplyActionToUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..tostring(bApplyActionToUnit)) end

                                    if bApplyActionToUnit then
                                        bWasUnitAlreadyPaused = oUnit[AiBotUnitInfo.refbPaused] --Means we will ignore the energy usage when calculating how much we have saved
                                        oBP = oUnit:GetBlueprint()
                                        iCurUnitEnergyUsage = oBP.Economy.MaintenanceConsumptionPerSecondEnergy

                                        if (iCurUnitEnergyUsage or 0) == 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryMex + categories.COMMAND, oUnit.UnitId) then
                                            --Approximate energy usage based on build rate as a very rough guide
                                            --examples: Upgrading mex to T3 costs 11E per BP; T3 power is 8.4; T1 power is 6; Guncom is 30; Laser is 178; Strat bomber is 15
                                            local iEnergyPerBP = 9
                                            if EntityCategoryContains(categories.SILO, oUnit.UnitId) and oBP.Economy.BuildRate then
                                                --Dealing with a silo so need to calculate energy usage differently
                                                iCurUnitEnergyUsage = 0
                                                if oBP.Weapon and type(oBP.Weapon) == "table" then
                                                    for iWeapon, tWeapon in oBP.Weapon do
                                                        if tWeapon.MaxProjectileStorage and tWeapon.ProjectileId then
                                                            local oProjectileBP = __blueprints[tWeapon.ProjectileId]
                                                            if oProjectileBP.Economy and oProjectileBP.Economy.BuildCostEnergy and oProjectileBP.Economy.BuildTime > 0 and oBP.Economy.BuildRate > 0 then
                                                                --(will multiply cost by 10% in later step)
                                                                iCurUnitEnergyUsage = oProjectileBP.Economy.BuildCostEnergy * oBP.Economy.BuildRate * iBuildRateMod / oProjectileBP.Economy.BuildTime
                                                                --If are power stalling then assume we only save 80% of this, as might have adjacency
                                                                if bPauseNotUnpause then iCurUnitEnergyUsage = iCurUnitEnergyUsage * 0.8 end
                                                                break
                                                            end
                                                        end
                                                    end
                                                else
                                                    AiBotUtilities.ErrorHandler('Have silo without weapon')
                                                end
                                            else
                                                if iCategoryRef == categories.COMMAND and oUnit[AiBotOrders.refiOrderCount] > 0 and oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderEnhancement then
                                                    --Determine energy cost per BP
                                                    local sUpgradeRef = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint]
                                                    iEnergyPerBP = AiBotUnitInfo.GetUpgradeEnergyCost(oUnit, sUpgradeRef) / (AiBotUnitInfo.GetUpgradeBuildTime(oUnit, sUpgradeRef) or 1)
                                                    oUnit[refiLastEnergyUsage] = iCurUnitEnergyUsage
                                                else
                                                    --Engineer - adjust energy consumption based on what are building
                                                    iEnergyPerBP = 3
                                                end

                                                if oBP.Economy.BuildRate then
                                                    --iCurUnitEnergyUsage = oBP.Economy.BuildRate * iEnergyPerBP
                                                    --Reduce this massively if unit isn't actually building anything
                                                    if bPauseNotUnpause then
                                                        if (not(oUnit:IsUnitState('Building')) and not(oUnit:IsUnitState('Repairing')) and not(oUnit.GetWorkProgress and oUnit:GetWorkProgress() > 0)) then
                                                            iCurUnitEnergyUsage = oBP.Economy.BuildRate * iBuildRateMod * 0.01
                                                        else
                                                            if AiBotUnitInfo.IsUnitValid(oUnit:GetFocusUnit()) then
                                                                oFocusUnitBP = oUnit:GetFocusUnit():GetBlueprint()
                                                                iCurUnitEnergyUsage = oBP.Economy.BuildRate * iBuildRateMod / oFocusUnitBP.Economy.BuildTime * oFocusUnitBP.Economy.BuildCostEnergy
                                                                oUnit[refiLastEnergyUsage] = iCurUnitEnergyUsage
                                                            else
                                                                iCurUnitEnergyUsage = oBP.Economy.BuildRate * iBuildRateMod * iEnergyPerBP
                                                            end
                                                        end
                                                    else
                                                        iCurUnitEnergyUsage = (oUnit[refiLastEnergyUsage] or oBP.Economy.BuildRate * iBuildRateMod * iEnergyPerBP)
                                                    end
                                                end
                                            end
                                        end
                                        --We're working in ticks so adjust energy usage accordingly
                                        iCurUnitEnergyUsage = iCurUnitEnergyUsage * 0.1
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef .. ': Estimated energy usage before factoring in unit state=' .. iCurUnitEnergyUsage..'; About to call the function PauseOrUnpauseEnergyUsage on unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; iUnitsAdjusted where expected to save energy='..iUnitsAdjusted)
                                        end

                                        if not((iCurUnitEnergyUsage or 0) == 0) then
                                            iUnitsAdjusted = iUnitsAdjusted + 1
                                            if bPauseNotUnpause and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                                                if not(oUnit:IsUnitState('Upgrading') or oUnit:IsUnitState('Repairing') or oUnit:IsUnitState('Building') or oUnit:IsUnitState('BeingUpgraded')) then
                                                    iCurUnitEnergyUsage = iCurUnitEnergyUsage * 0.01
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..' so will set the amount of energy saved equal to just 1% of the actual value, so it is now '..iCurUnitEnergyUsage) end
                                                end
                                            end
                                        end
                                        AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, bPauseNotUnpause, nil, iTeam, iCategoryCount)
                                        --Cant move the below into unitinfo as get a crash if unitinfo tries to refernce the table of paused units
                                        --Managed to avoid the crash by making a localised import of AiBotEconomy into the pauseorunpause function; want it in unitinfo as then aibotorders can call the same function when clearing an engineer's orders


                                        --[[if bPauseNotUnpause then
                                            table.insert(oBrain[reftPausedUnits], oUnit)
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': Added unit to tracker table, size=' .. table.getn(oBrain[reftPausedUnits]))
                                            end
                                        else
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': Will remove unit from reftPausedUnits. Size of table before removal=' .. table.getn(oBrain[reftPausedUnits]))
                                            end
                                            for iPausedUnit, oPausedUnit in oBrain[reftPausedUnits] do
                                                if oPausedUnit == oUnit then
                                                    table.remove(oBrain[reftPausedUnits], iPausedUnit)
                                                end
                                            end
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef .. ': Size of table after removal =' .. table.getn(oBrain[reftPausedUnits]))
                                            end
                                        end--]]


                                        if not (bWasUnitAlreadyPaused) and bPauseNotUnpause then
                                            iEnergySavingManaged = iEnergySavingManaged + iCurUnitEnergyUsage
                                        elseif bWasUnitAlreadyPaused and not (bPauseNotUnpause) then
                                            iEnergySavingManaged = iEnergySavingManaged - iCurUnitEnergyUsage
                                        end
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef .. ': iEnergySavingManaged=' .. iEnergySavingManaged .. '; iEnergyPerTickSavingNeeded=' .. iEnergyPerTickSavingNeeded .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; bWasUnitAlreadyPaused='..tostring(bWasUnitAlreadyPaused)..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)..'; iCurUnitEnergyUsage='..iCurUnitEnergyUsage)
                                        end

                                        if bPauseNotUnpause then
                                            if iEnergySavingManaged > iEnergyPerTickSavingNeeded then
                                                if bDebugMessages == true then
                                                    LOG(sFunctionRef .. ': Estimate we have saved ' .. iEnergySavingManaged .. ' which is more tahn we wanted so will pause')
                                                end
                                                bAbort = true
                                                break
                                            end
                                        else
                                            if iEnergySavingManaged < iEnergyPerTickSavingNeeded then
                                                bAbort = true
                                                break
                                            end
                                        end
                                    elseif bUnpauseThisUnit and oUnit[AiBotUnitInfo.refbPaused] then
                                        AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false, nil, iTeam, iCategoryCount)
                                    end


                                end
                            elseif bDebugMessages == true then
                                LOG(sFunctionRef .. ': We have no units for iCategoryCount=' .. iCategoryCount)
                            end



                            if bAbort then
                                break
                            end
                            if bConsideringTeamWideUnits then break end --dont want to consider for more than one brain
                        end
                        if bAbort then
                            break
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef .. 'If we have no paused units then will set us as not having an energy stall; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]..'; subrefbTeamIsStallingMass ='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; bPauseNotUnpause='..tostring(bPauseNotUnpause)) end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] <= 0 then
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] = false
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] = 0
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables] = nil
                        if bDebugMessages == true then LOG(sFunctionRef .. ': We are no longer stalling energy, we had a paused unit count of <= 0') end
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] and not(bPauseNotUnpause) and not(bHaveWeCappedUnpauseAmount) then
                        --Unpause all units' energy usage only (i.e. production remains paused, but radar and shields should be unpaused
                        for iCategory, tUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                            if tUnits then
                                for iUnit, oUnit in tUnits do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will pause just the energy usage parts of unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                        AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false, true, iTeam)
                                    end
                                end
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Are stalling mass so have finished unpausing energy usage of units at time='..GetGameTimeSeconds()) end
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] = false
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastEnergyStallCategoryAndEngineerTables] = nil
                    else
                        if bDebugMessages == true then LOG(sFunctionRef .. ': About to check if we wanted to unpause units but havent unpaused anything; iUnitsAdjusted=' .. iUnitsAdjusted .. '; bNoRelevantUnits=' .. tostring(bNoRelevantUnits) .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
                        --Backup - sometimes we still have units in the table listed as being paused (e.g. if an engineer changes action to one that isnt listed as needing pausing) - unpause them if we couldnt find via category search
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and not (bPauseNotUnpause) and (iEnergySavingManaged > iEnergyPerTickSavingNeeded or iUnitsAdjusted == 0 or bNoRelevantUnits) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.95 then
                            --Have a decent amount of power, are flagged as stalling energy, but couldnt find any categories to unpause
                            if bDebugMessages == true then LOG(sFunctionRef .. ': werent able to find any units to unpause with normal approach so will unpause all remaining units for all AiBot brains in the team') end
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority]) == false then
                                for iCategory, tUnits in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoPausedUnitsByPriority] do
                                    if tUnits then
                                        local iUnitCount = table.getn(tUnits)
                                        if iUnitCount > 0 then
                                            for iCurUnit = iUnitCount, 1, -1 do
                                                if AiBotUnitInfo.IsUnitValid(tUnits[iCurUnit]) then
                                                    AiBotUnitInfo.PauseOrUnpauseEnergyUsage(tUnits[iCurUnit], false, iTeam)
                                                end
                                            end
                                        end
                                    end
                                    tUnits = nil
                                end
                            end
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] = false
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount] = 0
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastMassStallCategoryAndEngineerTables] = nil


                            if bDebugMessages == true then LOG(sFunctionRef .. ': FInished unpausing units and resetting the flag re paused units') end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef .. ': End of code, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]=' .. tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) .. '; bPauseNotUnpause=' .. tostring(bPauseNotUnpause) .. '; iUnitsAdjusted=' .. iUnitsAdjusted .. '; Game time=' .. GetGameTimeSeconds() .. '; Energy stored %=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] .. '; Net energy income=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] .. '; gross energy income=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] = GetGameTimeSeconds()
                end
            end

            if bDebugMessages == true then
                LOG(sFunctionRef..': Will now call manage mass stalls if not stalling energy. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; bChangeRequired='..tostring(bChangeRequired)..'; is team stalling mass (pre mass stall check)='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPausedUnitCount])
            end
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and not(bChangeRequired) then
                ForkThread(ManageMassStalls, iTeam)
            end
        end
    else
        AiBotUtilities.ErrorHandler('No active AiBot brains')
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function GetEnergyStorageMaximum(aiBrain, bDetailedUpdate)
    --bDetailedUpdate - called periodically (but not by the every tick team resource sharer)
    if aiBrain:GetEconomyStoredRatio('ENERGY') > 0 then
        aiBrain[refiMaxEnergyStorage] = aiBrain:GetEconomyStored('ENERGY') / aiBrain:GetEconomyStoredRatio('ENERGY')
        return aiBrain[refiMaxEnergyStorage]
    else
        if bDetailedUpdate then
            aiBrain[refiMaxEnergyStorage] = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEnergyStorage) * AiBotBuilding.iEnergyStorageExpectedCapacity + aiBrain:GetCurrentUnits(categories.COMMAND) * 3900 + 100 + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryQuantumOptics) * 10000
        end
        return aiBrain[refiMaxEnergyStorage]
    end
end

function GetMassStorageMaximum(aiBrain, bDetailedUpdate)
    if aiBrain:GetEconomyStoredRatio('MASS') > 0 then
        aiBrain[refiMaxMassStorage] = aiBrain:GetEconomyStored('MASS') / aiBrain:GetEconomyStoredRatio('MASS')
        return aiBrain[refiMaxMassStorage]
    else
        if bDetailedUpdate then
            aiBrain[refiMaxMassStorage] = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMassStorage) * 500 + aiBrain:GetCurrentUnits(categories.COMMAND) * 650 + 150
        end
        return aiBrain[refiMaxMassStorage]
    end
end


function GiveResourcesToPlayer(oBrainGiver, oBrainReceiver, iMass, iEnergy)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GiveResourcesToPlayer'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Check we have the resources to give:
    if iMass > 0 and oBrainGiver:GetEconomyStored('MASS') >= iMass then
        --Check the person receiving has enough capacity
        if GetMassStorageMaximum(oBrainReceiver) - oBrainReceiver:GetEconomyStored('MASS') >= iMass then
            oBrainReceiver:GiveResource('Mass', iMass)
            oBrainGiver:TakeResource('Mass', iMass)
            if bDebugMessages == true then LOG(sFunctionRef..': Given '..iMass..' Mass from '..oBrainGiver.Nickname..' to '..oBrainReceiver.Nickname) end

        end
    end
    if iEnergy > 0 and oBrainGiver:GetEconomyStored('ENERGY') >= iEnergy then
        if GetEnergyStorageMaximum(oBrainReceiver) - oBrainReceiver:GetEconomyStored('ENERGY') >= iEnergy then
            oBrainReceiver:GiveResource('Energy', iEnergy)
            oBrainGiver:TakeResource('Energy', iEnergy)
            if bDebugMessages == true then LOG(sFunctionRef..': Given '..iEnergy..' Energy from '..oBrainGiver.Nickname..' to '..oBrainReceiver.Nickname) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function ShareResourcesMassAndEnergyBetweenTeam() AiBotUtilities.ErrorHandler('Using superceded code')  end --Done to make the below easier to find
function AllocateTeamEnergyAndMassResources(iTeam)
    --Smoothes out energy storage for AiBot brains on the same team, where % storage is <95%

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AllocateTeamEnergyResources'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iTeam='..iTeam..'; Is table of active brains empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))) end

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then

        local refiResourceEnergy = 1
        local refiResourceMass = 2
        local tDetailsOfBrainsNeedingEnergy = {}
        local tDetailsOfBrainsWithEnergy = {}
        local tDetailsOfBrainsNeedingMass = {}
        local tDetailsOfBrainsWithMass = {}

        local subrefoBrain = 1
        local subrefiRemainingResourceNeeded = 2
        local subrefiResourceToGive = 3

        local iTotalEnergyStored = 0
        local iTotalMassStored = 0
        local bMobaOrNoCombinedArmies = AiBotOrders.bDontConsiderCombinedArmy or tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 3 --if in MOBA mode then want to have human players share resources

        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if bMobaOrNoCombinedArmies or oBrain.BrainType == 'AI' then
                iTotalEnergyStored = iTotalEnergyStored + oBrain:GetEconomyStored('ENERGY')
                iTotalMassStored = iTotalMassStored + oBrain:GetEconomyStored('MASS')
            end
        end
        local iAverageEnergyStored = iTotalEnergyStored / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
        local iAverageMassStored = iTotalMassStored / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
        local iCurEnergySpare, iCurMassSpare

        if bDebugMessages == true then LOG(sFunctionRef..': Near start, time='..GetGameTimeSeconds()..'; iAverageEnergyStored='..iAverageEnergyStored..'; iAverageMassStored='..iAverageMassStored) end

        --Sort brains into those that have mass, and those that give mass
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if bMobaOrNoCombinedArmies or oBrain.BrainType == 'AI' then
                iCurEnergySpare = oBrain:GetEconomyStored('ENERGY') - iAverageEnergyStored
                --Adjust spare energy if we have significantly different % to average
                if math.abs(oBrain:GetEconomyStoredRatio('ENERGY') - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]) >= 0.3 then
                    if iCurEnergySpare >= 0 and oBrain:GetEconomyStoredRatio('ENERGY') < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] then
                        iCurEnergySpare = -GetEnergyStorageMaximum(oBrain) * 0.1
                    elseif iCurEnergySpare <= 0 and oBrain:GetEconomyStoredRatio('ENERGY') > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] then
                        if oBrain:GetEconomyStored('ENERGY') >= AiBotBuilding.iEnergyStorageExpectedCapacity or oBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 then
                            iCurEnergySpare = 0
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurEnergySpare after limiting based on ratios='..iCurEnergySpare..'; Expected value before limitation='..(oBrain:GetEconomyStored('ENERGY') - iAverageEnergyStored)) end
                end

                if iCurEnergySpare < 0 then
                    --Limit Energy to receive to the amount that takes us to 95% storage:
                    iCurEnergySpare = math.max(iCurEnergySpare, math.min(0, oBrain:GetEconomyStored('ENERGY') -  GetEnergyStorageMaximum(oBrain) * 0.95))
                    if iCurEnergySpare < 0 then
                        table.insert(tDetailsOfBrainsNeedingEnergy, {[subrefoBrain] = oBrain, [subrefiRemainingResourceNeeded] = iCurEnergySpare})
                    end
                elseif iCurEnergySpare > 0 then
                    table.insert(tDetailsOfBrainsWithEnergy, {[subrefoBrain] = oBrain, [subrefiResourceToGive] = iCurEnergySpare})
                end

                iCurMassSpare = oBrain:GetEconomyStored('MASS') - iAverageMassStored
                --Adjust spare mass if we have significantly different % to average
                if math.abs(oBrain:GetEconomyStoredRatio('MASS') - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]) >= 0.2 or (iCurMassSpare < 0 and oBrain:GetEconomyStoredRatio('MASS') >= 0.95) then
                    if iCurMassSpare >= 0 and oBrain:GetEconomyStoredRatio('MASS') < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] then
                        iCurMassSpare = -GetMassStorageMaximum(oBrain) * 0.05
                    elseif iCurMassSpare <= 0 and oBrain:GetEconomyStoredRatio('MASS') > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] then
                        if oBrain:GetEconomyStored('MASS') >= 700 or oBrain:GetEconomyStoredRatio('MASS') >= 0.9 then
                            iCurMassSpare = 0
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurMassSpare after limiting based on ratios='..iCurMassSpare..'; Expected value before limitation='..(oBrain:GetEconomyStored('MASS') - iAverageMassStored)) end
                end

                if iCurMassSpare < 0 then
                    --Limit mass to receive to the amount that takes us to 95% storage:
                    iCurMassSpare = math.max(iCurMassSpare, math.min(0, oBrain:GetEconomyStored('MASS') -  GetMassStorageMaximum(oBrain) * 0.95))
                    if iCurMassSpare < 0 then
                        table.insert(tDetailsOfBrainsNeedingMass, {[subrefoBrain] = oBrain, [subrefiRemainingResourceNeeded] = iCurMassSpare})
                    end
                elseif iCurMassSpare > 0 then
                    table.insert(tDetailsOfBrainsWithMass, {[subrefoBrain] = oBrain, [subrefiResourceToGive] = iCurMassSpare})
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..oBrain.Nickname..': iCurEnergySpare='..iCurEnergySpare..'; iCurMassSpare='..iCurMassSpare..'; Actual mass stored='..oBrain:GetEconomyStored('MASS')..'; Actual energy stored='..oBrain:GetEconomyStored('ENERGY')..'; iAverageMassStored='..iAverageMassStored) end
            end
        end

        --Allocate resources:
        local tBrainsNeedingResource, tBrainsWithResource
        local iResourceToGive
        for iResourceType = 1, 2, 1 do
            if iResourceType == refiResourceEnergy then
                tBrainsNeedingResource = tDetailsOfBrainsNeedingEnergy
                tBrainsWithResource = tDetailsOfBrainsWithEnergy
                if bDebugMessages == true then LOG(sFunctionRef..': Allcoating energy') end
            else
                tBrainsNeedingResource = tDetailsOfBrainsNeedingMass
                tBrainsWithResource = tDetailsOfBrainsWithMass
                if bDebugMessages == true then LOG(sFunctionRef..': Allcoating mass') end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of brains needing this resource empty='..tostring(AiBotUtilities.IsTableEmpty(tBrainsNeedingResource))..'; Is table of brains with this resource available empty='..tostring(AiBotUtilities.IsTableEmpty(tBrainsWithResource))) end
            if AiBotUtilities.IsTableEmpty(tBrainsNeedingResource) == false and AiBotUtilities.IsTableEmpty(tBrainsWithResource) == false then
                for iBrainWithResource, tBrainWithResourceSubtable in tBrainsWithResource do
                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding which brain '..tBrainWithResourceSubtable[subrefoBrain].Nickname..' should give its resources to') end
                    for iBrainNeedingResource, tBrainNeedingResourceSubtable in tBrainsNeedingResource do
                        iResourceToGive = math.min(-tBrainNeedingResourceSubtable[subrefiRemainingResourceNeeded], tBrainWithResourceSubtable[subrefiResourceToGive])
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to give resources to brain '..tBrainNeedingResourceSubtable[subrefoBrain].Nickname..'; iResourceToGive='..iResourceToGive..'; tBrainNeedingResourceSubtable[subrefiRemainingResourceNeeded]='..tBrainNeedingResourceSubtable[subrefiRemainingResourceNeeded]..'; tBrainWithResourceSubtable[subrefiResourceToGive]='..tBrainWithResourceSubtable[subrefiResourceToGive]) end
                        if iResourceToGive > 0 then
                            if iResourceType == refiResourceEnergy then
                                GiveResourcesToPlayer(tBrainWithResourceSubtable[subrefoBrain], tBrainNeedingResourceSubtable[subrefoBrain], 0, iResourceToGive)
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': About to give '..iResourceToGive..' mass from player '..tBrainWithResourceSubtable[subrefoBrain].Nickname..' to player '..tBrainNeedingResourceSubtable[subrefoBrain].Nickname) end
                                GiveResourcesToPlayer(tBrainWithResourceSubtable[subrefoBrain], tBrainNeedingResourceSubtable[subrefoBrain], iResourceToGive, 0)
                            end
                            tBrainNeedingResourceSubtable[subrefiRemainingResourceNeeded] = tBrainNeedingResourceSubtable[subrefiRemainingResourceNeeded] + iResourceToGive
                            tBrainWithResourceSubtable[subrefiResourceToGive] = tBrainWithResourceSubtable[subrefiResourceToGive] - iResourceToGive
                            if tBrainWithResourceSubtable[subrefiResourceToGive] <= 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Remaining resource available for brain '..tBrainWithResourceSubtable[subrefoBrain].Nickname..' to give='..tBrainWithResourceSubtable[subrefiResourceToGive]..' so will break') end
                                break
                            end
                        end
                    end
                end
            end
        end
    else
        AiBotUtilities.ErrorHandler('No active AiBot brains')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TeamResourceSharingMonitor(iTeam)
    --Monitors resources for AI in the team and shares resources
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TeamResourceSharingMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, checking if already running a monitor for iTeam='..iTeam..': Is table of friendl yAiBot brains for this team empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 'nil')) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
        local iDefaultTimeToStop = GetGameTimeSeconds() + 120
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(10)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        while GetGameTimeSeconds() < iDefaultTimeToStop do
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] > 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] > 0) then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to start sharing resources between teammates as have T2 or alot of mass') end
                break
            else
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end

        while AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd) --moved here since getting very high readings for how long this is taking
            ForkThread(AllocateTeamEnergyAndMassResources, iTeam)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateTableOfUpgradingMexesForTeam(iTeam)
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
        local tUpgradingMexes = AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]
        local iEntries = table.getn(tUpgradingMexes)

        for iCurEntry = iEntries, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(tUpgradingMexes[iCurEntry])) then
                table.remove(tUpgradingMexes, iCurEntry)
            end
        end
    end
end

function ManageMassOverflow(iTeam)
    --Stop any engineers that have a reclaim area order
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageMassOverflow'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastOverflowEngiCheck] or -100) >= 1 then --Only do this every couple of seconds
            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastOverflowEngiCheck] = GetGameTimeSeconds()
            local iEngiCycleCount = 0
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do

                local tEngineers = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer, false, true)
                if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                    for iUnit, oUnit in tEngineers do
                        iEngiCycleCount = iEngiCycleCount + 1
                        if AiBotUnitInfo.IsUnitValid(oUnit) and (oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionReclaimArea or oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionReclaimFriendlyUnit) then
                            if bDebugMessages == true then LOG(sFunctionRef..': About to stop engineer '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from reclaiming as have lots of mass now') end
                            AiBotOrders.IssueTrackedClearCommands(oUnit)
                        end
                        if iEngiCycleCount >= 30 then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitTicks(1)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastOverflowEngiCheck] = GetGameTimeSeconds()
                            iEngiCycleCount = 0
                        end
                    end
                end
            end
        end
    else
        AiBotUtilities.ErrorHandler('No AiBot brains active')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderFutureMexUpgrade(oMex, iOverrideSecondsToWait)
    --Called when we have just constructed a mex - considers upgrading the mex in the future if we have no active upgrades
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderFutureMexUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTimeToWait = iOverrideSecondsToWait
    local iMexTechLevel = AiBotUnitInfo.GetUnitTechLevel(oMex)
    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oMex:GetPosition())
    local aiBrain = oMex:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam
    local tLZOrWZData, tLZOrWZTeamData
    local iMexesOnMap = table.getn(AiBotMap.tMassPoints)



    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, iOverrideSecondsToWait='..(iOverrideSecondsToWait or 'nil')..'; oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..' owned by '..aiBrain.Nickname..'; P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; iMexTechLevel='..(iMexTechLevel or 'nil')..'; Time='..GetGameTimeSeconds()) end

    if not(iTimeToWait) then
        if iMexTechLevel == 1 then
            if bDebugMessages == true then LOG(sFunctionRef..': tLZOrWZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech])..'; tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]..'; Brain highest tech='..aiBrain[refiOurHighestFactoryTechLevel]..'; Gross mass inc='..aiBrain[refiGrossMassBaseIncome]..'; Dangerous enemies in LZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or false)..'; Air to ground threat='..(tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')..'; Enemies in adj zone='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; Is table of active mex upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]))..'; refbBaseInSafePosition='..tostring(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] or false)) end
            --Eco slot in FAF - consider upgrading first mex relatively early on if lots of mexes in start zone and have a resource multiplier
                --Have further eco slot condition a bit lower down that is slower than this for where we dont have lots of mexes
            if AiBotUnitInfo.GetUnitLifetimeCount(oMex) == 1 and (tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] or aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 6 and oMex:GetAIBrain()[refiBrainBuildRateMultiplier] <= 1.1 and AiBotUtilities.bFAFActive then
                if bDebugMessages == true then LOG(sFunctionRef..': First mex in eco slot so want to be more likely to get upgrade really early in FAF') end
                iTimeToWait = 150 - GetGameTimeSeconds()
                --Rebuilding zone with lots of mexes where have built on the last mex, and have good mass income generally
                --NOTE: A slight delay between registering how many mexes we have by tech in a zone, so this is likely to be outdated slightly, hence use a threshold of 2 mexes away from completion
            elseif tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 4 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 and (aiBrain[refiOurHighestFactoryTechLevel] >= 2 or aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and aiBrain[refiGrossMassBaseIncome] >= 5 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] >= tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] - 2 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(5, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] - 1) and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and GetGameTimeSeconds() >= 600 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]) then
                --Wait 1 sec to check updated mex count
                iTimeToWait = 5
                if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(6, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(2)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(6, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) then
                        if bDebugMessages == true then LOG(sFunctionRef..': still dont have all mexes built so increasing time to wait to 90s') end
                        iTimeToWait = 90
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': 4+ mex zone and we ahvae built on all mexes so will upgrade to t2, iTimeToWait='..iTimeToWait) end
            elseif (AiBotMap.iMapSize >= 1000 or aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                --if AiBotUtilities.bLoudModActive or AiBotMap.iMapSize > 1024 then iTimeToWait = 5 * 60

                if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                    if iMexesOnMap <= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then --e.g. average of 10 mexes per player assuming even teams, or 60 mexes in a 3v3
                        --assumed early aggression will be rewarded more as either lots of mexes to fight over; also with lots of mexes the e upkeep cost in LOUD becomes more of an issue (so dont want to upgrade quite as soon)
                        iTimeToWait = 2 * 60 --In LOUD players often start a mex upgrade around 3m30
                    else
                        iTimeToWait = 3.5 * 60
                    end
                else
                    if AiBotMap.iMapSize > 1000 then
                        iTimeToWait = 4.5 * 60
                    else
                        iTimeToWait = 5.5 * 60
                    end
                end
                --First 8m - delay slightly, both generally, and if dealing with mexes 2-4; also later on have an adjustment for just the first mex that overrides the below to be aware of
                if GetGameTimeSeconds() <= 480 then
                    local iCurDiscount = 420 - iTimeToWait
                    iTimeToWait = iTimeToWait + iCurDiscount * (480-GetGameTimeSeconds()) / 480

                    --Also adjust based on which mex it is, on the assumption mexes 2-4 may have been built v.soon after mex 1 - i.e. first mex will by default follow this
                    iTimeToWait = iTimeToWait - 30 + 120 * math.min(4, AiBotUnitInfo.GetUnitLifetimeCount(oMex)) / 4 --NOTE: Have override later on for just the first mex's timing
                end
            else
                if aiBrain[AiBotOverseer.refbPrioritiseHighTech] then iTimeToWait = 6.5 * 60
                else
                    iTimeToWait = 7 * 60
                end
            end
            if AiBotUnitInfo.GetUnitLifetimeCount(oMex) == 1 and (tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] or aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 3 then
                if bDebugMessages == true then LOG(sFunctionRef..': First mex in eco slot but dont have large number of mexes in this zone, will ensure time to wait is low, if not already lower, iTimeToWait pre adj='..iTimeToWait) end
                iTimeToWait = math.min(iTimeToWait, 250 - GetGameTimeSeconds())
            end
        elseif iMexTechLevel == 2 then
            if aiBrain[refiGrossMassBaseIncome] < 10 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or iMexesOnMap > 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                if aiBrain[AiBotOverseer.refbPrioritiseHighTech] then
                    iTimeToWait = 7 * 60 + 4 * 60 * (10-aiBrain[refiGrossMassBaseIncome]) / 10
                else
                    iTimeToWait = 8 * 60 + 4 * 60 * (10-aiBrain[refiGrossMassBaseIncome]) / 10
                end
            elseif aiBrain[refiGrossMassBaseIncome] < 5 and iMexesOnMap <= 60 and AiBotUnitInfo.GetUnitLifetimeCount(oMex) <= 3 then --Prioritise first few t3 mex upgrades
                iTimeToWait = 2 * 60 + 4 * 60 * (10-aiBrain[refiGrossMassBaseIncome]) / 10
            else
                if aiBrain[AiBotOverseer.refbPrioritiseHighTech] then
                    iTimeToWait = 7 * 60
                else
                    iTimeToWait = 8 * 60
                end
            end
            if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                if iMexesOnMap > 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                    iTimeToWait = iTimeToWait - 40
                else
                    iTimeToWait = iTimeToWait - 20
                end
            end
        elseif bT3MexCanBeUpgraded and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and iMexTechLevel == 3 then
            iTimeToWait = 0
        else --redundancy
            local tLZData = AiBotMap.GetLandOrWaterZoneData(oMex:GetPosition())
            local iMexesInZone = (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0)
            if aiBrain[refiGrossMassBaseIncome] < 25 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or iMexesOnMap > 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                iTimeToWait = 4 * 60 + 5 * 60 * (25-aiBrain[refiGrossMassBaseIncome]) / 10
            elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and aiBrain[refiGrossMassBaseIncome] < 12 and iMexesOnMap <= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                iTimeToWait = 2 * 60 + 2 * 60 * (25-aiBrain[refiGrossMassBaseIncome]) / 10
            else
                iTimeToWait = 4 * 60
            end
            if iMexesInZone < 4 and aiBrain[refiGrossMassBaseIncome] <= 40 and iMexesOnMap > 60 then
                iTimeToWait = iTimeToWait + 2 * 60 * (4 - (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0))
            elseif iMexesInZone < 4 and aiBrain[refiGrossMassBaseIncome] <= 20 and iMexesOnMap <= 60 then
                iTimeToWait = iTimeToWait + 1 * 60 * (4 - (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0))
            end
        end
        if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotUnitInfo.GetUnitLifetimeCount(oMex) == 1 and iMexTechLevel == 1 then
            if iMexesOnMap > 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                iTimeToWait = math.min(iTimeToWait, 180)
            else
                iTimeToWait = math.min(iTimeToWait, 60)
            end
        end
        --Adjust for brain personality
        if aiBrain[AiBotOverseer.refbPrioritiseLowTech] then iTimeToWait = iTimeToWait * 2
        elseif aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] then iTimeToWait = iTimeToWait * 0.9
        end
        -- Boom is an explicit player-controlled risk/reward choice.  On low-mex
        -- maps waiting for the normal combat-oriented timing leaves no route to
        -- scale, so consider mex upgrades substantially earlier.
        if AiBotOverseer.IsBoomMode(aiBrain) then iTimeToWait = iTimeToWait * 0.35 end

        -- Dual Gap mid has a concrete opening: four T2 mexes by roughly five
        -- minutes. The generic scheduler is intentionally conservative on a
        -- 1024 map and can spend the opening on a second T1 factory instead.
        -- Pull only the consideration time forward here; the normal safety,
        -- mass and active-upgrade checks below still decide whether the mex is
        -- actually upgraded.
        if aiBrain.AiBotDualGapMexUpgradeTargetCount and iMexTechLevel == 1 then
            local iMexOrder = math.min(aiBrain.AiBotDualGapMexUpgradeTargetCount, math.max(1, AiBotUnitInfo.GetUnitLifetimeCount(oMex)))
            local iTargetTime = (aiBrain.AiBotDualGapMexUpgradeStart or 180)
                    + (iMexOrder - 1) * (aiBrain.AiBotDualGapMexUpgradeSpacing or 20)
            iTimeToWait = math.min(iTimeToWait or iTargetTime, math.max(0, iTargetTime - GetGameTimeSeconds()))
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': About to wait before considering upgrading this mex again='..iTimeToWait..' for mex '..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..' owned by '..aiBrain.Nickname..' at time='..GetGameTimeSeconds()..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oMex))) end
    if iTimeToWait > 0 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(iTimeToWait)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is oMex '..(oMex.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oMex) or 'nil')..' still valid='..tostring(AiBotUnitInfo.IsUnitValid(oMex))..' at time='..GetGameTimeSeconds()) end
    if AiBotUnitInfo.IsUnitValid(oMex) then
        -- Dedicated DualGap air/eco build phase: after the first strat, turn
        -- the eight home T2 mexes into T3 continuously.  This intentionally
        -- bypasses the generic production/low-mass gates; a cap of three live
        -- upgrades keeps the push aggressive without recreating the old
        -- all-at-once upgrade stall.
        local iForcedGameTime = GetGameTimeSeconds()
        local bForcedDualGapT3Mex = (aiBrain.AiBotDualGapRole == 'top_air'
                or aiBrain.AiBotDualGapRole == 'bottom_air'
                or aiBrain.AiBotDualGapRole == 'eco')
                and iMexTechLevel == 2
                and iForcedGameTime <= 900
                and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryBomber * categories.TECH3) > 0
                and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3) < 8
                and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] or {}) < 1
        if bForcedDualGapT3Mex and AiBotConditions.SafeToUpgradeUnit(oMex) then
            LOG('AiBot Dual Gap FORCED T3 mex push: army='..aiBrain:GetArmyIndex()
                    ..'; role='..aiBrain.AiBotDualGapRole
                    ..'; t3 mexes='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3)
                    ..'; team active='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] or {})
                    ..'; time='..iForcedGameTime)
            UpgradeUnit(oMex, true)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Are we in t1 spam mode='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] or false)) end
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam]) then
            --Only do this if there are 3+ mexes in the zone, or it's a plateau
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether we want to upgrade mex '..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..'; safe to upgrade='..tostring(AiBotConditions.SafeToUpgradeUnit(oMex))..'; iMexTechLevel='..iMexTechLevel..'; Team has low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; Time='..GetGameTimeSeconds()) end
            if AiBotConditions.SafeToUpgradeUnit(oMex) and not(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refbPrioritiseProduction]) then
                -- The dedicated DualGap air opening needs four completed T2
                -- mexes around minute five. Use the normal tracked upgrade path,
                -- but let the first four start as soon as the hydro is complete.
                -- Keeping the zone cap at two avoids the unsafe mass-upgrade
                -- fan-out that previously stalled the simulation.
                local iGameTime = GetGameTimeSeconds()
                local bDualGapAirEcoRole = aiBrain.AiBotDualGapRole == 'top_air'
                        or aiBrain.AiBotDualGapRole == 'bottom_air'
                        or aiBrain.AiBotDualGapRole == 'eco'
                local bDualGapEarlyAirMex = bDualGapAirEcoRole
                        and iMexTechLevel == 1
                        and iGameTime >= (aiBrain.AiBotDualGapMexUpgradeStart or 130)
                        and iGameTime <= 300
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryHydro) > 0
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH2) < 4
                        and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) < 4
                        and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])
                if bDualGapEarlyAirMex then
                    LOG('AiBot Dual Gap early air mex upgrade: army='..aiBrain:GetArmyIndex()
                            ..'; t2 mexes='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH2)
                            ..'; active='..(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)
                            ..'; time='..iGameTime)
                    UpgradeUnit(oMex, true)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return
                end
                local bDualGapPostStratT3Mex = bDualGapAirEcoRole
                        and iMexTechLevel == 2
                        and iGameTime <= 900
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH3) > 0
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryBomber * categories.TECH3) > 0
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3) < 8
                        and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) < 2
                        and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])
                if bDualGapPostStratT3Mex then
                    LOG('AiBot Dual Gap post-strat T3 mex upgrade: army='..aiBrain:GetArmyIndex()
                            ..'; role='..aiBrain.AiBotDualGapRole
                            ..'; t3 mexes='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3)
                            ..'; active='..(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)
                            ..'; time='..iGameTime)
                    UpgradeUnit(oMex, true)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return
                end
                local bUpgradeDueToHowLongHadMex = false
                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) == 0 then
                    local iTimeThreshold
                    if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then iTimeThreshold = 600
                    else
                        if AiBotMap.iMapSize <= 512 then
                            if AiBotMap.iMapSize <= 256 then
                                iTimeThreshold = 1200
                            else
                                iTimeThreshold = 1080
                            end
                        else iTimeThreshold = 900
                        end
                    end
                    if AiBotOverseer.IsBoomMode(aiBrain) then iTimeThreshold = iTimeThreshold * 0.35 end
                    if iMexTechLevel == 2 then iTimeThreshold = iTimeThreshold * 1.5 end
                    if not(aiBrain[refiBrainResourceMultiplier] == 1) then
                        iTimeThreshold = iTimeThreshold * (1 + (aiBrain[refiBrainResourceMultiplier] - 1) * 0.5)
                    end
                    local iTeamUpgradingMexCount = 0
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
                        iTeamUpgradingMexCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])
                        iTimeThreshold = 60 * iTeamUpgradingMexCount
                    end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iTimeThreshold = iTimeThreshold + 120 + 60 * iTeamUpgradingMexCount end
                    if iPlateauOrZero == 0 then iTimeThreshold = iTimeThreshold + 90 end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= iMexTechLevel then iTimeThreshold = iTimeThreshold + 300 end
                    --Increase time threshold if we dont have many mexes of the current level
                    local iMexesOfHigherTech = 0
                    local iUpgradingMexCount = 0
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
                        iUpgradingMexCount = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])
                    end
                    if iMexTechLevel == 1 then
                        iMexesOfHigherTech = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiUpgradedMexCount] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
                    else
                        iMexesOfHigherTech = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex - categories.TECH1 - categories.TECH2)
                    end
                    if iMexesOfHigherTech <= 3 * (1 + iUpgradingMexCount) then  --e.g. want 3 t2 mex for every 1 t1 mex that are upgrading, so significantly increase the time to wait by up to 3 times
                        iTimeThreshold = iTimeThreshold * (3 - 2 * iMexesOfHigherTech / (3 * (1 + iUpgradingMexCount)))
                        if iMexesOfHigherTech <= 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then iTimeThreshold = iTimeThreshold * 2 end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': Time since constructed='..(GetGameTimeSeconds() - (oMex[AiBotUnitInfo.refiTimeMexConstructed] or oMex[AiBotUnitInfo.refiTimeCreated]))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiUpgradedMexCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiUpgradedMexCount]..'; iMexesOfHigherTech='..iMexesOfHigherTech..'; iUpgradingMexCount='..iUpgradingMexCount) end
                    if GetGameTimeSeconds() - (oMex[AiBotUnitInfo.refiTimeMexConstructed] or oMex[AiBotUnitInfo.refiTimeCreated]) >= iTimeThreshold and iUpgradingMexCount < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiUpgradedMexCount] * 0.3 then
                        --Also check adjacent zones not also upgrading
                        bUpgradeDueToHowLongHadMex = true
                        local iMexesChecked = (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) --WZ uses same ref
                        if iMexesChecked < 4 then
                            local iMexesUpgrading = 0
                            if iPlateauOrZero > 0 then
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                    for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                        iMexesUpgrading = iMexesUpgrading + (tAdjLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)
                                        iMexesChecked = iMexesChecked + tAdjLZData[AiBotMap.subrefLZOrWZMexCount]
                                    end
                                end
                            else
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                                    for _, iAdjWZ in tLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                                        local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
                                        local tAdjWZTeamData = tAdjWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        iMexesUpgrading = iMexesUpgrading + (tAdjWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)
                                        iMexesChecked = iMexesChecked + tAdjWZData[AiBotMap.subrefLZOrWZMexCount]
                                    end
                                end
                            end
                            if not(iMexesUpgrading == 0 or iMexesUpgrading < math.min(3, iMexesChecked / 8)) then
                                bUpgradeDueToHowLongHadMex = false
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iMexesChecked='..iMexesChecked..'; iMexesUpgrading='..iMexesUpgrading..'; bUpgradeDueToHowLongHadMex='..tostring(bUpgradeDueToHowLongHadMex)) end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Zoen wants t1 spam='..tostring(AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam) or false)..'; Team has low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam) or false)..'; iMexTechLevel='..iMexTechLevel..'; LZ mex count='..(tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0)..'; Active mex upgrades='..(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)..'; T1 mexes in zone='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1]..'; Brain gross mass='..aiBrain[refiGrossMassBaseIncome]..'; bUpgradeDueToHowLongHadMex='..tostring(bUpgradeDueToHowLongHadMex)) end
                if not(AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam)) and (bUpgradeDueToHowLongHadMex or not(AiBotConditions.TeamHasLowMass(iTeam)) or iMexTechLevel == 3 or ((tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) >= 3 and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) == 0 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 or aiBrain[refiGrossMassBaseIncome] >= 8 or (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or (((tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbRushT3AirInAirSlot]) or aiBrain[refiOurHighestAirFactoryTech] >= 3)) or aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] >= tLZOrWZData[AiBotMap.subrefLZOrWZMexCount])))))) then

                    --Are there enough mexes that we want to consider upgrading?
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Safe to upgrade, will proceed if enoguh mexes in this zone to support an upgrade, or dealing with a 2 mex plateau, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]..'; Plateau mex count='..AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauTotalMexCount]..'; tLZOrWZTeamData[AiBotMap.refiModDistancePercent]='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Team upgrading mex count='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] or {})..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass])
                        if table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] or {}) >= 5 then
                            for iUpgradingMex, oUpgradingMex in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                                if AiBotUnitInfo.IsUnitValid(oUpgradingMex) then
                                    LOG(sFunctionRef..': iUpgradingMex='..iUpgradingMex..'; oUpgradingMex='..oUpgradingMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgradingMex)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUpgradingMex))..'; Work progress='..oUpgradingMex:GetWorkProgress())
                                else
                                    LOG(sFunctionRef..': iUpgradingMex='..iUpgradingMex..'; oUpgradingMex='..oUpgradingMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgradingMex)..'; mex is no longer valid')
                                end
                            end
                        end
                    end
                    if iMexTechLevel == 3 or
                            bUpgradeDueToHowLongHadMex or
                            tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or
                            (iPlateauOrZero > 0 and tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= math.max(2,(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauTotalMexCount] or 0) * 0.5)) or
                            (iPlateauOrZero > 0 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 and (not(AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes])) or table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) < math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / (2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] * AiBotUnitInfo.GetUnitTechLevel(oMex))))) then
                        --Do we have any active mex upgrades?
                        if bDebugMessages == true then LOG(sFunctionRef..': active mex upgrades='..(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)..'; Stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; Stalling energy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Is team table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]))..'; Gross mass for brain='..aiBrain[refiGrossMassBaseIncome])
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
                                LOG(sFunctionRef..': Number of mexes upgrading on team='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]))
                            end
                        end

                        local bDualGapAirOpeningMex = (aiBrain.AiBotDualGapRole == 'top_air'
                                or aiBrain.AiBotDualGapRole == 'bottom_air'
                                or aiBrain.AiBotDualGapRole == 'eco')
                                and iMexTechLevel == 1
                                and GetGameTimeSeconds() <= 540
                                and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) < 4
                                and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])

                        if bDualGapAirOpeningMex or (iMexTechLevel ==3 and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive)) or (AiBotConditions.TeamHasLowMass(iTeam) or (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) == 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and
                                (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) or
                                        AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) or
                                        (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 3 and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and aiBrain[refiGrossMassBaseIncome] >= 3.5 * iMexTechLevel and (iMexTechLevel == 1 or  table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.5)) or
                                        ((tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 4 or tLZOrWZData[AiBotMap.subrefLZbCoreBase]) and AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3])
                                )) then
                            --Do we have any mexes lower than this tech level? if so then dont upgrade

                            if iMexTechLevel > 1 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 or (iMexTechLevel >= 3 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] > 0)) then
                                ForkThread(ConsiderFutureMexUpgrade, oMex, 60)
                                --If this is a T2+ mex and as a team we have more than enough upgrading already then also dont upgrade unless this is a core base with no active upgrades
                            elseif not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) == 0) and not(AiBotConditions.WantAnotherT3MexUpgrade(iTeam)) then
                                ForkThread(ConsiderFutureMexUpgrade, oMex, 20) --check in a bit as we want another upgrade but once some existing ones have finished
                            elseif iMexTechLevel < 3 or AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                                --We arent stalling (or need to upgrade even if stalling), we dont have any active mex upgrades in this zone, and this mex has been alive a while - proceed with upgrade
                                if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade mex '..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..' as it has been active a while') end
                                UpgradeUnit(oMex, true)
                            end
                        else
                            --Check in a bit as we already have a mex upgrading or we are stalling resources
                            ForkThread(ConsiderFutureMexUpgrade, oMex, 20)
                        end
                    else
                        --Dont want to consider so will just rely on default logic, unless our mod dist is such that we likely failed due to temporary upgrade/eco conditions
                        if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 then
                            ForkThread(ConsiderFutureMexUpgrade, oMex, 30)
                        end
                    end
                else
                    ForkThread(ConsiderFutureMexUpgrade, oMex, 40)
                end

            else
                --Not safe to upgrade or want to focus on production for now, consider in a while
                ForkThread(ConsiderFutureMexUpgrade, oMex, 60)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderUpgradingMexDueToCompletion(oJustBuilt, oOptionalEngineer)
    --Idea - if we have just completed a mex upgrade in a zone, then look to immediately start upgrading another mex (since the one we just built should be able to help fund it); this is separate to logic considering future upgrade which is intended for the mex that has just been built to then upgrade to a higher tier after a period of time
    --oOptionalEngineer - if specified then will wait 1 tick to allow active upgrades to refresh
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderUpgradingMexDueToCompletion'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oJustBuilt) then --needed as might call this via a delay now
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code for oJustBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; Owner='..oJustBuilt:GetAIBrain().Nickname..'; oOptionalEngineer='..(oOptionalEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalEngineer) or 'nil')..'; Time='..GetGameTimeSeconds()) end
        local aiBrain = oJustBuilt:GetAIBrain()
        if not(EntityCategoryContains(categories.TECH1, oJustBuilt.UnitId)) or aiBrain[AiBotOverseer.refbPrioritiseHighTech] then
            local iTeam = aiBrain.AiBotTeam
            local iMexTechLevel = AiBotUnitInfo.GetUnitTechLevel(oJustBuilt)

            if bDebugMessages == true then LOG(sFunctionRef..': Is team stalling energy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Prioritise production for land team='..tostring(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refbPrioritiseProduction] or false)..'; Team low on mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; refiMexCountByTech='..reprs(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech])) end
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) or (iMexTechLevel >= 3 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.95) then
                local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oJustBuilt:GetPosition(), true, iTeam)
                if bDebugMessages == true then
                    local iCurPlateauOrZero, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
                    LOG(sFunctionRef..': Mex is in iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurZone='..(iCurZone or 'nil')..'; Mod dist%='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent])
                end
                --T3 mex upgrade has just completed - order mass storage around the mex immediately to benefit from the adjacency bonus, as the tick-based logic could be delayed by subrefMexCountByTech updates
                local bDualGapAirEcoRole = aiBrain.AiBotDualGapRole == 'top_air'
                        or aiBrain.AiBotDualGapRole == 'bottom_air'
                        or aiBrain.AiBotDualGapRole == 'eco'
                if iMexTechLevel >= 3 and AiBotBuilding.iLowestMassStorageTechAvailable <= 2 then
                    BuildMassStorageAroundMexDueToCompletion(oJustBuilt, oOptionalEngineer, tLZOrWZData, tLZOrWZTeamData)
                    if bDualGapAirEcoRole then
                        --The priority manager will retry this cap until all four
                        --storages exist, and only then permit the next T3 mex.
                        ForkThread(ConsiderFutureMexUpgrade, oJustBuilt, 12)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return
                    end
                end
                --Wait 1 tick if oOptionalEngineer is set and we might be on last upgrade in zone, to make sure our tracking of active upgrades is updated
                if oOptionalEngineer and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] == 1 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][iMexTechLevel] < tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] and iMexTechLevel > 1 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Waiting 1 sec so our upgrade count can update, tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]='..tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]..'; will first try updating upgrade tracking') end
                    local oMexUpgradingToThis
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oOptionalEngineer.UnitId) then
                        oMexUpgradingToThis = oOptionalEngineer
                    elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
                        for iMex, oMex in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if upgrading team mex is owned by this brain and couldve upgraded to this unit, oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..'; Assigned zone='..oMex[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]..'; Unit state='..AiBotUnitInfo.GetUnitState(oMex)..'; .Dead='..tostring(oMex.Dead or false)..'; Work progress='..oMex:GetWorkProgress()) end
                            if oMex:GetAIBrain() == aiBrain and AiBotUnitInfo.GetUnitTechLevel(oMex) == iMexTechLevel - 1 and oMex:GetBlueprint().General.UpgradesTo == oJustBuilt.UnitId and oMex.GetFocusUnit then
                                local oFocusUnit = oMex:GetFocusUnit()
                                if bDebugMessages == true then LOG(sFunctionRef..': Satisfies most conditions, oFocusUnit='..(oFocusUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit) or 'nil')) end
                                if oFocusUnit == oJustBuilt then
                                    oMexUpgradingToThis = oMex
                                    break
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oMexUpgradingToThis='..(oMexUpgradingToThis.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oMexUpgradingToThis) or 'nil')) end
                    if oMexUpgradingToThis then
                        AiBotTeam.UpdateUpgradeTrackingOfUnit(oMexUpgradingToThis, true, oJustBuilt.UnitId)
                        if bDebugMessages == true then LOG(sFunctionRef..': subrefiActiveMexUpgrades after update='..tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]) end
                    end
                    if tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] == 1 then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(10)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting 1 sec, tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]='..tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]) end
                    end
                end
                if AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refbPrioritiseProduction] and AiBotConditions.TeamHasLowMass(iTeam) and (not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or ((tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][iMexTechLevel - 1] or 0) == 0) and not(AiBotUtilities.bQuietModActive)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will call this function again in a while as we want to prioritise production at the moment') end
                    ForkThread(AiBotUtilities.DelayedFunction, 60, ConsiderUpgradingMexDueToCompletion, {oJustBuilt})
                else
                    local iMexesOnMap = table.getn(AiBotMap.tMassPoints)
                    local bTryingToUpgradeMex = false
                    if bDebugMessages == true then LOG(sFunctionRef..': tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]='..(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 'nil')..'; tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2]='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2]..'; tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) end
                    if iMexTechLevel >= 3 or
                            (iMexTechLevel > 1 or (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] >= tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] == 0) and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] > 1 or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and
                                    ((AiBotMap.iMapSize >= 1000 and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] < 2) or tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] < tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] * 0.3 or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex, oJustBuilt.UnitId) or (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 and iMexesOnMap <= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])))
                                            and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] < math.max(1, tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] * 0.5 + tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] * 0.15 + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]) or (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] <= 1 and AiBotMap.iMapSize >= 1000) or (AiBotUtilities.bLoudModActive and EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex, oJustBuilt.UnitId))))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Checkign we dont have lower tech mexes or loud/QUIET active, iMexTechLevel='..iMexTechLevel..'; AiBotUtilities.bLoudModActive='..tostring(AiBotUtilities.bLoudModActive)..'; Active mex upgrades='..tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]..'; LZ Mex count='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]..'; Gross mass income='..aiBrain[refiGrossMassBaseIncome]) end
                        if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 or AiBotUtilities.bQuietModActive or (iMexTechLevel >= 3 and (AiBotUtilities.bLoudModActive or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] > 0)) or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] == 0 and tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 3 and aiBrain[refiGrossMassBaseIncome] >= 15)  then --In LOUD, T3 mex upgrades are more efficient than t2 to t3 apparently
                            --Basic safety check (much more limited than normal one):
                            if bDebugMessages == true then LOG(sFunctionRef..': Doing safety check, is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Enemy air to ground threat='..(tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)) end
                            if (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) or ((tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 100) <= 2)) and (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 and AiBotUtilities.IsTableEmpty(oJustBuilt[AiBotBuilding.reftTMLInRangeOfThisUnit]) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) and (tLZOrWZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 then
                                --Upgrade another mex in this zone (or this mex if T3 LOUD)
                                bTryingToUpgradeMex = true
                                if iMexTechLevel >= 3 and AiBotUtilities.bLoudModActive and not((oJustBuilt:GetBlueprint().General.UpgradesTo or '') == '') then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Upgrading this unit again') end
                                    UpgradeUnit(oJustBuilt, true)
                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then --redundancy
                                    local iMexCategory

                                    if AiBotUtilities.bQuietModActive then
                                        if iMexTechLevel <= 2 then
                                            iMexCategory = AiBotUnitInfo.refCategoryT1Mex
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will look for T1 mexes') end
                                            if tbQuietT25MexUnitIds[oJustBuilt.UnitId] then
                                                if bDebugMessages == true then LOG(sFUnctionRef..': This is a T2.5 mex so including T2 mexes in mexes to consider upgrading') end
                                                iMexCategory = iMexCategory + AiBotUnitInfo.refCategoryT2Mex
                                                for sTech25, _ in tbQuietT25MexUnitIds do
                                                    iMexCategory = iMexCategory - categories[sTech25]
                                                end
                                            end
                                        else
                                            --Tech 3 mex
                                            iMexCategory = AiBotUnitInfo.refCategoryT1Mex + AiBotUnitInfo.refCategoryT2Mex
                                            if (oJustBuilt:GetBlueprint().General.UpgradesTo or '') == '' then
                                                --Likely dealing with a t3.5 mex not a t3 mex, double-check
                                                local sUpgradesFrom = oJustBuilt:GetBlueprint().General.UpgradesFrom
                                                if sUpgradesFrom and EntityCategoryContains(categories.TECH3, sUpgradesFrom) then
                                                    iMexCategory = AiBotUnitInfo.refCategoryMex - categories[oJustBuilt.UnitId]
                                                end
                                            end
                                        end
                                    else
                                        if iMexTechLevel <= 2 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will look for T1 mexes') end
                                            iMexCategory = AiBotUnitInfo.refCategoryT1Mex --i.e. if we have just upgraded a t1 mex to t2, then we want to look for other t1 mexes in the zone to upgrade
                                        else iMexCategory = AiBotUnitInfo.refCategoryMex
                                        end
                                    end

                                    local tMexOfCategory = EntityCategoryFilterDown(iMexCategory, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    local bAlreadyUpgraded = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have other mexes that could upgrade to same tech level, is tMexOfCategory empty='..tostring(AiBotUtilities.IsTableEmpty(tMexOfCategory))..'; subrefiActiveMexUpgrades='..(tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0)) end
                                    --If we have mexes of category check none are upgrading
                                    if AiBotUtilities.IsTableEmpty(tMexOfCategory) == false then
                                        for iCurMex = table.getn(tMexOfCategory), 1, -1 do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering mex='..tMexOfCategory[iCurMex].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tMexOfCategory[iCurMex])..'; Work progress='..tMexOfCategory[iCurMex]:GetWorkProgress()..'; Fraction complete='..tMexOfCategory[iCurMex]:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(tMexOfCategory[iCurMex])) end
                                            if tMexOfCategory[iCurMex]:GetWorkProgress() >= 0.05 or tMexOfCategory[iCurMex] == oOptionalEngineer then
                                                table.remove(tMexOfCategory, iCurMex)
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is tMexOfCategory empty after removing near-complete ones='..tostring(AiBotUtilities.IsTableEmpty(tMexOfCategory))) end
                                    if AiBotUtilities.IsTableEmpty(tMexOfCategory) then
                                        --if have no active upgrades in this zone, then consider searching adjacent land/water zones if they are <35% mod dist; if no mexes after this, and we are at T1-T2, then consider going to T3
                                        if (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) == 0 then
                                            local iModDistThreshold = math.max(0.35, tLZOrWZTeamData[AiBotMap.refiModDistancePercent])
                                            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
                                            if iPlateauOrZero then
                                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then --for now will only to land zones not water zones since greater risk with water zones
                                                    for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                        if tAdjLZTeamData[AiBotMap.refiModDistancePercent] <= iModDistThreshold and tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                            tMexOfCategory = EntityCategoryFilterDown(iMexCategory, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                            if AiBotUtilities.IsTableEmpty(tMexOfCategory) == false then
                                                                for iMex, oMex in tMexOfCategory do
                                                                    if AiBotUnitInfo.IsUnitValid(oMex) and oMex:GetFractionComplete() == 1 and not(oMex:IsUnitState('Upgrading')) and not(oMex:IsUnitState('BeingUpgraded')) then
                                                                        UpgradeUnit(oMex, true)
                                                                        bAlreadyUpgraded = true
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade mex in adj zone P'..iPlateauOrZero..'Z'..iAdjLZ..', oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)) end
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    if AiBotUtilities.IsTableEmpty(tMexOfCategory) and iMexTechLevel <= 2 then
                                        local bGetT3Mex = AiBotConditions.WantAnotherT3MexUpgrade(iTeam)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to get another t3 mex at this stage, bGetT3Mex='..tostring(bGetT3Mex)) end
                                        if bGetT3Mex then
                                            if bDebugMessages == true then LOG(sFunctionRef..': We want another t3 mex on our team; however will avoid upgrading multiple at once in this zone if we dont have lots of mass and lack any t3 mexes; also abort if this isnt a core base/similar mod dist then want to consider our base, subrefiActiveMexUpgrades='..tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades]) end
                                            if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] > 0.05 and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] < 10 then
                                                local tNearestBaseLZData, tNearestBaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.GetPlayerStartPosition(oJustBuilt:GetAIBrain()), true, iTeam)
                                                --Does nearest base not have many t3 mexes yet, but seems as safe as this zone?
                                                if tNearestBaseLZTeamData and tNearestBaseLZTeamData[AiBotMap.subrefMexCountByTech][3] <= 1 and tNearestBaseLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 and (tNearestBaseLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or tNearestBaseLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0) and (AiBotUtilities.IsTableEmpty(tNearestBaseLZTeamData[AiBotMap.reftoNearestDFEnemies]) or not(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))) then
                                                    bGetT3Mex = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want more t3 mex in core base first so will cancel getting a t3 mex') end
                                                end
                                            end
                                            if bGetT3Mex and aiBrain:GetEconomyStored('MASS') <= 4000 and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] > 0 and tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= math.min(3, tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': We already have a mex upgrading in this zone so wont get t3 mex unless we are upgrading from t1 to t2 with just one mex') end
                                                bGetT3Mex = false
                                                if tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] <= 1 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.TECH2, tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades])) and (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) or AiBotMap.iLowestMassStorageTechAvailable > 1 or table.getn(tLZOrWZTeamData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) < 0.5 * tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Have no t2 units upgrading in this zone, and only 1 active mex upgrade, and not lots of mass storage locations') end
                                                    bGetT3Mex = true
                                                end
                                            end
                                            if bGetT3Mex then
                                                --Consider mex of higher tech level if not already
                                                tMexOfCategory = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and find a mex to upgrade, is AiBotUtilities.IsTableEmpty(tMexOfCategory)='..tostring(AiBotUtilities.IsTableEmpty(tMexOfCategory))) end
                                    if AiBotUtilities.IsTableEmpty(tMexOfCategory) == false and not(bAlreadyUpgraded) then
                                        for iMex, oMex in tMexOfCategory do
                                            if AiBotUnitInfo.IsUnitValid(oMex) and oMex:GetFractionComplete() == 1 and not(oMex:IsUnitState('Upgrading')) and not(oMex:IsUnitState('BeingUpgraded')) and not(oMex == oJustBuilt) and not(oMex == oOptionalEngineer) and not((oMex:GetBlueprint().General.UpgradesTo or '') == '') then
                                                bAlreadyUpgraded = true
                                                UpgradeUnit(oMex, true)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade the mex '..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..' as have just compelted a mex upgrade in this zone') end
                                                break
                                            end
                                        end
                                    end
                                    if not(bAlreadyUpgraded) and AiBotUtilities.bQuietModActive and not((oJustBuilt:GetBlueprint().General.UpgradesTo or '') == '') and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) < 2 then
                                        UpgradeUnit(oJustBuilt, true)
                                        bAlreadyUpgraded = true
                                    end
                                end
                            end
                        end
                    end
                    if not(bTryingToUpgradeMex) then ForkThread(AiBotUtilities.DelayedFunction, 20, ConsiderUpgradingMexDueToCompletion, {oJustBuilt}) end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Will call this function again in a while as we arent upgrading due to low power') end
                ForkThread(AiBotUtilities.DelayedFunction, 10, ConsiderUpgradingMexDueToCompletion, {oJustBuilt})
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

local function ForceDualGapMexStorageSlot(oEngineer, oBlocker, tStorageLocation, sStorageBP)
    if not(AiBotUnitInfo.IsUnitValid(oEngineer)) then return end
    if AiBotUnitInfo.IsUnitValid(oBlocker) then
        AiBotOrders.IssueTrackedReclaim(oEngineer, oBlocker, false, 'DGClearMexCap', true, true)
        local iStopWaitingAt = GetGameTimeSeconds() + 30
        while AiBotUnitInfo.IsUnitValid(oBlocker) and GetGameTimeSeconds() < iStopWaitingAt do
            WaitSeconds(1)
        end
    end
    if AiBotUnitInfo.IsUnitValid(oEngineer) then
        AiBotOrders.IssueTrackedBuild(oEngineer, tStorageLocation, sStorageBP, false, 'DGMexStorage', true)
        AiBotEngineer.TrackEngineerAction(oEngineer, AiBotEngineer.refActionBuildMassStorage, true, 1)
    end
end

function BuildMassStorageAroundMexDueToCompletion(oMex, oOptionalEngineer, tLZOrWZData, tLZOrWZTeamData)
    --Called from ConsiderUpgradingMexDueToCompletion when we have just completed a T3 mex upgrade, so we get T1 mass storage built around the mex immediately to benefit from the adjacency bonus (the tick-based logic can be delayed as it relies on subrefMexCountByTech which only updates after a few ticks)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'BuildMassStorageAroundMexDueToCompletion'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local aiBrain = oMex:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam
    if IsDualGapAirEcoBrain(aiBrain) then
        if GetOwnMassStorageCountAroundMex(aiBrain, oMex) >= 4
                or (oMex.AiBotDualGapStorageDispatchUntil or 0) > GetGameTimeSeconds() then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for mex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..'; Owner='..aiBrain.Nickname..'; oOptionalEngineer='..(oOptionalEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalEngineer) or 'nil')..'; lowest mass storage tech='..AiBotBuilding.iLowestMassStorageTechAvailable..'; Time='..GetGameTimeSeconds()) end

    --Basic safety check (same as in ConsiderUpgradingMexDueToCompletion) - dont bother building storage if enemies are contesting this zone
    if not(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])) and (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 100) > 2 then
        if bDebugMessages == true then LOG(sFunctionRef..': Enemies contesting this zone so wont build mass storage') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end

    local bDualGapAirEcoRole = aiBrain.AiBotDualGapRole == 'top_air'
            or aiBrain.AiBotDualGapRole == 'bottom_air'
            or aiBrain.AiBotDualGapRole == 'eco'

    --Work out which engineers can help, preferring the engineer that just completed the mex upgrade
    local tEngineersToUse = {}
    if AiBotUnitInfo.IsUnitValid(oOptionalEngineer) and oOptionalEngineer:GetFractionComplete() == 1 and oOptionalEngineer:GetAIBrain() == aiBrain and EntityCategoryContains(categories.TECH1, oOptionalEngineer.UnitId) and not(EntityCategoryContains(categories.COMMAND, oOptionalEngineer.UnitId)) and AiBotConditions.IsEngineerAvailable(oOptionalEngineer, true) then
        table.insert(tEngineersToUse, oOptionalEngineer)
    end
    local tEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer * categories.TECH1, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
    if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false then
        for iUnit, oUnit in tEngineersInZone do
            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 and oUnit:GetAIBrain() == aiBrain and not(oUnit == oOptionalEngineer) and not(EntityCategoryContains(categories.COMMAND, oUnit.UnitId)) and not(oUnit:IsUnitState('Attached')) then
                table.insert(tEngineersToUse, oUnit)
            end
        end
    end
    if bDualGapAirEcoRole and table.getn(tEngineersToUse) < 6 then
        local tAllT1Engineers = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer * categories.TECH1, false) or {}
        for _, oEngineer in tAllT1Engineers do
            if table.getn(tEngineersToUse) >= 6 then break end
            local bAlreadyAdded = false
            for _, oAddedEngineer in tEngineersToUse do
                if oAddedEngineer == oEngineer then bAlreadyAdded = true break end
            end
            if not(bAlreadyAdded) and AiBotUnitInfo.IsUnitValid(oEngineer)
                    and oEngineer:GetAIBrain() == aiBrain
                    and oEngineer:GetFractionComplete() == 1
                    and not(oEngineer:IsUnitState('Attached')) then
                table.insert(tEngineersToUse, oEngineer)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tEngineersToUse) then
        if bDebugMessages == true then LOG(sFunctionRef..': No engineers available to build mass storage around mex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end

    --Determine a mass storage blueprint buildable by our engineers
    local sStorageBP
    for iEngineer, oEngineer in tEngineersToUse do
        sStorageBP = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryMassStorage, oEngineer)
        if sStorageBP then break end
    end
    if not(sStorageBP) then
        if bDebugMessages == true then LOG(sFunctionRef..': Couldnt find a mass storage blueprint buildable by our engineers, lowest mass storage tech='..AiBotBuilding.iLowestMassStorageTechAvailable) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end

    --Generate the 4 standard adjacency locations around the mex and check each is still buildable (including that no build is already queued there)
    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oMex:GetPosition())
    local tiXZOffset = {{-2,0},{0,-2},{0,2},{2,0}}
    local tMexPosition = oMex:GetPosition()
    local tStorageLocationsToBuild = {}
    for iOffset, tXZOffset in tiXZOffset do
        local tCurPos = {tMexPosition[1] + tXZOffset[1], 0, tMexPosition[3] + tXZOffset[2]}
        tCurPos[2] = GetSurfaceHeight(tCurPos[1], tCurPos[3])
        local bCanBuild = AiBotConditions.CanBuildStorageAtLocation(tCurPos)
        if bCanBuild and iLandOrWaterZone then
            bCanBuild = AiBotEngineer.CanBuildAtLocation(aiBrain, sStorageBP, tCurPos, iPlateauOrZero, iLandOrWaterZone, nil, false, true, false, false, true)
        elseif bCanBuild and aiBrain.CanBuildStructureAt then
            bCanBuild = aiBrain:CanBuildStructureAt(sStorageBP, tCurPos)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering storage location '..repru(tCurPos)..'; bCanBuild='..tostring(bCanBuild)) end
        local oBlockingStructure
        if not(bCanBuild) and bDualGapAirEcoRole then
            local tNearbyStructures = aiBrain:GetUnitsAroundPoint(categories.STRUCTURE * (categories.TECH1 + categories.TECH2)
                    - AiBotUnitInfo.refCategoryMex - AiBotUnitInfo.refCategoryMassStorage, tCurPos, 1.6, 'Ally') or {}
            for _, oStructure in tNearbyStructures do
                if AiBotUnitInfo.IsUnitValid(oStructure) and oStructure:GetAIBrain() == aiBrain then
                    oBlockingStructure = oStructure
                    break
                end
            end
        end
        if bCanBuild or oBlockingStructure then
            table.insert(tStorageLocationsToBuild, {position=tCurPos, blocker=oBlockingStructure})
        end
    end
    if AiBotUtilities.IsTableEmpty(tStorageLocationsToBuild) then
        if bDebugMessages == true then LOG(sFunctionRef..': No mass storage locations available to build around mex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end
    table.sort(tEngineersToUse, function(oEngineerA, oEngineerB)
        return AiBotUtilities.GetDistanceBetweenPositions(oEngineerA:GetPosition(), oMex:GetPosition())
                < AiBotUtilities.GetDistanceBetweenPositions(oEngineerB:GetPosition(), oMex:GetPosition())
    end)

    if bDualGapAirEcoRole then
        oMex.AiBotDualGapStorageDispatchUntil = GetGameTimeSeconds() + 30
    end

    --Four dedicated builders take one adjacency side each. Up to two further
    --engineers guard the builders, giving the requested 5-6 engineer response.
    local iLocation = 1
    for iEngineer, oEngineer in tEngineersToUse do
        local tSlot = tStorageLocationsToBuild[iLocation]
        if not(tSlot) then break end
        if bDualGapAirEcoRole then oEngineer.AiBotDualGapStorageWorkerUntil = GetGameTimeSeconds() + 60 end
        ForkThread(ForceDualGapMexStorageSlot, oEngineer, tSlot.blocker, tSlot.position, sStorageBP)
        iLocation = iLocation + 1
    end
    if bDualGapAirEcoRole and table.getn(tEngineersToUse) > table.getn(tStorageLocationsToBuild) then
        local iHelperLimit = math.min(table.getn(tEngineersToUse), table.getn(tStorageLocationsToBuild) + 2)
        for iHelper = table.getn(tStorageLocationsToBuild) + 1, iHelperLimit do
            local oBuilder = tEngineersToUse[math.mod(iHelper - 1, table.getn(tStorageLocationsToBuild)) + 1]
            AiBotOrders.IssueTrackedGuard(tEngineersToUse[iHelper], oBuilder, false, 'DGMexStorageAssist', true)
        end
    end
    if bDualGapAirEcoRole then
        LOG('AiBot Dual Gap mex cap dispatched: army='..aiBrain:GetArmyIndex()
                ..'; mex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)
                ..'; slots='..table.getn(tStorageLocationsToBuild)
                ..'; engineers='..math.min(6, table.getn(tEngineersToUse))..'; time='..GetGameTimeSeconds())
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderPowerPgenUpgrade(oUnit, iOverrideSecondsToWait)
    --Called when we have just constructed a t3 pgen that is capable of being upgraded - tries to upgrade immediately unless are stalling mass
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderPowerPgenUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTimeToWait = iOverrideSecondsToWait or 0

    if bDebugMessages == true then LOG(sFunctionRef..': About to wait '..iTimeToWait..' for oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
    if iTimeToWait > 0 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(iTimeToWait)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is oUnit still valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; oUnit[AiBotUnitInfo.refbTriedUpgrading]='..tostring(oUnit[AiBotUnitInfo.refbTriedUpgrading] or false)) end
    if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit[AiBotUnitInfo.refbTriedUpgrading]) then
        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
        local iTeam = oUnit:GetAIBrain().AiBotTeam
        local tLZOrWZData, tLZOrWZTeamData
        if iPlateauOrZero == 0 then
            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
        end

        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(2, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]))) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbPrioritiseProduction] and not(AiBotConditions.HaveLowPower(iTeam)) and AiBotConditions.HaveLowMass(iTeam)) or not(AiBotConditions.SafeToUpgradeUnit(oUnit)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Dont have enough mass or want to produce more so will delay consideration of pgen upgrade, tLZOrWZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or false)..'; Prioritise production='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbPrioritiseProduction] or false)..'; Safe to upgrade unit='..tostring(AiBotConditions.SafeToUpgradeUnit(oUnit))) end
            ForkThread(ConsiderPowerPgenUpgrade, oUnit, 10)
        else
            if not(AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam)) then
                --Wnat to upgrade pgen
                if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                UpgradeUnit(oUnit, true)
                oUnit[AiBotUnitInfo.refbTriedUpgrading] = true
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Want t1 spam so will reconsider later') end
                ForkThread(ConsiderPowerPgenUpgrade, oUnit, 10)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderMassFabUpgrade(oUnit, iOverrideSecondsToWait)
    --Called when we have just constructed a t3 mass fab that is capable of being upgraded - tries to upgrade immediately unless are stalling energy
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderMassFabUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTimeToWait = iOverrideSecondsToWait or 0

    if bDebugMessages == true then LOG(sFunctionRef..': About to consider wait '..iTimeToWait..' for oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
    if iTimeToWait > 0 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(iTimeToWait)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is oUnit still valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        local iTeam = oUnit:GetAIBrain().AiBotTeam
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbPrioritiseProduction] and (AiBotConditions.HaveLowPower(iTeam) or AiBotConditions.HaveLowMass(iTeam))) or not(AiBotConditions.SafeToUpgradeUnit(oUnit)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Dont have enough energy or want to produce more so will delay consideration of mass fab upgrade, or we are dealing with unsafe to upgrade unit') end
            ForkThread(ConsiderMassFabUpgrade, oUnit, 10)
        else
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            local tLZOrWZData, tLZOrWZTeamData
            if iPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end

            if not(AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam)) then
                --Wnat to upgrade pgen
                if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade mass fab unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                UpgradeUnit(oUnit, true)
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Want t1 spam so will reconsider later') end
                ForkThread(ConsiderMassFabUpgrade, oUnit, 10)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function JustBuiltT2PlusPowerOrExperimentalInZone(oPGen)
    --If we dont have an activem ex upgrade in the zone then will try and upgrade a mex, assuming it is safe
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'JustBuiltT2PlusPowerOrExperimentalInZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTeam = oPGen:GetAIBrain().AiBotTeam
    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oPGen:GetPosition(), true, iTeam)
    if tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] == 0 and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] then
        if  tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 and EntityCategoryContains(categories.TECH3 + categories.EXPERIMENTAL, oPGen.UnitId)) then
            if not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then
                if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 then
                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        --Get a mex in the zone to upgrade
                        local oMexToUpgrade
                        local iCurDist
                        local iClosestDist = 10000
                        function ConsiderUnits(tUnitsToConsider)
                            if AiBotUtilities.IsTableEmpty(tUnitsToConsider) == false then
                                for iUnit, oUnit in tUnitsToConsider do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])
                                        if iCurDist < iClosestDist then
                                            iClosestDist = iCurDist
                                            oMexToUpgrade = oUnit
                                        end
                                    end
                                end
                            end
                        end
                        ConsiderUnits(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT1Mex, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))
                        if not(oMexToUpgrade) then ConsiderUnits(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Mex, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) end
                        if oMexToUpgrade  then
                            if bDebugMessages == true then LOG(sFunctionRef..': Just completed oPgen='..oPGen.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPGen)..'; oMexToUpgrade='..oMexToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMexToUpgrade)) end
                            UpgradeUnit(oMexToUpgrade, true)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBestEngiToKill(oUnit)
    --If we are planning on killing oUnit, and it is T3, and we have T1 or T2 engis in the esame area, then consider switching to killing the T1/T2 unit instead
    --returns either oUnit, or the replacement engineer
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBestEngiToKill'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
    if iUnitTechLevel == 1 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return oUnit
    else
        --Dealing with T3 engineer, is there a T1/T2 in the same zone?
        local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, oUnit:GetAIBrain().AiBotTeam)
        local iSearchCategory
        if iUnitTechLevel == 2 then iSearchCategory = AiBotUnitInfo.refCategoryEngineer * categories.TECH1
        else iSearchCategory = AiBotUnitInfo.refCategoryEngineer * categories.TECH1 + AiBotUnitInfo.refCategoryEngineer * categories.TECH2
        end
        local tT1AndT2EngisInZone = EntityCategoryFilterDown(iSearchCategory, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty( tT1AndT2EngisInZone) == false then
            --The higher the priority number the less important the task
            local iLowestPriorityEngineer = -1000
            local iPrimaryBuilderPriorityAdjust = -500
            local iNoPriorityReplacement = 400
            local iTech1PriorityAdjust = 50 --i.e. treats t1 engi as having +50 to priority value
            local oLowestPriorityEngineer
            local iCurPriority
            local iOrigFaction = AiBotUnitInfo.GetUnitFaction(oUnit)
            local iCurFaction

            for iEngi, oEngi in tT1AndT2EngisInZone do
                if AiBotUnitInfo.IsUnitValid(oEngi) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering possible replacement engi, oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; Engi state='..AiBotUnitInfo.GetUnitState(oEngi)..'; Assigned priority='..(oEngi[AiBotEngineer.refiAssignedActionPriority] or 'nil')..'; Is primary builder='..tostring(oEngi[AiBotEngineer.refbPrimaryBuilder] or false)) end
                    if not(oEngi:IsUnitState('Reclaiming')) then
                        iCurPriority = (oEngi[AiBotEngineer.refiAssignedActionPriority] or iNoPriorityReplacement)
                        if oEngi[AiBotEngineer.refbPrimaryBuilder] then
                            iCurPriority = iCurPriority + iPrimaryBuilderPriorityAdjust
                        end
                        if iUnitTechLevel == 3 and AiBotUnitInfo.GetUnitTechLevel(oEngi) == 1 then iCurPriority = iCurPriority + iTech1PriorityAdjust end
                        if iCurPriority > iLowestPriorityEngineer then
                            --If it is for a different faction then check we have a factory of the new faction in this zone or higher tech engi before we kill the engi
                            iCurFaction = AiBotUnitInfo.GetUnitFaction(oEngi)
                            if iCurFaction == iOrigFaction or (iCurFaction and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory * AiBotUnitInfo.ConvertFactionToCategory(iCurFaction) + AiBotUnitInfo.refCategoryEngineer * categories.TECH3 * AiBotUnitInfo.ConvertFactionToCategory(iCurFaction), tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false) then
                                iLowestPriorityEngineer = iCurPriority
                                oLowestPriorityEngineer = oEngi
                            end
                        end
                    end
                end
            end
            if oLowestPriorityEngineer then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return oLowestPriorityEngineer
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oUnit
end

function ConsiderImmediateUpgradeOfFactory(oFactory)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderImmediateUpgradeOfFactory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(AiBotUtilities.bFAFActive) then
        local iTechLevel = AiBotUnitInfo.GetUnitTechLevel(oFactory)
        local aiBrain = oFactory:GetAIBrain()
        if iTechLevel < math.min(3, aiBrain[refiOurHighestFactoryTechLevel]) then

            if EntityCategoryContains(AiBotUnitInfo.refCategoryAirHQ, oFactory.UnitId) then
                if aiBrain[refiOurHighestAirFactoryTech] > math.min(3, iTechLevel) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade air factory immediately, oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)) end
                    UpgradeUnit(oFactory, true)
                end
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandHQ, oFactory.UnitId) then
                iCategoryWanted = AiBotUnitInfo.refCategoryLandHQ
                if iTechLevel == 1 then
                    iCategoryWanted = iCategoryWanted * categories.TECH3 + iCategoryWanted * categories.TECH2
                else iCategoryWanted = iCategoryWanted * categories.TECH3
                end

                if iCategoryWanted then
                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oFactory:GetPosition(), true, aiBrain.AiBotTeam)
                    if AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, iCategoryWanted) > 0 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade land factory immediately, oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)) end
                        UpgradeUnit(oFactory, true)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UnpausePausedMexFollowingUpgrade(oJustBuilt, bBuiltMexCanUpgrade)
    local iTeam = oJustBuilt:GetAIBrain().AiBotTeam
    if not(EntityCategoryContains(categories.TECH1, oJustBuilt.UnitId)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) == false then
            local iMexToUnpause = 1
            if not(bBuiltMexCanUpgrade) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iMexToUnpause = 2 end
            local iClosestToCompletion, oMexToUnpause, iCurProgress
            while iMexToUnpause > 0 do
                iClosestToCompletion = -1
                iMexToUnpause = iMexToUnpause - 1
                for iMex, oMex in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes] do
                    iCurProgress = oMex:GetWorkProgress()
                    if iCurProgress > iClosestToCompletion and oMex[AiBotUnitInfo.refbPaused] then
                        iClosestToCompletion = iCurProgress
                        oMexToUnpause = oMex
                    end
                end
                if oMexToUnpause then
                    AiBotUnitInfo.PauseOrUnpauseMassUsage(oMexToUnpause, false, iTeam)
                else
                    break
                end
            end

        end
    end
end

function JustBuiltSignificantPowerMonitor(iTeam, iMaxTimeToWait, iEnergyGenPerTick)
    --Called if we have built first 1-2 T2-T3 pgen on the team and want to wait more than standard 6s before resetting
    local iTimeToStopMonitoring = GetGameTimeSeconds() + iMaxTimeToWait
    if iTimeToStopMonitoring > (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeEndingActiveCheckOfLotsOfPower] or -1) then
        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeEndingActiveCheckOfLotsOfPower] = iTimeToStopMonitoring
        local iEnergyStoredAtStart = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored]
        local iAverageEnergyStoredAtStart = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]
        local iNetEnergyWanted = iEnergyGenPerTick * 0.1
        local iTimeWaited = 6
        WaitSeconds(iTimeWaited)

        while (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= iNetEnergyWanted or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] > iEnergyStoredAtStart and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > -2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < -1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < -AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4))) do
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] > iEnergyStoredAtStart or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > iAverageEnergyStoredAtStart then
                --Do nothing
            else
                break
            end
            WaitSeconds(1)
            iTimeWaited = iTimeWaited + 1
            if iTimeWaited >= iMaxTimeToWait then break end
        end
        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbJustBuiltLotsOfPower] = false
        AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeEndingActiveCheckOfLotsOfPower] = nil
    end
end

function ConsiderChangingCoreBase(aiBrain, iOriginalPlateau, iOriginalZone)
    --Assumed has been called after our air fac (generlaly) or last land fac in a core base or override base in the zone was destroyed, suggesting core base is in trouble
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderChangingCoreBase'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if aiBrain.AiBotAI then
        local iTeam = aiBrain.AiBotTeam
        local tOrigLZData = AiBotMap.tAllPlateaus[iOriginalPlateau][AiBotMap.subrefPlateauLandZones][iOriginalZone]
        local tOrigLZTeamData = tOrigLZData[AiBotMap.subrefLZTeamData][iTeam]
        local bLookForDifferentZone = false
        local iNewBasePlateau, iNewBaseLandZone
        local iSValueWanted
        if bDebugMessages == true then LOG(sFunctionRef..': About to start loop for aiBrain='..aiBrain.Nickname..'; refiOurHighestAirFactoryTech='..aiBrain[refiOurHighestAirFactoryTech]..'; iOriginalPlateau='..iOriginalPlateau..'; iOriginalZone='..iOriginalZone..'; subrefiActiveAiBotBrainCount='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Time='..GetGameTimeSeconds()..'; aiBrain[refbActiveCoreBaseReassessment]='..tostring(aiBrain[refbActiveCoreBaseReassessment] or false)) end
        if not(aiBrain[refbActiveCoreBaseReassessment]) then
            aiBrain[refbActiveCoreBaseReassessment] = true
            while aiBrain[refiOurHighestAirFactoryTech] == 0 do
                --Only consider changing if we lack land facts in our core base
                if bDebugMessages == true then LOG(sFunctionRef..': Start of loop, subrefiActiveAiBotBrainCount='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Time='..GetGameTimeSeconds()) end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] <= 1 then
                    bLookForDifferentZone = true
                    if AiBotUtilities.IsTableEmpty(tOrigLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have no units in orig base so will look for alternative') end
                    else
                        local tFactoriesInCoreZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tOrigLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tFactoriesInCoreZone) == false then
                            for iFactory, oFactory in tFactoriesInCoreZone do
                                if not(oFactory.Dead) and oFactory:GetFractionComplete() == 1 and oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iOriginalZone then
                                    if bDebugMessages == true then LOG(sFunctionRef..': We still have a constructed factory in the old core base, oFactory='..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..'; reftAssignedPlateauAndLandZoneByTeam='..repru(oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam])) end
                                    bLookForDifferentZone = false
                                    break
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bLookForDifferentZone='..tostring(bLookForDifferentZone)..'; time='..GetGameTimeSeconds()) end
                    if bLookForDifferentZone then
                        iSValueWanted = (tOrigLZTeamData[AiBotMap.subrefLZSValue] or 0)
                        local toLandFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, false, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': is toLandFactories empty='..tostring(AiBotUtilities.IsTableEmpty(toLandFactories))) end
                        if AiBotUtilities.IsTableEmpty(toLandFactories) == false then
                            local tbZoneConsideredByPlateau = {}
                            tbZoneConsideredByPlateau[iOriginalPlateau] = {}
                            tbZoneConsideredByPlateau[iOriginalPlateau][iOriginalZone] = true
                            local iCurPlateau, iCurZone

                            for iFactory, oFactory in toLandFactories do
                                iCurPlateau = oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                                iCurZone = oFactory[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                                if not(tbZoneConsideredByPlateau[iCurPlateau]) then tbZoneConsideredByPlateau[iCurPlateau] = {} end
                                if not(tbZoneConsideredByPlateau[iCurPlateau][iCurZone]) then
                                    tbZoneConsideredByPlateau[iCurPlateau][iCurZone] = true
                                    local tCurLZData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurZone]
                                    local tCurLZTeamData = tCurLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurPlateau='..iCurPlateau..'; iCurZone='..iCurZone..'; iSValueWanted='..iSValueWanted..'; subrefLZSValue='..tCurLZTeamData[AiBotMap.subrefLZSValue]..'; subrefLZTThreatAllyCombatTotal='..tCurLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]..'; refiEnemyAirToGroundThreat='..tCurLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; subrefMexCountByTech='..repru(tCurLZTeamData[AiBotMap.subrefMexCountByTech])..'; tCurLZData[AiBotMap.subrefLZOrWZMexCount]='..tCurLZData[AiBotMap.subrefLZOrWZMexCount]..'; subrefTThreatEnemyCombatTotal='..tCurLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]) end
                                    if tCurLZTeamData[AiBotMap.subrefLZSValue] > iSValueWanted and ((tCurLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) == 0 or tCurLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 5 < tCurLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]) and ((tCurLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 or tCurLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 10 < tCurLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) and (iSValueWanted <= 50 or tCurLZTeamData[AiBotMap.subrefMexCountByTech][1] + tCurLZTeamData[AiBotMap.subrefMexCountByTech][2] + tCurLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tCurLZData[AiBotMap.subrefLZOrWZMexCount]) then
                                        iSValueWanted = tCurLZTeamData[AiBotMap.subrefLZSValue]
                                        iNewBasePlateau = iCurPlateau
                                        iNewBaseLandZone = iCurZone
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have a new plateau and zone to call our base') end
                                    end
                                end
                            end
                            if iNewBasePlateau and iNewBaseLandZone then break end
                        end
                    end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(30)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                if bDebugMessages == true then LOG(sFunctionRef..': About to restart loop, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; refiOurHighestAirFactoryTech='..aiBrain[refiOurHighestAirFactoryTech]..'; Time='..GetGameTimeSeconds()) end
            end
            if iNewBasePlateau and iNewBaseLandZone then
                local tNewLZData = AiBotMap.tAllPlateaus[iNewBasePlateau][AiBotMap.subrefPlateauLandZones][iNewBaseLandZone]
                local tNewLZTeamData = tNewLZData[AiBotMap.subrefLZTeamData][iTeam]

                tNewLZTeamData[AiBotMap.subrefbCoreBaseOverride] = true
                --Clear override flag from old (but not the actual core zone flag just in case we could get into a situation with no core zone)
                tOrigLZTeamData[AiBotMap.subrefbCoreBaseOverride] = nil
                if bDebugMessages == true then LOG(sFunctionRef..': have flagged for iNewBasePlateau='..iNewBasePlateau..'iNewBaseLandZone='..iNewBaseLandZone..' to be a core base, removed flag from iOriginalPlateau='..iOriginalPlateau..'; iOriginalZone='..iOriginalZone) end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': End of monitoring, Time='..GetGameTimeSeconds()) end
            aiBrain[refbActiveCoreBaseReassessment] = false
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpgradeToT3LandOnceHaveLotsOfSupportFactories(aiBrain, tLZTeamData)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpgradeToT3LandOnceHaveLotsOfSupportFactories'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(aiBrain[refbLandSupportFactoryUpgradeMonitor]) and not(aiBrain[AiBotOverseer.refbPrioritiseLowTech]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and not(aiBrain[AiBotOverseer.refbPrioritiseAir]) then
        --Find HQ
        local oT2LandHQInZone
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tT2HQsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandHQ * categories.TECH2, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tT2HQsInZone) == false then
                for iHQ, oHQ in tT2HQsInZone do
                    oT2LandHQInZone = oHQ
                    break
                end
            end
        end
        if oT2LandHQInZone then
            aiBrain[refbLandSupportFactoryUpgradeMonitor] = true
            local iTeam = aiBrain.AiBotTeam
            local bUpgradeHQUnlessAlreadyGotHQUpgrading
            local bGivenUpgradeOrder
            while AiBotUnitInfo.IsUnitValid(oT2LandHQInZone) and aiBrain[refiOurHighestLandFactoryTech] == 2 do
                local tSupportFactoriesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory * categories.SUPPORTFACTORY * categories.TECH2, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tSupportFactoriesInZone) == false then
                    local iCurSupportFactories = table.getn(tSupportFactoriesInZone)
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurSupportFactories='..iCurSupportFactories..'; Time='..GetGameTimeSeconds()) end
                    if iCurSupportFactories >= 3 then
                        for iFactory, oFactory in tSupportFactoriesInZone do
                            if oFactory:GetFractionComplete() < 1 then iCurSupportFactories = iCurSupportFactories - 1 end
                        end
                        if iCurSupportFactories >= 6 then
                            bUpgradeHQUnlessAlreadyGotHQUpgrading = true
                        elseif iCurSupportFactories >= 5 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                            bUpgradeHQUnlessAlreadyGotHQUpgrading = true
                        elseif not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
                            if not(AiBotConditions.TeamHasLowMass(iTeam)) or (AiBotConditions.HaveEnoughGrossEcoToSupportLandHQUpgrade(aiBrain, 2) and (iCurSupportFactories >= 4 or oT2LandHQInZone[AiBotFactory.refiTotalBuildCount] >= 10 or AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryMobileDFLand * categories.TECH2 + AiBotUnitInfo.refCategoryIndirectT2Plus) >= 15)) then
                                bUpgradeHQUnlessAlreadyGotHQUpgrading = true
                            end
                        end
                    end
                end
                if bUpgradeHQUnlessAlreadyGotHQUpgrading then
                    --basic check that we have enough eco to support
                    if aiBrain[refiGrossMassBaseIncome] >= 9 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4 or tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 or (not(AiBotConditions.TeamHasLowMass(iTeam)) and aiBrain[refiGrossMassBaseIncome] >= 5) then
                        local iSearchCategory
                        if AiBotConditions.TeamHasLowMass(iTeam) or AiBotConditions.HaveLowPower(iTeam) then iSearchCategory = AiBotUnitInfo.refCategoryLandFactory * categories.TECH2 + AiBotUnitInfo.refCategoryAirFactory * categories.TECH2
                        else iSearchCategory = AiBotUnitInfo.refCategoryLandFactory * categories.TECH2
                        end
                        if not(AiBotTeam.DoesBrainHaveActiveHQUpgradesOfCategory(aiBrain, iSearchCategory, false)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade from T2 to T3') end
                            UpgradeUnit(oT2LandHQInZone, true, nil)
                            bGivenUpgradeOrder = true
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitSeconds(60)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            break
                        end
                    end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

            end
            aiBrain[refbLandSupportFactoryUpgradeMonitor] = nil
        end
    end
end
